// ── Order snapshot — saves full Shopify order data to order_meta ──────────────
// Called on every orders/create + orders/updated webhook so DB is always current.
// Callers that need customer/address/items data read from here instead of hitting Shopify live.
async function snapshotOrder(payload) {
  if (!mdb || !payload?.id) return;
  const sid = String(payload.id);
  const rawPhone = payload.shipping_address?.phone || payload.billing_address?.phone || payload.phone || '';
  const phone = rawPhone.replace(/\D/g,'').replace(/^91/,'').slice(-10);
  const customerName = payload.shipping_address
    ? `${payload.shipping_address.first_name||''} ${payload.shipping_address.last_name||''}`.trim()
    : payload.customer ? `${payload.customer.first_name||''} ${payload.customer.last_name||''}`.trim() : '';
  const items = (payload.line_items || []).map(li => ({
    line_item_id: li.id, product_id: li.product_id, variant_id: li.variant_id,
    title: li.title, variant_title: li.variant_title, sku: li.sku,
    qty: li.quantity, price: li.price, vendor: li.vendor || '',
  }));
  const vendors = [...new Set(items.map(i => i.vendor).filter(Boolean))];
  const fulfillments = (payload.fulfillments || []).map(f => ({
    tracking_number: f.tracking_number || '',
    tracking_url: f.tracking_url || '',
    tracking_company: f.tracking_company || '',
    shipment_status: f.shipment_status || '',
    // store which line_item ids belong to this fulfillment so vendorStages can be derived without Shopify
    line_item_ids: (f.line_items || []).map(li => li.id),
  }));
  const shipping_charge = parseFloat(
    payload.total_shipping_price_set?.shop_money?.amount ||
    (payload.shipping_lines || []).reduce((s, l) => s + parseFloat(l.price || 0), 0) ||
    0
  );

  // Derive payment_type and advance_paid directly from Shopify financial data
  // so partial orders are captured even without a "99 partial" tag.
  // applyTagMappings may overwrite advance_paid with a tag-based value later.
  const snapPayType = paymentTypeFromFinancial(payload.financial_status);
  const snapFields = { payment_type: snapPayType };
  if (snapPayType === 'partial') {
    const totalOutstanding = parseFloat(payload.total_outstanding || 0);
    const totalPrice = parseFloat(payload.total_price || 0);
    const advance = parseFloat((totalPrice - totalOutstanding).toFixed(2));
    if (advance > 0) snapFields.advance_paid = advance;
  }

  await OM.upsert(sid, {
    order_name: payload.name || '',
    customer_name: customerName,
    customer_email: (payload.email || '').toLowerCase().trim(),
    customer_phone: phone,
    shipping_address: payload.shipping_address || null,
    financial_status: payload.financial_status || '',
    fulfillment_status: payload.fulfillment_status || null,
    total_price: payload.total_price || '0.00',
    subtotal_price: payload.subtotal_price || '0.00',
    currency: payload.currency || 'INR',
    tags: payload.tags || '',
    items,
    vendors,
    fulfillments,
    shipping_charge,
    shopify_created_at: payload.created_at || null,
    shopify_updated_at: payload.updated_at || null,
    snapshot_at: new Date().toISOString(),
    ...snapFields,
  });
}

// Reconstruct a Shopify-shaped order stub from an order_meta snapshot.
// Used to pass into buildOrderPayload without a live API call.
function orderStubFromMeta(meta) {
  const nameParts = (meta.customer_name || '').trim().split(' ');
  return {
    id: meta.shopify_id,
    name: meta.order_name,
    email: meta.customer_email || '',
    phone: meta.customer_phone || '',
    customer: meta.customer_name ? { first_name: nameParts[0] || '', last_name: nameParts.slice(1).join(' ') || '' } : null,
    shipping_address: meta.shipping_address || null,
    billing_address: null,
    financial_status: meta.financial_status || '',
    fulfillment_status: meta.fulfillment_status || null,
    total_price: meta.total_price || '0.00',
    currency: meta.currency || 'INR',
    created_at: meta.shopify_created_at || null,
    tags: meta.tags || '',
    line_items: (meta.items || []).map(i => ({
      id: i.line_item_id, product_id: i.product_id, variant_id: i.variant_id,
      title: i.title, variant_title: i.variant_title, sku: i.sku,
      quantity: i.qty, price: i.price, vendor: i.vendor || '',
    })),
    fulfillments: (meta.fulfillments || []).map(f => ({
      tracking_number: f.tracking_number,
      tracking_url: f.tracking_url,
      tracking_company: f.tracking_company,
      shipment_status: f.shipment_status || '',
      // translate stored line_item_ids back to line_items shape vendorStagesFromFulfillments expects
      line_items: (f.line_item_ids || []).map(id => ({ id })),
    })),
  };
}

const OVS = {
  async upsert(shopify_id, vendor_name, fields, { respectManualOverride = false, respectStageOrder = false } = {}) {
    const sid = String(shopify_id);
    const existing = await mdb.collection('order_vendor_stage').findOne(
      { shopify_id: sid, vendor_name },
      { projection: { stage: 1, dispatched_at: 1, stage_history: 1, manually_overridden: 1, _id: 0 } }
    );

    // If admin has manually locked this vendor's stage, automated systems must not overwrite it
    if (respectManualOverride && existing?.manually_overridden) return;

    // Automated syncs must never downgrade a stage — e.g. a NOT_PICKED event after
    // a transit scan should not rewind the stage back to pickup.
    if (fields.stage && respectStageOrder && existing?.stage) {
      fields = { ...fields, stage: higherStage(existing.stage, fields.stage) };
    }

    // Capture dispatch timestamp the first time an order moves from a
    // pre-dispatch stage (new/confirmed/partial) into a dispatched stage.
    // Used to measure dispatch turnaround time (stage_started_at → dispatched_at).
    const DISPATCHED_STAGES = new Set(['ready','pickup','transit','ofd','delivered','rto']);
    if (fields.stage && DISPATCHED_STAGES.has(fields.stage)) {
      const wasPreDispatch = !existing || ['new','confirmed','partial'].includes(existing.stage);
      if (wasPreDispatch && !existing?.dispatched_at) {
        fields = { ...fields, dispatched_at: Date.now() };
      }
    }

    // Log every distinct stage transition with a timestamp — this is the
    // generic history we mine later for avg time-in-stage, avg total
    // delivery time, avg transit time etc. Only append when the stage
    // actually changes (avoid duplicate entries on no-op upserts that just
    // update other fields like awb/courier without changing stage).
    let stageHistoryUpdate = {};
    if (fields.stage && fields.stage !== existing?.stage) {
      const history = Array.isArray(existing?.stage_history) ? existing.stage_history : [];
      stageHistoryUpdate = { stage_history: [...history, { stage: fields.stage, at: Date.now() }].slice(-25) };
    }

    await mdb.collection('order_vendor_stage').updateOne(
      { shopify_id: sid, vendor_name },
      { $set: { shopify_id: sid, vendor_name, ...fields, ...stageHistoryUpdate, _updated: new Date() } },
      { upsert: true }
    );
  },
};

