// ── GET /admin/reports/product-analytics ─────────────────────────────────
app.get('/admin/reports/product-analytics', adminAuth, async (req, res) => {
  try {
    const { vendor = '', days = '30', search = '' } = req.query;
    const daysInt = parseInt(days);
    const since = daysInt > 0 ? new Date(Date.now() - daysInt * 24 * 3600 * 1000).toISOString() : null;

    // Query order_meta — uses shopify_created_at for date field
    const vendorReLP = vendor ? new RegExp(`^${vendor.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}$`, 'i') : null;
    const matchQ = since ? { shopify_created_at: { $gte: since } } : {};
    const orders = await mdb.collection('order_meta').find(matchQ, {
      projection: { shopify_id: 1, items: 1, stage: 1 }
    }).toArray();

    // Build stage map from order_vendor_stage (authoritative source)
    // { shopify_id: { vendor_name_lower: stage } }
    const ovsQ = since ? { updated_at: { $gte: since } } : {};
    if (vendor) ovsQ.vendor_name = { $regex: vendorReLP };
    const ovsAll = await mdb.collection('order_vendor_stage').find(
      vendor ? ovsQ : {},
      { projection: { shopify_id: 1, vendor_name: 1, stage: 1, _id: 0 } }
    ).toArray();
    const stageMap = {}; // { shopify_id: { vendor_lower: stage } }
    for (const s of ovsAll) {
      if (!stageMap[s.shopify_id]) stageMap[s.shopify_id] = {};
      stageMap[s.shopify_id][(s.vendor_name || '').toLowerCase()] = s.stage;
    }

    // Aggregate per product title
    const prodMap = {};
    for (const o of orders) {
      const sid = o.shopify_id;
      for (const item of (o.items || [])) {
        if (!item.title) continue;
        if (vendorReLP && item.vendor && !vendorReLP.test(item.vendor)) continue;
        const key = item.title.trim();
        if (search && !key.toLowerCase().includes(search.toLowerCase())) continue;
        if (!prodMap[key]) prodMap[key] = { name: key, vendor: item.vendor || '', image: '', units: 0, revenue: 0, delivered: 0, rto: 0, cancelled: 0 };
        const qty = item.qty || item.quantity || 1;
        prodMap[key].units += qty;
        prodMap[key].revenue += parseFloat(item.price || 0) * qty;
        // Stage: look up order_vendor_stage first, fall back to order_meta.stage
        const itemVendorLower = (item.vendor || '').toLowerCase();
        const stage = (stageMap[sid] && (stageMap[sid][itemVendorLower] || Object.values(stageMap[sid])[0])) || o.stage || 'new';
        if (stage === 'delivered') prodMap[key].delivered += qty;
        else if (stage === 'rto') prodMap[key].rto += qty;
        else if (stage === 'cancelled') prodMap[key].cancelled += qty;
      }
    }

    // Enrich with pixel images where order image missing
    const names = Object.keys(prodMap).slice(0, 60);
    if (names.length) {
      const escR = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const pxDocs = await mdb.collection('pixel_events').aggregate([
        { $match: { productName: { $regex: names.map(escR).join('|'), $options: 'i' }, productImage: { $exists: true, $ne: '' } } },
        { $group: { _id: '$productName', image: { $last: '$productImage' } } },
      ]).toArray().catch(() => []);
      for (const px of pxDocs) {
        const match = names.find(n => n.toLowerCase() === (px._id || '').toLowerCase());
        if (match && !prodMap[match].image) prodMap[match].image = px.image;
      }
    }

    const sorted = Object.values(prodMap)
      .sort((a, b) => b.units - a.units)
      .slice(0, search ? 100 : 50)
      .map(p => ({
        ...p,
        revenue: parseFloat(p.revenue.toFixed(2)),
        deliveryRate: p.units ? Math.round(p.delivered / p.units * 100) : null,
        rtoRate:      p.units ? Math.round(p.rto      / p.units * 100) : null,
        cancelRate:   p.units ? Math.round(p.cancelled / p.units * 100) : null,
      }));

    res.json({ products: sorted, total: sorted.length, vendor, days: parseInt(days), search });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ══════════════════════════════════════════════════════════════════════════
// PATTERN INTELLIGENCE — autonomous anomaly + trend detection
// Finds things nobody asked it to look for: regional tag clusters, dispatch
// drift, RTO hotspots, vendors quietly drifting worse, confirm-without-ship
// regions, repeat-RTO customers, weekday RTO skew. Runs every 3 days and
// emails a digest; also triggerable on demand.
// ══════════════════════════════════════════════════════════════════════════

const PI_RUN_EVERY_DAYS    = 3;
const PI_CURRENT_DAYS      = 7;   // "this week" window
const PI_BASELINE_DAYS     = 30;  // trailing baseline window, ending where current window starts
const PI_LOOKBACK_DAYS     = 90;  // total dataset pulled, for weekday/repeat-customer patterns
const PI_MIN_SAMPLE        = 4;   // ignore any bucket smaller than this — avoids noise from 1-2 order flukes

function pctSafe(n, d) { return d > 0 ? (n / d) * 100 : 0; }
function hoursBetween(a, b) { return (b - a) / 3600000; }

async function buildPatternDataset(days) {
  const fromISO = new Date(Date.now() - days * 24 * 3600 * 1000).toISOString();
  const orders = await fetchAllOrders("any", fromISO);
  const metasArr = await mdb.collection('order_meta').find({}, { projection: { _id: 0 } }).toArray();
  const metaMap = Object.fromEntries(metasArr.map(m => [m.shopify_id, m]));
  const vsArr = await mdb.collection('order_vendor_stage').find({}, { projection: { _id: 0 } }).toArray();
  const vsMap = {};
  vsArr.forEach(r => { (vsMap[r.shopify_id] ||= []).push(r); });
  const PI_SO = ['new','hold','confirmed','partial','ready','pickup','transit','ofd','delivered','rto','cancelled'];
  const piEffStage = (sid, meta) => {
    const ms = meta.stage || 'new'; let best = PI_SO.indexOf(ms); if (best < 0) best = 0;
    (vsMap[sid] || []).forEach(r => { const vi = PI_SO.indexOf(r.stage); if (vi > best) best = vi; });
    return PI_SO[best] || ms;
  };

  return orders.map(o => {
    const sid = String(o.id);
    const meta = metaMap[sid] || {};
    const addr = o.shipping_address || {};
    return {
      id: sid,
      name: o.name,
      created_at: o.created_at,
      created_ms: new Date(o.created_at).getTime(),
      stage: piEffStage(sid, meta),
      tags: (o.tags || '').split(',').map(t => t.trim()).filter(Boolean),
      vendors: [...new Set((o.line_items || []).map(li => li.vendor).filter(Boolean))],
      state: addr.province || 'Unknown',
      city: (addr.city || 'Unknown').trim(),
      phone: (addr.phone || o.phone || '').replace(/\D/g, '').slice(-10) || null,
      email: o.email || null,
      customerName: addr.name || `${o.customer?.first_name||''} ${o.customer?.last_name||''}`.trim() || null,
      cancelled_at: o.cancelled_at || null,
      financial_status: o.financial_status,
      vendorStages: vsMap[sid] || [],
      line_items: (o.line_items || []).map(li => ({
        title: li.title || 'Unknown Product',
        vendor: li.vendor || '',
        qty: li.quantity || 1,
        price: parseFloat(li.price) || 0,
        product_id: li.product_id ? String(li.product_id) : null,
      })),
    };
  });
}

function piWindow(dataset, startMs, endMs) {
  return dataset.filter(o => o.created_ms >= startMs && o.created_ms < endMs);
}

// ── Individual analyzers — each returns an array of finding objects ────────

function analyzeDispatchTime(current, baseline, currentDays = PI_CURRENT_DAYS, baselineDays = PI_BASELINE_DAYS) {
  const avgDispatchHrs = (rows) => {
    const hrs = [];
    rows.forEach(o => o.vendorStages.forEach(vs => {
      if (vs.dispatched_at && vs.stage_started_at && vs.dispatched_at > vs.stage_started_at) {
        hrs.push(hoursBetween(vs.stage_started_at, vs.dispatched_at));
      }
    }));
    return hrs.length >= PI_MIN_SAMPLE ? { avg: hrs.reduce((a,b)=>a+b,0)/hrs.length, count: hrs.length } : null;
  };
  const cur = avgDispatchHrs(current);
  const base = avgDispatchHrs(baseline);
  if (!cur || !base) return [];
  const change = ((cur.avg - base.avg) / base.avg) * 100;
  if (Math.abs(change) < 15) return [];
  const worse = change > 0;
  return [{
    category: 'Dispatch Speed',
    severity: change >= 40 ? 'red' : 'amber',
    title: `Avg dispatch time has ${worse ? 'risen' : 'fallen'} from ${base.avg.toFixed(0)}h to ${cur.avg.toFixed(0)}h`,
    detail: `Based on ${base.count} baseline shipments (trailing ${baselineDays}d) vs ${cur.count} in the current ${currentDays}d window. ${worse ? 'Orders are taking longer to leave the warehouse — worth a look.' : 'Dispatch speed has improved — whatever changed, keep doing it.'}`,
  }];
}

// Routine workflow tags applied to nearly every order in the normal course of
// business — clustering by region is meaningless noise for these, since
// they're not signals of a problem, just a status marker. Anything matching
// is excluded from the regional-cluster scan.
const PI_NOISE_TAG_PATTERNS = [/forwarded/i, /order confirmed/i, /^confirmed$/i];
function piIsNoiseTag(tag) { return PI_NOISE_TAG_PATTERNS.some(re => re.test(tag)); }

function analyzeTagRegionAnomalies(current) {
  const totalOrders = current.length;
  if (totalOrders < 10) return [];
  const totalByState = {};
  current.forEach(o => { totalByState[o.state] = (totalByState[o.state] || 0) + 1; });

  const tagCounts = {}; // tag -> total count
  const tagByState = {}; // tag -> { state: count }
  current.forEach(o => o.tags.filter(t => !piIsNoiseTag(t)).forEach(tag => {
    tagCounts[tag] = (tagCounts[tag] || 0) + 1;
    (tagByState[tag] ||= {})[o.state] = (tagByState[tag][o.state] || 0) + 1;
  }));

  const findings = [];
  for (const [tag, total] of Object.entries(tagCounts)) {
    if (total < 5) continue; // need enough occurrences of the tag itself
    for (const [state, count] of Object.entries(tagByState[tag])) {
      if (count < PI_MIN_SAMPLE || state === 'Unknown') continue;
      const expectedShare = totalByState[state] / totalOrders;
      const actualShare = count / total;
      if (actualShare >= expectedShare * 2.2) {
        findings.push({
          category: 'Regional Tag Cluster',
          severity: actualShare >= expectedShare * 3.5 ? 'red' : 'amber',
          title: `"${tag}" is disproportionately coming from ${state}`,
          detail: `${count} of ${total} orders tagged "${tag}" this week are from ${state}, which only accounts for ${expectedShare.toFixed(0) === '0' ? '<1' : (expectedShare*100).toFixed(0)}% of total order volume — about ${(actualShare/expectedShare).toFixed(1)}× its expected share.`,
          strength: actualShare / expectedShare,
        });
      }
    }
  }
  return findings.sort((a,b) => b.strength - a.strength).slice(0, 6);
}

function analyzeRTOHotspots(current) {
  const terminal = current.filter(o => ['delivered', 'rto'].includes(o.stage));
  if (terminal.length < 10) return [];
  const overallRtoRate = pctSafe(terminal.filter(o => o.stage === 'rto').length, terminal.length);

  const byKey = (keyFn) => {
    const map = {};
    terminal.forEach(o => {
      const k = keyFn(o);
      if (k === 'Unknown') return;
      (map[k] ||= { total: 0, rto: 0 }).total++;
      if (o.stage === 'rto') map[k].rto++;
    });
    return map;
  };

  const findings = [];
  for (const [label, keyFn] of [['state', o => o.state], ['city', o => o.city]]) {
    const map = byKey(keyFn);
    for (const [name, v] of Object.entries(map)) {
      if (v.total < PI_MIN_SAMPLE) continue;
      const rate = pctSafe(v.rto, v.total);
      if (rate >= Math.max(overallRtoRate * 1.6, overallRtoRate + 20) && rate >= 30) {
        findings.push({
          category: 'RTO Hotspot',
          severity: rate >= 50 ? 'red' : 'amber',
          title: `${name} (${label}) RTO rate is ${rate.toFixed(0)}% — overall average is ${overallRtoRate.toFixed(0)}%`,
          detail: `${v.rto} of ${v.total} delivered/RTO orders from ${name} came back as RTO this week.`,
          strength: rate,
        });
      }
    }
  }
  return findings.sort((a,b) => b.strength - a.strength).slice(0, 6);
}

function analyzeConfirmNotComplete(current) {
  const stuckCandidates = current.filter(o => ['confirmed', 'partial'].includes(o.stage));
  const nowMs = Date.now();
  const stuck = stuckCandidates.filter(o => hoursBetween(o.created_ms, nowMs) >= 5 * 24);
  if (stuck.length < PI_MIN_SAMPLE) return [];

  const totalByState = {};
  current.forEach(o => { totalByState[o.state] = (totalByState[o.state] || 0) + 1; });
  const overallStuckRate = pctSafe(stuck.length, current.length);

  const stuckByState = {};
  stuck.forEach(o => { stuckByState[o.state] = (stuckByState[o.state] || 0) + 1; });

  const findings = [];
  for (const [state, count] of Object.entries(stuckByState)) {
    if (count < PI_MIN_SAMPLE || state === 'Unknown') continue;
    const stateTotal = totalByState[state] || 0;
    if (stateTotal < PI_MIN_SAMPLE) continue;
    const rate = pctSafe(count, stateTotal);
    if (rate >= Math.max(overallStuckRate * 2, overallStuckRate + 20)) {
      findings.push({
        category: 'Confirmed but Stuck',
        severity: rate >= 60 ? 'red' : 'amber',
        title: `${state}: customers confirm but orders aren't shipping`,
        detail: `${count} of ${stateTotal} orders from ${state} (${rate.toFixed(0)}%) have sat in "confirmed/partial" for 5+ days without dispatch — vs ${overallStuckRate.toFixed(0)}% overall. Customers are saying yes, fulfilment isn't following through.`,
        strength: rate,
      });
    }
  }
  return findings.sort((a,b) => b.strength - a.strength).slice(0, 5);
}

function analyzeVendorOutliers(current) {
  const vendorStats = {};
  current.forEach(o => o.vendors.forEach(vn => {
    const v = vendorStats[vn] ||= { total: 0, rto: 0, dispatchHrs: [] };
    v.total++;
    if (o.stage === 'rto') v.rto++;
    const myStage = o.vendorStages.find(vs => vs.vendor_name === vn);
    if (myStage?.dispatched_at && myStage?.stage_started_at && myStage.dispatched_at > myStage.stage_started_at) {
      v.dispatchHrs.push(hoursBetween(myStage.stage_started_at, myStage.dispatched_at));
    }
  }));

  const rtoRates = Object.values(vendorStats).filter(v=>v.total>=PI_MIN_SAMPLE).map(v => pctSafe(v.rto, v.total));
  const overallRto = rtoRates.length ? rtoRates.reduce((a,b)=>a+b,0)/rtoRates.length : 0;
  const allDispatchHrs = Object.values(vendorStats).flatMap(v=>v.dispatchHrs);
  const overallDispatch = allDispatchHrs.length ? allDispatchHrs.reduce((a,b)=>a+b,0)/allDispatchHrs.length : 0;

  const findings = [];
  for (const [vn, v] of Object.entries(vendorStats)) {
    if (v.total < PI_MIN_SAMPLE) continue;
    const rate = pctSafe(v.rto, v.total);
    if (overallRto > 0 && rate >= Math.max(overallRto * 1.8, overallRto + 20) && rate >= 25) {
      findings.push({
        category: 'Vendor Watchlist',
        severity: rate >= 45 ? 'red' : 'amber',
        title: `${vn}: RTO rate ${rate.toFixed(0)}% vs ${overallRto.toFixed(0)}% marketplace average`,
        detail: `${v.rto} of ${v.total} orders from ${vn} this week came back RTO.`,
        strength: rate,
      });
    }
    if (v.dispatchHrs.length >= PI_MIN_SAMPLE && overallDispatch > 0) {
      const avgHrs = v.dispatchHrs.reduce((a,b)=>a+b,0)/v.dispatchHrs.length;
      if (avgHrs >= Math.max(overallDispatch * 1.6, overallDispatch + 18)) {
        findings.push({
          category: 'Vendor Watchlist',
          severity: avgHrs >= overallDispatch * 2.2 ? 'red' : 'amber',
          title: `${vn}: dispatching in ${avgHrs.toFixed(0)}h vs ${overallDispatch.toFixed(0)}h marketplace average`,
          detail: `Slowest dispatch turnaround among active vendors this week, based on ${v.dispatchHrs.length} shipments.`,
          strength: avgHrs,
        });
      }
    }
  }
  return findings.sort((a,b) => b.strength - a.strength).slice(0, 6);
}

// ── Product-level analyzers ─────────────────────────────────────────────────

function analyzeProductDispatchDelay(current) {
  // Per vendor, compare each product's avg dispatch time against that same
  // vendor's overall average — catches "this SKU takes 24h longer than your
  // other products" without needing a marketplace-wide baseline per product.
  const vendorProductHrs = {};
  const vendorAllHrs = {};
  current.forEach(o => {
    o.vendorStages.forEach(vs => {
      if (!(vs.dispatched_at && vs.stage_started_at && vs.dispatched_at > vs.stage_started_at)) return;
      const hrs = hoursBetween(vs.stage_started_at, vs.dispatched_at);
      (vendorAllHrs[vs.vendor_name] ||= []).push(hrs);
      const seenTitles = new Set();
      o.line_items.filter(li => li.vendor === vs.vendor_name).forEach(li => {
        if (seenTitles.has(li.title)) return;
        seenTitles.add(li.title);
        ((vendorProductHrs[vs.vendor_name] ||= {})[li.title] ||= []).push(hrs);
      });
    });
  });

  const findings = [];
  for (const [vendor, productMap] of Object.entries(vendorProductHrs)) {
    const allHrs = vendorAllHrs[vendor] || [];
    if (allHrs.length < PI_MIN_SAMPLE) continue;
    const vendorAvg = allHrs.reduce((a,b)=>a+b,0) / allHrs.length;
    for (const [title, hrsArr] of Object.entries(productMap)) {
      if (hrsArr.length < PI_MIN_SAMPLE) continue;
      const avg = hrsArr.reduce((a,b)=>a+b,0) / hrsArr.length;
      const diff = avg - vendorAvg;
      if (diff >= 15 && avg >= vendorAvg * 1.3) {
        findings.push({
          category: 'Product Dispatch Delay',
          severity: diff >= 30 ? 'red' : 'amber',
          title: `"${title}" (${vendor}) takes ${diff.toFixed(0)}h longer to dispatch than this vendor's other products`,
          detail: `Avg ${avg.toFixed(0)}h for this product vs ${vendorAvg.toFixed(0)}h vendor average this week, based on ${hrsArr.length} shipment${hrsArr.length>1?'s':''}. Could be a stocking/sourcing delay specific to this SKU.`,
          strength: diff,
          productTitle: title,
        });
      }
    }
  }
  return findings.sort((a,b) => b.strength - a.strength).slice(0, 6);
}

function analyzeProductMomentum(current, baseline, currentDays = PI_CURRENT_DAYS, baselineDays = PI_BASELINE_DAYS) {
  const countUnits = (rows) => {
    const map = {};
    rows.forEach(o => o.line_items.forEach(li => { map[li.title] = (map[li.title] || 0) + li.qty; }));
    return map;
  };
  const curMap = countUnits(current);
  const baseMap = countUnits(baseline);
  const currentWeeks = Math.max(currentDays / 7, 1);
  const baselineWeeks = Math.max(baselineDays / 7, 1);
  const periodLabel = currentDays === 7 ? 'this week' : `in the last ${currentDays}d`;

  const findings = [];
  for (const [title, curUnits] of Object.entries(curMap)) {
    if (curUnits < 6) continue;
    const curWeeklyAvg = curUnits / currentWeeks;
    const baseUnits = baseMap[title] || 0;
    const baseWeeklyAvg = baseUnits / baselineWeeks;

    if (baseWeeklyAvg < 1) {
      // Barely sold (or didn't exist) in the baseline period, now selling — a silent winner.
      findings.push({
        category: 'Silent Winner',
        severity: 'info',
        title: `"${title}" sold ${curUnits} units ${periodLabel} after near-zero sales in the prior ${baselineDays} days`,
        detail: `Sudden demand with no prior trend — check stock levels before it runs out, and look for what triggered it (organic, ad spend, influencer, marketplace placement).`,
        strength: curWeeklyAvg,
        productTitle: title,
      });
      continue;
    }

    const growth = curWeeklyAvg / baseWeeklyAvg;
    if (growth >= 2.5) {
      findings.push({
        category: 'Silent Winner',
        severity: 'info',
        title: `"${title}" sold ${curUnits} units ${periodLabel} (${curWeeklyAvg.toFixed(1)}/wk) vs a ${baseWeeklyAvg.toFixed(1)}/wk baseline — ${growth.toFixed(1)}× normal`,
        detail: `Worth confirming inventory can keep up, and whether this is a one-off bulk order or a real trend.`,
        strength: growth,
        productTitle: title,
      });
    } else if (growth <= 0.35 && baseWeeklyAvg >= 2) {
      findings.push({
        category: 'Product Momentum',
        severity: 'amber',
        title: `"${title}" sales dropped to ${curWeeklyAvg.toFixed(1)}/wk ${periodLabel} vs a ${baseWeeklyAvg.toFixed(1)}/wk baseline`,
        detail: `Significant slowdown for a product that was previously selling steadily — check for stockouts, listing changes, or a price/visibility issue.`,
        strength: 1 / Math.max(growth, 0.01),
        productTitle: title,
      });
    }
  }
  return findings.sort((a,b) => b.strength - a.strength).slice(0, 6);
}

function analyzeProductGeoSpike(current) {
  const totalOrders = current.length;
  if (totalOrders < 10) return [];
  const totalByState = {};
  current.forEach(o => { totalByState[o.state] = (totalByState[o.state] || 0) + 1; });

  const productTotal = {};
  const productByState = {};
  current.forEach(o => {
    const titles = new Set(o.line_items.map(li => li.title));
    titles.forEach(title => {
      productTotal[title] = (productTotal[title] || 0) + 1;
      (productByState[title] ||= {})[o.state] = (productByState[title][o.state] || 0) + 1;
    });
  });

  const findings = [];
  for (const [title, total] of Object.entries(productTotal)) {
    if (total < 6) continue;
    for (const [state, count] of Object.entries(productByState[title])) {
      if (count < PI_MIN_SAMPLE || state === 'Unknown') continue;
      const expectedShare = totalByState[state] / totalOrders;
      const actualShare = count / total;
      if (actualShare >= expectedShare * 2.2) {
        findings.push({
          category: 'Product Geography',
          severity: actualShare >= expectedShare * 3.5 ? 'amber' : 'info',
          title: `"${title}" orders are clustering in ${state}`,
          detail: `${count} of ${total} orders for this product this week are from ${state}, which normally accounts for ${(expectedShare*100).toFixed(0) === '0' ? '<1' : (expectedShare*100).toFixed(0)}% of order volume — about ${(actualShare/expectedShare).toFixed(1)}× the expected concentration.`,
          strength: actualShare / expectedShare,
          productTitle: title,
        });
      }
    }
  }
  return findings.sort((a,b) => b.strength - a.strength).slice(0, 5);
}

function analyzeProductRtoConcentration(current) {
  const terminal = current.filter(o => ['delivered', 'rto'].includes(o.stage));
  const totalRto = terminal.filter(o => o.stage === 'rto').length;
  if (totalRto < 6) return [];

  const productTotalOrders = {};
  const productRtoCount = {};
  terminal.forEach(o => {
    const titles = new Set(o.line_items.map(li => li.title));
    titles.forEach(title => {
      productTotalOrders[title] = (productTotalOrders[title] || 0) + 1;
      if (o.stage === 'rto') productRtoCount[title] = (productRtoCount[title] || 0) + 1;
    });
  });

  const findings = [];
  for (const [title, rtoCount] of Object.entries(productRtoCount)) {
    const total = productTotalOrders[title];
    if (total < PI_MIN_SAMPLE) continue;
    const ownRate = pctSafe(rtoCount, total);
    const shareOfAllRto = pctSafe(rtoCount, totalRto);
    if (shareOfAllRto >= 15 || ownRate >= 50) {
      findings.push({
        category: 'Product RTO',
        severity: (shareOfAllRto >= 25 || ownRate >= 60) ? 'red' : 'amber',
        title: `"${title}" is ${shareOfAllRto.toFixed(0)}% of all RTOs this week — ${ownRate.toFixed(0)}% of its own orders refused`,
        detail: `${rtoCount} of ${total} orders containing this product came back RTO. People are ordering it but not accepting delivery — check the listing (sizing/description accuracy) and COD confirmation quality for this product.`,
        strength: Math.max(shareOfAllRto, ownRate),
        productTitle: title,
      });
    }
  }
  return findings.sort((a,b) => b.strength - a.strength).slice(0, 5);
}

// ── Pixel Tracker analyzers — storefront funnel data (views/ATC/checkout/
// purchase), independent of the order-pipeline dataset above. Pulled
// straight from pixel_events, which already carries productImage from the
// storefront pixel itself, so these findings don't need the separate
// order-line-item photo lookup the others use.
async function buildPixelDataset(days) {
  const fromISO = new Date(Date.now() - days * 24 * 3600 * 1000).toISOString();
  const events = await mdb.collection('pixel_events').find(
    { created_at: { $gte: fromISO }, productName: { $ne: 'N/A' } },
    { projection: { eventName: 1, productName: 1, productImage: 1, value: 1, created_at: 1, _id: 0 } }
  ).toArray();
  return events.map(e => ({ ...e, created_ms: new Date(e.created_at).getTime() }));
}

function analyzePixelTrending(current, baseline, currentDays = PI_CURRENT_DAYS, baselineDays = PI_BASELINE_DAYS) {
  const countViews = (rows) => {
    const map = {};
    rows.forEach(e => { if (e.eventName === 'ViewContent') map[e.productName] = (map[e.productName] || 0) + 1; });
    return map;
  };
  const curMap = countViews(current), baseMap = countViews(baseline);
  const curWeeks = Math.max(currentDays / 7, 1), baseWeeks = Math.max(baselineDays / 7, 1);
  const periodLabel = currentDays === 7 ? 'this week' : `in the last ${currentDays}d`;
  const imageOf = (rows, name) => rows.find(e => e.productName === name && e.productImage)?.productImage || '';

  const findings = [];
  for (const [name, curViews] of Object.entries(curMap)) {
    if (curViews < 8) continue; // need real traffic before calling it a trend
    const curRate = curViews / curWeeks;
    const baseViews = baseMap[name] || 0;
    const baseRate = baseViews / baseWeeks;

    if (baseRate < 2) {
      findings.push({
        category: 'Pixel Trending', severity: 'info',
        title: `"${name}" got ${curViews} views ${periodLabel} after almost no traffic before`,
        detail: `Sudden interest with no prior browsing trend — check what's driving it (ad spend, social mention, search ranking change) and make sure stock can handle a sales spike if it converts.`,
        strength: curRate, productTitle: name, image: imageOf(current, name),
      });
      continue;
    }
    const growth = curRate / baseRate;
    if (growth >= 2.5) {
      findings.push({
        category: 'Pixel Trending', severity: 'info',
        title: `"${name}" views up ${growth.toFixed(1)}× — ${curRate.toFixed(0)}/wk vs ${baseRate.toFixed(0)}/wk baseline`,
        detail: `Traffic to this product is climbing well above its normal pace. Worth featuring more prominently while interest is high.`,
        strength: growth, productTitle: name, image: imageOf(current, name),
      });
    } else if (growth <= 0.35 && baseRate >= 5) {
      findings.push({
        category: 'Pixel Trending', severity: 'amber',
        title: `"${name}" views dropped to ${curRate.toFixed(0)}/wk vs a ${baseRate.toFixed(0)}/wk baseline`,
        detail: `Used to get steady traffic, now falling off — check if it dropped in search/collection ranking, went out of stock, or lost ad spend.`,
        strength: 1 / Math.max(growth, 0.01), productTitle: name, image: imageOf(current, name),
      });
    }
  }
  return findings.sort((a,b) => b.strength - a.strength).slice(0, 6);
}

function analyzePixelFunnelDropoff(current) {
  const stats = {};
  current.forEach(e => {
    const s = stats[e.productName] ||= { views: 0, atc: 0, checkout: 0, purchases: 0, image: '' };
    if (e.productImage && !s.image) s.image = e.productImage;
    if (e.eventName === 'ViewContent') s.views++;
    else if (e.eventName === 'AddToCart') s.atc++;
    else if (e.eventName === 'InitiateCheckout') s.checkout++;
    else if (e.eventName === 'Purchase') s.purchases++;
  });

  const entries = Object.entries(stats);
  const avgRate = (numKey, denKey, minDen) => {
    let num = 0, den = 0;
    entries.forEach(([, s]) => { if (s[denKey] >= minDen) { num += s[numKey]; den += s[denKey]; } });
    return den ? (num / den) * 100 : 0;
  };
  const overallViewToAtc = avgRate('atc', 'views', 1);
  const overallAtcToCheckout = avgRate('checkout', 'atc', 1);
  const overallCheckoutToPurchase = avgRate('purchases', 'checkout', 1);

  const findings = [];
  for (const [name, s] of Object.entries(stats)) {
    if (s.views >= 10 && s.views * (overallViewToAtc/100) >= PI_MIN_SAMPLE) {
      const rate = (s.atc / s.views) * 100;
      if (rate <= Math.min(overallViewToAtc * 0.4, overallViewToAtc - 8) && overallViewToAtc > 0) {
        findings.push({
          category: 'Funnel Drop-off', severity: 'amber',
          title: `"${name}" gets views but barely converts to cart — ${rate.toFixed(0)}% vs ${overallViewToAtc.toFixed(0)}% average`,
          detail: `${s.views} views, only ${s.atc} added to cart. Worth checking price, product photos, or description — there's traffic but something's stopping the add-to-cart.`,
          strength: overallViewToAtc - rate, productTitle: name, image: s.image,
        });
      }
    }
    if (s.atc >= PI_MIN_SAMPLE) {
      const rate = (s.checkout / s.atc) * 100;
      if (rate <= Math.min(overallAtcToCheckout * 0.4, overallAtcToCheckout - 10) && overallAtcToCheckout > 0) {
        findings.push({
          category: 'Funnel Drop-off', severity: 'amber',
          title: `"${name}" gets added to cart but checkout rarely starts — ${rate.toFixed(0)}% vs ${overallAtcToCheckout.toFixed(0)}% average`,
          detail: `${s.atc} carts, only ${s.checkout} reached checkout. Could be a shipping-cost surprise or a price that looks different at cart vs product page.`,
          strength: overallAtcToCheckout - rate, productTitle: name, image: s.image,
        });
      }
    }
    if (s.checkout >= PI_MIN_SAMPLE) {
      const rate = (s.purchases / s.checkout) * 100;
      if (rate <= Math.min(overallCheckoutToPurchase * 0.4, overallCheckoutToPurchase - 10) && overallCheckoutToPurchase > 0) {
        findings.push({
          category: 'Funnel Drop-off', severity: 'red',
          title: `"${name}" starts checkout but rarely completes — ${rate.toFixed(0)}% vs ${overallCheckoutToPurchase.toFixed(0)}% average`,
          detail: `${s.checkout} checkouts started, only ${s.purchases} completed. This is the most expensive drop-off point — check for a payment/COD issue specific to this product or its price point.`,
          strength: overallCheckoutToPurchase - rate, productTitle: name, image: s.image,
        });
      }
    }
  }
  return findings.sort((a,b) => b.strength - a.strength).slice(0, 8);
}

function analyzeCancellations(current) {
  const totalOrders = current.length;
  if (totalOrders < 10) return [];
  const isCancelled = (o) => o.stage === 'cancelled' || !!o.cancelled_at;
  const cancelled = current.filter(isCancelled);
  if (cancelled.length < PI_MIN_SAMPLE) return [];
  const overallRate = pctSafe(cancelled.length, totalOrders);

  const findings = [];

  // 1) Orders that sat too long before being cancelled instead of confirmed/dispatched in time.
  const delayed = cancelled.filter(o => {
    if (!o.cancelled_at) return false;
    return hoursBetween(o.created_ms, new Date(o.cancelled_at).getTime()) >= 48;
  });
  if (delayed.length >= PI_MIN_SAMPLE) {
    findings.push({
      category: 'Cancellation Delay',
      severity: delayed.length >= 10 ? 'red' : 'amber',
      title: `${delayed.length} orders sat 48h+ before being cancelled`,
      detail: `Out of ${cancelled.length} cancellations this period, ${delayed.length} were never confirmed/dispatched in time and ended up cancelled instead of fulfilled. Faster confirmation calls or earlier follow-up nudges could likely save some of these.`,
      strength: delayed.length,
    });
  }

  // 2) Hotspots by state and city
  for (const [label, keyFn] of [['state', o => o.state], ['city', o => o.city]]) {
    const map = {};
    current.forEach(o => {
      const k = keyFn(o);
      if (k === 'Unknown') return;
      (map[k] ||= { total: 0, cancelled: 0 }).total++;
      if (isCancelled(o)) map[k].cancelled++;
    });
    for (const [name, v] of Object.entries(map)) {
      if (v.total < PI_MIN_SAMPLE) continue;
      const rate = pctSafe(v.cancelled, v.total);
      if (rate >= Math.max(overallRate * 1.8, overallRate + 15) && rate >= 20) {
        findings.push({
          category: 'Cancellation Hotspot',
          severity: rate >= 40 ? 'red' : 'amber',
          title: `${name} (${label}) cancellation rate is ${rate.toFixed(0)}% vs ${overallRate.toFixed(0)}% overall`,
          detail: `${v.cancelled} of ${v.total} orders from ${name} were cancelled this period.`,
          strength: rate,
        });
      }
    }
  }

  // 3) Vendor hotspots
  const vendorMap = {};
  current.forEach(o => o.vendors.forEach(vn => {
    (vendorMap[vn] ||= { total: 0, cancelled: 0 }).total++;
    if (isCancelled(o)) vendorMap[vn].cancelled++;
  }));
  for (const [vn, v] of Object.entries(vendorMap)) {
    if (v.total < PI_MIN_SAMPLE) continue;
    const rate = pctSafe(v.cancelled, v.total);
    if (rate >= Math.max(overallRate * 1.8, overallRate + 15) && rate >= 20) {
      findings.push({
        category: 'Cancellation Hotspot',
        severity: rate >= 40 ? 'red' : 'amber',
        title: `${vn}: cancellation rate ${rate.toFixed(0)}% vs ${overallRate.toFixed(0)}% marketplace average`,
        detail: `${v.cancelled} of ${v.total} orders from ${vn} were cancelled this period.`,
        strength: rate,
      });
    }
  }

  // 4) Product concentration — which SKUs make up an outsized share of cancellations
  const productMap = {};
  current.forEach(o => {
    const titles = new Set(o.line_items.map(li => li.title));
    titles.forEach(title => {
      (productMap[title] ||= { total: 0, cancelled: 0 }).total++;
      if (isCancelled(o)) productMap[title].cancelled++;
    });
  });
  const totalCancelled = cancelled.length;
  for (const [title, v] of Object.entries(productMap)) {
    if (v.total < PI_MIN_SAMPLE) continue;
    const ownRate = pctSafe(v.cancelled, v.total);
    const shareOfAll = pctSafe(v.cancelled, totalCancelled);
    if (shareOfAll >= 15 || ownRate >= 35) {
      findings.push({
        category: 'Product Cancellation',
        severity: (shareOfAll >= 25 || ownRate >= 50) ? 'red' : 'amber',
        title: `"${title}" is ${shareOfAll.toFixed(0)}% of all cancellations — ${ownRate.toFixed(0)}% of its own orders cancelled`,
        detail: `${v.cancelled} of ${v.total} orders containing this product were cancelled this period.`,
        strength: Math.max(shareOfAll, ownRate),
        productTitle: title,
      });
    }
  }

  return findings.sort((a,b) => b.strength - a.strength).slice(0, 8);
}

function analyzeWeekdaySkew(lookback) {
  const terminal = lookback.filter(o => ['delivered', 'rto'].includes(o.stage));
  if (terminal.length < 30) return [];
  const DAYS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const byDay = DAYS.map(() => ({ total: 0, rto: 0 }));
  terminal.forEach(o => {
    const d = new Date(o.created_ms).getDay();
    byDay[d].total++;
    if (o.stage === 'rto') byDay[d].rto++;
  });
  const rates = byDay.map((d,i) => ({ day: DAYS[i], rate: pctSafe(d.rto, d.total), total: d.total }))
    .filter(d => d.total >= 8);
  if (rates.length < 4) return [];
  const best = rates.reduce((a,b) => a.rate < b.rate ? a : b);
  const worst = rates.reduce((a,b) => a.rate > b.rate ? a : b);
  if (worst.rate - best.rate < 15) return [];
  return [{
    category: 'Weekday Pattern',
    severity: worst.rate - best.rate >= 25 ? 'amber' : 'info',
    title: `Orders placed on ${worst.day} RTO at ${worst.rate.toFixed(0)}%, vs ${best.rate.toFixed(0)}% on ${best.day}`,
    detail: `Based on the last ${PI_LOOKBACK_DAYS} days of delivered/RTO orders. Day-of-order-placement appears to predict return risk — worth checking if it's a courier scheduling or COD-confirmation-call timing issue.`,
  }];
}

function analyzeRepeatRtoCustomers(lookback) {
  const rto = lookback.filter(o => o.stage === 'rto');
  const byCustomer = {};
  rto.forEach(o => {
    const key = o.phone || o.email;
    if (!key) return;
    const bucket = (byCustomer[key] ||= { name: o.customerName || '', orders: [] });
    if (!bucket.name && o.customerName) bucket.name = o.customerName;
    bucket.orders.push(o.name);
  });
  const repeats = Object.entries(byCustomer).filter(([,v]) => v.orders.length >= 2);
  if (!repeats.length) return [];
  repeats.sort((a,b) => b[1].orders.length - a[1].orders.length);
  const top = repeats.slice(0, 8);
  return [{
    category: 'Repeat RTO Customers',
    severity: top[0][1].orders.length >= 3 ? 'amber' : 'info',
    title: `${repeats.length} customer${repeats.length>1?'s':''} with 2+ RTO orders in the last ${PI_LOOKBACK_DAYS} days`,
    detail: top.map(([key, v]) => `${v.name ? v.name + ' — ' : ''}${key}: ${v.orders.join(', ')} (${v.orders.length} RTOs)`).join('<br>'),
  }];
}

async function runPatternAnalysis(currentDays = PI_CURRENT_DAYS, baselineDays = PI_BASELINE_DAYS) {
  // Lookback must cover both windows, plus enough extra for the
  // weekday/repeat-customer analyzers which scan the whole dataset.
  const lookbackDays = Math.max(PI_LOOKBACK_DAYS, currentDays + baselineDays);
  const dataset = await buildPatternDataset(lookbackDays);
  const nowMs = Date.now();
  const currentStart = nowMs - currentDays * 24 * 3600 * 1000;
  const baselineStart = currentStart - baselineDays * 24 * 3600 * 1000;

  const current  = piWindow(dataset, currentStart, nowMs);
  const baseline = piWindow(dataset, baselineStart, currentStart);

  const pixelDataset  = await buildPixelDataset(lookbackDays);
  const pixelCurrent  = pixelDataset.filter(e => e.created_ms >= currentStart && e.created_ms < nowMs);
  const pixelBaseline = pixelDataset.filter(e => e.created_ms >= baselineStart && e.created_ms < currentStart);

  const findings = [
    ...analyzeDispatchTime(current, baseline, currentDays, baselineDays),
    ...analyzeTagRegionAnomalies(current),
    ...analyzeRTOHotspots(current),
    ...analyzeConfirmNotComplete(current),
    ...analyzeVendorOutliers(current),
    ...analyzeProductDispatchDelay(current),
    ...analyzeProductMomentum(current, baseline, currentDays, baselineDays),
    ...analyzeProductGeoSpike(current),
    ...analyzeProductRtoConcentration(current),
    ...analyzeCancellations(current),
    ...analyzeWeekdaySkew(dataset),
    ...analyzeRepeatRtoCustomers(dataset),
    ...analyzePixelTrending(pixelCurrent, pixelBaseline, currentDays, baselineDays),
    ...analyzePixelFunnelDropoff(pixelCurrent),
  ];

  const severityRank = { red: 0, amber: 1, info: 2 };
  findings.sort((a,b) => severityRank[a.severity] - severityRank[b.severity]);

  // Attach product photos to any finding tagged with a productTitle that
  // doesn't already have one (Pixel Tracker findings already set their own
  // image directly from the storefront pixel data — don't refetch those).
  const titleToProductId = {};
  current.forEach(o => o.line_items.forEach(li => {
    if (li.product_id && !titleToProductId[li.title]) titleToProductId[li.title] = li.product_id;
  }));
  const needsImage = findings.filter(f => f.productTitle && !f.image);
  const productIds = [...new Set(needsImage.map(f => titleToProductId[f.productTitle]).filter(Boolean))];
  if (productIds.length) {
    const imageMap = await getProductImageMap(productIds);
    needsImage.forEach(f => {
      const pid = titleToProductId[f.productTitle];
      if (pid && imageMap[pid]) f.image = imageMap[pid];
    });
  }

  return { findings, period: { current_days: currentDays, baseline_days: baselineDays, current_orders: current.length, baseline_orders: baseline.length, generated_at: new Date().toISOString() } };
}

async function getProductImageMap(productIds) {
  const map = {};
  if (!productIds.length) return map;
  try {
    const token = await getAccessToken();
    for (let i = 0; i < productIds.length; i += 50) {
      const batch = productIds.slice(i, i + 50);
      const res = await fetch(`https://${SHOP}.myshopify.com/admin/api/2025-01/products.json?ids=${batch.join(',')}&fields=id,image`, {
        headers: { 'X-Shopify-Access-Token': token },
      }).then(r => r.json());
      (res.products || []).forEach(p => { if (p.image?.src) map[String(p.id)] = p.image.src; });
    }
  } catch (e) { console.error('getProductImageMap error:', e.message); }
  return map;
}

function renderPatternReportHtml({ findings, period }) {
  const SEV = {
    red:   { color:'#ef4444', bg:'#2d0a0a', label:'🔴 RED FLAG' },
    amber: { color:'#f59e0b', bg:'#2d1a00', label:'🟡 WATCH'   },
    info:  { color:'#6366f1', bg:'#10142d', label:'🔵 NOTICED' },
  };
  const grouped = {};
  findings.forEach(f => (grouped[f.category] ||= []).push(f));

  const card = (f) => {
    const s = SEV[f.severity];
    return `
    <div style="background:${s.bg};border-left:4px solid ${s.color};border-radius:8px;padding:14px 18px;margin-bottom:10px;display:flex;gap:12px;align-items:flex-start">
      ${f.image ? `<img src="${f.image}" alt="" width="48" height="48" style="width:48px;height:48px;border-radius:6px;object-fit:cover;flex-shrink:0;border:1px solid rgba(255,255,255,0.12)">` : ''}
      <div style="flex:1;min-width:0">
        <div style="font-size:10px;font-weight:800;color:${s.color};letter-spacing:1px;margin-bottom:6px">${s.label}</div>
        <div style="font-size:14px;font-weight:700;color:#f8fafc;margin-bottom:4px;line-height:1.4">${f.title}</div>
        <div style="font-size:12px;color:#94a3b8;line-height:1.6">${f.detail}</div>
      </div>
    </div>`;
  };

  const sections = Object.entries(grouped).map(([cat, items]) => `
    <div style="font-size:12px;font-weight:700;color:#64748b;text-transform:uppercase;letter-spacing:1.5px;margin:24px 0 10px">${cat}</div>
    ${items.map(card).join('')}
  `).join('');

  const body = findings.length ? sections : `
    <div style="text-align:center;padding:36px 20px;color:#10b981;font-weight:700;font-size:14px">
      ✅ No significant anomalies found this period. Everything's tracking within normal range.
    </div>`;

  return `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
  <body style="margin:0;padding:0;background:#0b0f1a;font-family:'Segoe UI',Arial,sans-serif">
    <div style="max-width:640px;margin:0 auto;padding:36px 20px">
      <div style="text-align:center;margin-bottom:28px">
        <div style="font-size:13px;color:#6366f1;font-weight:800;letter-spacing:2px">CROSCROW · PATTERN INTELLIGENCE</div>
        <div style="font-size:21px;font-weight:800;color:#f8fafc;margin-top:6px">Autonomous Findings Report</div>
        <div style="font-size:12px;color:#64748b;margin-top:4px">Generated ${new Date(period.generated_at).toLocaleString('en-IN', { dateStyle:'medium', timeStyle:'short' })} · ${period.current_orders} orders analyzed this week</div>
      </div>
      ${body}
      <div style="text-align:center;margin-top:28px;padding-top:18px;border-top:1px solid #1e293b">
        <div style="font-size:11px;color:#475569">Findings are statistical anomalies vs trailing baselines — verify before acting. Generated automatically every ${PI_RUN_EVERY_DAYS} days.</div>
      </div>
    </div>
  </body></html>`;
}

// How long to suppress a repeated finding before re-alerting it (full digest)
const PI_DIGEST_DEDUPE_DAYS = 7;

async function generateAndSendPatternReport({ currentDays = PI_CURRENT_DAYS, baselineDays = PI_BASELINE_DAYS, sendEmail = true } = {}) {
  const { findings: allFindings, period } = await runPatternAnalysis(currentDays, baselineDays);

  // Deduplicate: for emailed digests, filter findings already sent in last PI_DIGEST_DEDUPE_DAYS
  // Always store all findings in the DB so the UI can show them, but only email new ones.
  let emailFindings = allFindings;
  if (sendEmail) {
    const cutoff = new Date(Date.now() - PI_DIGEST_DEDUPE_DAYS * 24 * 3600 * 1000).toISOString();
    const newOnes = [];
    for (const f of allFindings) {
      const fp = `digest::${piFindingFingerprint(f)}`;
      const existing = await mdb.collection('pattern_alerts_fired').findOne({ _id: fp });
      if (!existing || existing.fired_at < cutoff) newOnes.push(f);
    }
    emailFindings = newOnes;
  }

  await mdb.collection('pattern_reports').insertOne({ ...period, findings: allFindings, emailed_skipped: !sendEmail, created_at: new Date().toISOString() });
  await mdb.collection('pattern_reports').deleteMany({ created_at: { $lt: new Date(Date.now() - 180*24*3600*1000).toISOString() } });

  if (!sendEmail) { console.log('🧠 Pattern Intelligence: analysis run without emailing (manual preview run)'); return { findings: allFindings, period, emailed: 0 }; }

  const cfg = await getSmtpConfig();
  if (!cfg?.host) { console.log('⚠️  Pattern report: SMTP not configured, skipped email'); return { findings: allFindings, period, emailed: 0 }; }

  if (!emailFindings.length) {
    console.log('🧠 Pattern Intelligence: all findings already reported in last 7d — digest skipped');
    return { findings: allFindings, period, emailed: 0 };
  }

  const html = renderPatternReportHtml({ findings: emailFindings, period });
  const settings = await RS.get();
  const recipients = [cfg.adminEmail, ...(settings.staff_emails || '').split(',').map(e=>e.trim())].filter(Boolean);
  let emailed = 0;
  for (const to of recipients) {
    try {
      await sendEmail({ to, subject: `🧠 Pattern Intelligence — ${emailFindings.filter(f=>f.severity==='red').length} red flag${emailFindings.filter(f=>f.severity==='red').length===1?'':'s'}, ${emailFindings.length} total new findings`, html, shopifyId: 'pattern_report', trigger: 'pattern_intelligence' });
      emailed++;
    } catch (e) { console.error('Pattern report email failed:', to, e.message); }
  }

  // Mark emailed findings so they don't repeat for PI_DIGEST_DEDUPE_DAYS
  for (const f of emailFindings) {
    const fp = `digest::${piFindingFingerprint(f)}`;
    await mdb.collection('pattern_alerts_fired').updateOne({ _id: fp }, { $set: { fired_at: new Date().toISOString(), title: f.title, severity: f.severity } }, { upsert: true });
  }

  await mdb.collection('global_config').updateOne({ _id: 'pattern_intelligence' }, { $set: { last_sent_at: new Date().toISOString() } }, { upsert: true });
  console.log(`🧠 Pattern Intelligence digest: ${emailFindings.length} new findings emailed to ${emailed} recipients (${allFindings.length - emailFindings.length} suppressed as duplicates)`);
  return { findings: allFindings, period, emailed };
}

async function patternIntelligenceCronJob() {
  try {
    const cfg = await mdb.collection('global_config').findOne({ _id: 'pattern_intelligence' });
    const lastSent = cfg?.last_sent_at ? new Date(cfg.last_sent_at).getTime() : 0;
    if (Date.now() - lastSent < PI_RUN_EVERY_DAYS * 24 * 3600 * 1000) return;
    console.log('🧠 Running Pattern Intelligence cron…');
    await generateAndSendPatternReport();
  } catch (e) { console.error('Pattern Intelligence cron error:', e.message); }
}
setTimeout(() => patternIntelligenceCronJob().catch(()=>{}), 90 * 1000); // 90s after boot
setInterval(patternIntelligenceCronJob, 6 * 60 * 60 * 1000); // check every 6h, actually sends every PI_RUN_EVERY_DAYS

// ── Fast lane: catches urgent (red) findings between the 3-day digests ─────
// Runs every 3h, re-analyzes, and immediately emails ONLY red-severity
// findings that haven't already been alerted in the last PI_ALERT_DEDUPE_DAYS
// — so a real fire gets reported same-day instead of waiting up to 3 days,
// without spamming the same ongoing issue every 3 hours.
const PI_FASTLANE_INTERVAL_MS = 3 * 60 * 60 * 1000;
const PI_ALERT_DEDUPE_DAYS    = 3;

function piFindingFingerprint(f) { return `${f.category}::${f.title}`; }

async function patternIntelligenceFastLane() {
  try {
    const { findings } = await runPatternAnalysis();
    const reds = findings.filter(f => f.severity === 'red');
    if (!reds.length) return;

    const cfg = await getSmtpConfig();
    if (!cfg?.host) return;
    const settings = await RS.get();
    const recipients = [cfg.adminEmail, ...(settings.staff_emails || '').split(',').map(e => e.trim())].filter(Boolean);
    if (!recipients.length) return;

    const newOnes = [];
    for (const f of reds) {
      const fp = piFindingFingerprint(f);
      const existing = await mdb.collection('pattern_alerts_fired').findOne({ _id: fp });
      if (existing && Date.now() - new Date(existing.fired_at).getTime() < PI_ALERT_DEDUPE_DAYS * 24 * 3600 * 1000) continue;
      newOnes.push(f);
      await mdb.collection('pattern_alerts_fired').updateOne({ _id: fp }, { $set: { fired_at: new Date().toISOString(), title: f.title } }, { upsert: true });
    }
    if (!newOnes.length) return;

    const html = renderPatternReportHtml({ findings: newOnes, period: { generated_at: new Date().toISOString(), current_orders: 0 } });
    for (const to of recipients) {
      try {
        await sendEmail({ to, subject: `🚨 Urgent Pattern Alert — ${newOnes.length} new red flag${newOnes.length > 1 ? 's' : ''}`, html, shopifyId: 'pattern_alert', trigger: 'pattern_intelligence_alert' });
      } catch (e) { console.error('Pattern fast-lane email failed:', to, e.message); }
    }
    console.log(`🚨 Pattern fast-lane: ${newOnes.length} new red flag(s) alerted immediately`);
  } catch (e) { console.error('Pattern Intelligence fast-lane error:', e.message); }
}
setInterval(patternIntelligenceFastLane, PI_FASTLANE_INTERVAL_MS);
// Prune fired-alert fingerprints older than the dedupe window so old, now-resolved
// findings don't permanently block re-alerting if the same issue recurs later.
setInterval(() => {
  mdb.collection('pattern_alerts_fired').deleteMany({ fired_at: { $lt: new Date(Date.now() - PI_ALERT_DEDUPE_DAYS * 24 * 3600 * 1000).toISOString() } }).catch(()=>{});
}, 24 * 60 * 60 * 1000);

// ── Pattern Intelligence API endpoints ─────────────────────────────────────
app.post("/admin/pattern-report/run", adminAuth, async (req, res) => {
  try {
    const currentDays  = parseInt(req.body?.currentDays)  || PI_CURRENT_DAYS;
    const baselineDays = parseInt(req.body?.baselineDays) || PI_BASELINE_DAYS;
    const sendEmail     = req.body?.sendEmail !== false; // default true unless explicitly unchecked
    const result = await generateAndSendPatternReport({ currentDays, baselineDays, sendEmail });
    res.json({ success: true, ...result });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.get("/admin/pattern-report/preview", adminAuth, async (req, res) => {
  try {
    const currentDays  = parseInt(req.query.currentDays)  || PI_CURRENT_DAYS;
    const baselineDays = parseInt(req.query.baselineDays) || PI_BASELINE_DAYS;
    const { findings, period } = await runPatternAnalysis(currentDays, baselineDays);
    res.json({ findings, period });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.get("/admin/pattern-report/history", adminAuth, async (req, res) => {
  const reports = await mdb.collection('pattern_reports').find({}, { projection: { _id: 0 } }).sort({ created_at: -1 }).limit(20).toArray();
  res.json({ reports });
});

