// GET /order/lookup — unified API: track + confirm data in one call
app.get("/order/lookup", async (req, res) => {
  try {
    const { q, contact } = req.query;
    if (!q) return res.status(400).json({ error: "Order number is required" });

    const normalized = q.replace(/^#/, '').trim();
    const name = `#${normalized}`;
    const data = await shopifyREST(`/orders.json?name=${encodeURIComponent(name)}&status=any&limit=10`);
    const orders = data.orders || [];

    const skipContact = !contact || contact.trim().toLowerCase() === 'na';
    let order;
    if (skipContact) {
      order = orders[0];
    } else {
      const contactClean = contact.toLowerCase().trim();
      const contactPhone = normalizePhone(contact);
      order = orders.find(o => {
        const oEmail = (o.email || o.contact_email || o.billing_address?.email || '').toLowerCase().trim();
        const oPhone = normalizePhone(o.shipping_address?.phone || o.billing_address?.phone || o.phone || '');
        return oEmail === contactClean || (contactPhone.length >= 10 && oPhone === contactPhone);
      });
    }

    if (!order) return res.status(404).json({ error: "Order not found. Please check your order number." });
    if (order.cancelled_at) return res.status(400).json({ error: "This order has been cancelled." });

    const meta = await mdb.collection('order_meta').findOne({ shopify_id: String(order.id) }, { projection: { _id: 0 } }) || {};
    const isPrepaid = order.financial_status === 'paid';
    const advancePaid = parseFloat(meta.advance_paid || 0);
    const alreadyConfirmed = !!meta.confirmation_paid || advancePaid >= CONFIRM_FEE || isPrepaid;
    const total = parseFloat(order.total_price);
    const discountedTotal = Math.round(total * (1 - PREPAID_DISCOUNT_PCT / 100));
    const prepaidSavings = Math.round(total - discountedTotal);

    // Enrich items with images
    const enriched = await enrichOrderImages(order);
    const confirmItems = (enriched.line_items || []).map(li => ({
      title: li.title, variant_title: li.variant_title || '',
      quantity: li.quantity, price: li.price, image_url: li.image_url || null,
      product_id: li.product_id || null, variant_id: li.variant_id || null,
      vendor: li.vendor || '',
    }));

    // Build track payload
    const trackPayload = await buildOrderPayload(order);

    res.json({
      // shared
      shopify_order_id: order.id,
      order_name: order.name,
      customer_name: trackPayload.customer_name,
      // Use effective stage (max of order_meta + all vendor stages) so delivered orders aren't stuck at partial
      stage: trackPayload.stage || meta.stage || 'new',
      financial_status: order.financial_status,
      is_prepaid: isPrepaid,
      // confirm-specific
      already_confirmed: alreadyConfirmed,
      fee: CONFIRM_FEE,
      prepaid_savings: prepaidSavings,
      prepaid_amount_due: Math.max(0, discountedTotal - advancePaid),
      total: order.total_price,
      items: confirmItems,
      // track-specific
      awb: trackPayload.awb,
      tracking_url: trackPayload.tracking_url,
      delivery_status: trackPayload.delivery_status,
      delivery_status_updated_at: trackPayload.delivery_status_updated_at,
      tracking_history: trackPayload.tracking_history || [],
      vendor_shipments: trackPayload.vendor_shipments,
      return_requests: trackPayload.return_requests,
      return_configs: trackPayload.return_configs,
      customer_email: trackPayload.customer_email,
      customer_phone: trackPayload.customer_phone,
      created_at: order.created_at,
      shipping_city: order.shipping_address?.city || order.billing_address?.city || '',
      shipping_state: order.shipping_address?.province || order.billing_address?.province || '',
    });
  } catch (e) {
    console.error('❌ /order/lookup:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// GET /order/product-variants — return all variants for a product (for exchange picker)
app.get("/order/product-variants", async (req, res) => {
  try {
    const { product_id, variant_id } = req.query;
    if (!product_id) return res.status(400).json({ error: "product_id required" });
    const data = await shopifyREST(`/products/${product_id}.json?fields=id,title,variants,options,images`);
    const product = data.product;
    if (!product) return res.status(404).json({ error: "Product not found" });

    // Build option names (e.g. Size, Color)
    const options = (product.options || []).map(o => ({ name: o.name, values: o.values }));

    // Map variants, mark current one and OOS ones
    const variants = (product.variants || []).map(v => ({
      id: v.id,
      title: v.title,
      price: v.price,
      available: v.inventory_quantity > 0 || v.inventory_management === null || v.inventory_policy === 'continue',
      is_current: String(v.id) === String(variant_id),
      option1: v.option1, option2: v.option2, option3: v.option3,
      image_id: v.image_id || null,
    }));

    // Map image_id → url
    const imageMap = {};
    (product.images || []).forEach(img => { imageMap[img.id] = img.src; });

    res.json({ options, variants, imageMap });
  } catch(e) {
    console.error('❌ /order/product-variants:', e.message);
    res.status(500).json({ error: e.message });
  }
});

// GET /order/lookup-by-contact — find orders by email or phone (no order number needed)
app.get("/order/lookup-by-contact", async (req, res) => {
  try {
    const contact = (req.query.contact || '').trim();
    if (!contact) return res.status(400).json({ error: "Email or phone number is required" });

    const isEmail = contact.includes('@');
    let shopifyOrders = [];

    if (isEmail) {
      const data = await shopifyREST(`/orders.json?email=${encodeURIComponent(contact)}&status=any&limit=5&fields=id,name,financial_status,created_at,cancelled_at`);
      shopifyOrders = data.orders || [];
    } else {
      const phone = normalizePhone(contact);
      if (phone.length < 10) return res.status(400).json({ error: "Enter a valid 10-digit phone number or email" });
      // Search customers by phone then pull their orders
      const custData = await shopifyREST(`/customers/search.json?query=phone:${encodeURIComponent('+91' + phone.slice(-10))}&fields=id&limit=3`);
      const customers = custData.customers || [];
      if (customers.length) {
        const data = await shopifyREST(`/orders.json?customer_id=${customers[0].id}&status=any&limit=5&fields=id,name,financial_status,created_at,cancelled_at`);
        shopifyOrders = data.orders || [];
      }
    }

    const orders = shopifyOrders
      .filter(o => !o.cancelled_at)
      .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
      .slice(0, 3)
      .map(o => ({ order_name: o.name, created_at: o.created_at, status: o.financial_status }));

    if (!orders.length) return res.status(404).json({ error: "No orders found for this contact. Try your order number instead." });
    return res.json({ orders });
  } catch (e) {
    console.error('❌ /order/lookup-by-contact:', e.message);
    res.status(500).json({ error: "Lookup failed. Please try again." });
  }
});

