// ── POST /admin/metafield-audit/:productId/sizechart — upload size chart image ──
const adminSizeChartUpload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 10 * 1024 * 1024 } });
app.post("/admin/metafield-audit/:productId/sizechart", adminAuth, adminSizeChartUpload.single('image'), async (req, res) => {
  try {
    const { productId } = req.params;
    if (!req.file) return res.status(400).json({ error: 'Image file required.' });
    const allowedTypes = ['image/png','image/jpeg','image/jpg','image/webp'];
    if (!allowedTypes.includes(req.file.mimetype)) return res.status(400).json({ error: 'Only PNG, JPG, or WEBP allowed.' });

    let fileBuffer = req.file.buffer;
    let fileMime   = req.file.mimetype;
    let fileName   = req.file.originalname || 'sizechart.jpg';
    try {
      const sharp = require('sharp');
      const meta  = await sharp(fileBuffer).metadata();
      if ((meta.width * meta.height) / 1_000_000 > 20) {
        fileBuffer = await sharp(fileBuffer).resize({ width: 4000, withoutEnlargement: true }).jpeg({ quality: 90 }).toBuffer();
        fileMime   = 'image/jpeg';
        fileName   = fileName.replace(/\.[^.]+$/, '.jpg');
      }
    } catch {}

    const token = await getAccessToken();
    const gqlUrl = `https://${SHOP}.myshopify.com/admin/api/2025-01/graphql.json`;
    const gqlHeaders = { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' };

    // Stage upload
    const stageData = await fetch(gqlUrl, { method:'POST', headers: gqlHeaders, body: JSON.stringify({
      query:`mutation stagedUploadsCreate($input:[StagedUploadInput!]!){stagedUploadsCreate(input:$input){stagedTargets{url resourceUrl parameters{name value}}userErrors{message}}}`,
      variables:{ input:[{ filename: fileName, mimeType: fileMime, resource:'FILE', fileSize: String(fileBuffer.length), httpMethod:'POST' }] },
    }) }).then(r=>r.json());
    const target = stageData?.data?.stagedUploadsCreate?.stagedTargets?.[0];
    if (!target) throw new Error('Staged upload failed: ' + JSON.stringify(stageData?.data?.stagedUploadsCreate?.userErrors));

    // Upload file
    const formData = new (require('form-data'))();
    (target.parameters||[]).forEach(p => formData.append(p.name, p.value));
    formData.append('file', fileBuffer, { filename: fileName, contentType: fileMime });
    const uploadRes = await fetch(target.url, { method:'POST', body: formData, headers: formData.getHeaders() });
    if (!uploadRes.ok) throw new Error(`Upload failed: ${uploadRes.status}`);

    // Create file in Shopify
    const fileData = await fetch(gqlUrl, { method:'POST', headers: gqlHeaders, body: JSON.stringify({
      query:`mutation fileCreate($files:[FileCreateInput!]!){fileCreate(files:$files){files{id ...on MediaImage{image{url}}}userErrors{message}}}`,
      variables:{ files:[{ originalSource: target.resourceUrl, contentType:'IMAGE' }] },
    }) }).then(r=>r.json());
    const fileId   = fileData?.data?.fileCreate?.files?.[0]?.id;
    const imageUrl = fileData?.data?.fileCreate?.files?.[0]?.image?.url;
    if (!fileId) throw new Error('File create failed: ' + JSON.stringify(fileData?.data?.fileCreate?.userErrors));

    // Upsert sizechart metafield
    const mfData   = await shopifyREST(`/products/${productId}/metafields.json`);
    const existing = (mfData.metafields||[]).find(m => ['sizechart','size_chart'].includes((m.key||'').toLowerCase()));
    if (existing) {
      await fetch(`https://${SHOP}.myshopify.com/admin/api/2025-01/metafields/${existing.id}.json`, {
        method:'PUT', headers: gqlHeaders,
        body: JSON.stringify({ metafield:{ id: existing.id, value: fileId, type:'file_reference' } }),
      });
    } else {
      await fetch(`https://${SHOP}.myshopify.com/admin/api/2025-01/products/${productId}/metafields.json`, {
        method:'POST', headers: gqlHeaders,
        body: JSON.stringify({ metafield:{ namespace:'custom', key:'sizechart', value: fileId, type:'file_reference' } }),
      });
    }

    res.json({ ok: true, image_url: imageUrl, file_id: fileId });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// ── Meta Ads: helper ─────────────────────────────────────────────────────────
const META_TOKEN   = process.env.META_ACCESS_TOKEN  || '';
const META_ACCOUNT = process.env.META_AD_ACCOUNT_ID || ''; // e.g. act_123456789
const META_API     = 'https://graph.facebook.com/v21.0';

async function metaGet(path, params = {}) {
  const qs = new URLSearchParams({ access_token: META_TOKEN, ...params }).toString();
  const r = await fetch(`${META_API}${path}?${qs}`);
  const d = await r.json();
  if (d.error) throw new Error(`Meta API: ${d.error.message}`);
  return d;
}

// ── GET /admin/meta-ads/insights ─────────────────────────────────────────────
app.get('/admin/meta-ads/insights', adminAuth, async (req, res) => {
  if (!META_TOKEN || !META_ACCOUNT) return res.status(400).json({ error: 'META_ACCESS_TOKEN and META_AD_ACCOUNT_ID env vars not set' });
  const { period = 'last_30d', since, until } = req.query;

  // All Meta-supported date presets
  const PRESET_MAP = {
    today:'today', yesterday:'yesterday',
    last_7d:'last_7d', last_14d:'last_14d', last_28d:'last_28d', last_30d:'last_30d',
    this_week:'this_week_mon_today', last_week:'last_week_mon_sun',
    this_month:'this_month', last_month:'last_month',
    this_quarter:'this_quarter', last_quarter:'last_quarter',
    this_year:'this_year', last_year:'last_year',
  };

  // Build time params: custom range takes priority over preset
  const timeParams = (since && until)
    ? { time_range: JSON.stringify({ since, until }) }
    : { date_preset: PRESET_MAP[period] || 'last_30_d' };

  // Hourly breakdown only valid for ranges ≤ 7 days
  const isShortRange = (since && until)
    ? (new Date(until) - new Date(since)) / 86400000 <= 7
    : ['today','yesterday','last_7d'].includes(period);

  const baseFields    = 'spend,impressions,clicks,ctr,cpm,cpc,reach,frequency,actions,action_values,purchase_roas,cost_per_action_type';
  const insightFields = 'spend,impressions,clicks,reach,frequency,actions,action_values,purchase_roas';

  // Helper: extract purchase metrics from Meta insight row
  const extractPurchases = (item) => {
    const purchases  = parseFloat((item.actions||[]).find(a=>a.action_type==='purchase')?.value||0);
    const revenue    = parseFloat((item.action_values||[]).find(a=>a.action_type==='purchase')?.value||0);
    const addtocart  = parseFloat((item.actions||[]).find(a=>a.action_type==='add_to_cart')?.value||0);
    const initcheckout = parseFloat((item.actions||[]).find(a=>a.action_type==='initiate_checkout')?.value||0);
    const landingviews = parseFloat((item.actions||[]).find(a=>a.action_type==='landing_page_view')?.value||0);
    const roas       = item.purchase_roas?.[0]?.value
      ? parseFloat(item.purchase_roas[0].value)
      : (revenue && item.spend ? parseFloat((parseFloat(revenue)/parseFloat(item.spend)).toFixed(2)) : 0);
    const cpp        = purchases > 0 ? parseFloat((parseFloat(item.spend||0)/purchases).toFixed(2)) : 0; // cost per purchase
    return { purchases, revenue, roas, cpp, addtocart, initcheckout, landingviews };
  };

  const formatRow = (item) => {
    const p = extractPurchases(item);
    return {
      spend:       parseFloat(item.spend||0),
      impressions: parseInt(item.impressions||0),
      clicks:      parseInt(item.clicks||0),
      reach:       parseInt(item.reach||0),
      frequency:   parseFloat(parseFloat(item.frequency||0).toFixed(2)),
      ctr:         parseFloat(item.ctr||0),
      cpm:         parseFloat(item.cpm||0),
      cpc:         parseFloat(item.cpc||0),
      ...p,
    };
  };

  try {
    const safe = (p) => p.catch(e => ({ data: [], _err: e.message }));

    const [overview, byRegion, byAge, byCampaign, byAdset, byDevice, byPublisher, byHour] = await Promise.all([
      safe(metaGet(`/${META_ACCOUNT}/insights`, { fields: baseFields, ...timeParams })),
      safe(metaGet(`/${META_ACCOUNT}/insights`, { fields: insightFields, ...timeParams, breakdowns:'region', limit:50 })),
      safe(metaGet(`/${META_ACCOUNT}/insights`, { fields: insightFields, ...timeParams, breakdowns:'age,gender', limit:100 })),
      safe(metaGet(`/${META_ACCOUNT}/insights`, { fields:`campaign_name,${insightFields}`, ...timeParams, level:'campaign', limit:50 })),
      safe(metaGet(`/${META_ACCOUNT}/insights`, { fields:`campaign_name,adset_name,${insightFields}`, ...timeParams, level:'adset', limit:50 })),
      safe(metaGet(`/${META_ACCOUNT}/insights`, { fields: insightFields, ...timeParams, breakdowns:'device_platform', limit:20 })),
      safe(metaGet(`/${META_ACCOUNT}/insights`, { fields: insightFields, ...timeParams, breakdowns:'publisher_platform', limit:20 })),
      isShortRange
        ? safe(metaGet(`/${META_ACCOUNT}/insights`, { fields:'spend,impressions,clicks,actions,action_values', ...timeParams, breakdowns:'hourly_stats_aggregated_by_advertiser_time_zone', limit:24 }))
        : Promise.resolve({ data: [] }),
    ]);

    res.json({
      ok:          true,
      period: since && until ? `custom` : period,
      since: since || null, until: until || null,
      overview:    { ...formatRow((overview.data||[])[0]||{}), date_start:overview.data?.[0]?.date_start, date_stop:overview.data?.[0]?.date_stop },
      byRegion:    (byRegion.data||[]).map(r=>({ region:r.region, ...formatRow(r) })).sort((a,b)=>b.roas-a.roas),
      byAge:       (byAge.data||[]).map(r=>({ age:r.age, gender:r.gender, ...formatRow(r) })).sort((a,b)=>b.roas-a.roas),
      byCampaign:  (byCampaign.data||[]).map(r=>({ campaign:r.campaign_name, ...formatRow(r) })).sort((a,b)=>b.roas-a.roas),
      byAdset:     (byAdset.data||[]).map(r=>({ campaign:r.campaign_name, adset:r.adset_name, ...formatRow(r) })).sort((a,b)=>b.roas-a.roas),
      byDevice:    (byDevice.data||[]).map(r=>({ device:r.device_platform, ...formatRow(r) })),
      byPublisher: (byPublisher.data||[]).map(r=>({ publisher:r.publisher_platform, ...formatRow(r) })),
      byHour:      (byHour.data||[]).map(r=>({ hour:r.hourly_stats_aggregated_by_advertiser_time_zone, ...formatRow(r) })),
    });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// ── GET /admin/meta-ads/audiences — interest audience performance ─────────────
// Fetches all active ad sets, extracts their interest targets from targeting spec,
// then joins with insights so you can compare ROAS per interest audience.
app.get('/admin/meta-ads/audiences', adminAuth, async (req, res) => {
  if (!META_TOKEN || !META_ACCOUNT) return res.status(400).json({ error: 'META_ACCESS_TOKEN and META_AD_ACCOUNT_ID env vars not set' });
  const { period = 'last_30d', since, until } = req.query;
  const PRESET_MAP = { today:'today', yesterday:'yesterday', last_7d:'last_7_d', last_14d:'last_14_d', last_28d:'last_28_d', last_30d:'last_30_d', this_week:'this_week_mon_today', last_week:'last_week_mon_sun', this_month:'this_month', last_month:'last_month', this_quarter:'this_quarter', last_quarter:'last_quarter', this_year:'this_year', last_year:'last_year' };
  const timeParams = (since && until) ? { time_range: JSON.stringify({ since, until }) } : { date_preset: PRESET_MAP[period] || 'last_30_d' };

  try {
    // Fetch all ad sets with their targeting spec
    const adsetData = await metaGet(`/${META_ACCOUNT}/adsets`, {
      fields: 'id,name,status,targeting',
      limit: 200,
    });
    const adsets = adsetData.data || [];

    // Fetch insights for all ad sets in one call
    const insightData = await metaGet(`/${META_ACCOUNT}/insights`, {
      fields: 'adset_id,adset_name,spend,impressions,clicks,reach,actions,action_values,purchase_roas',
      ...timeParams,
      level: 'adset',
      limit: 200,
    });
    const insightMap = {};
    for (const row of (insightData.data || [])) {
      const purchases = parseFloat((row.actions||[]).find(a=>a.action_type==='purchase')?.value||0);
      const revenue   = parseFloat((row.action_values||[]).find(a=>a.action_type==='purchase')?.value||0);
      const roas      = row.purchase_roas?.[0]?.value ? parseFloat(row.purchase_roas[0].value) : (revenue && row.spend ? parseFloat(revenue)/parseFloat(row.spend) : 0);
      const cpp       = purchases > 0 ? parseFloat((parseFloat(row.spend||0)/purchases).toFixed(2)) : 0;
      insightMap[row.adset_id] = {
        spend: parseFloat(row.spend||0), impressions: parseInt(row.impressions||0),
        clicks: parseInt(row.clicks||0), reach: parseInt(row.reach||0),
        purchases, revenue, roas, cpp,
      };
    }

    // Extract interest names from targeting spec
    const extractInterests = (targeting) => {
      if (!targeting) return [];
      const interests = [];
      // flexible_spec: [{interests:[{id,name},...]}]
      const flexSpec = targeting.flexible_spec || [];
      for (const group of flexSpec) {
        for (const interest of (group.interests || [])) {
          if (interest.name) interests.push(interest.name);
        }
        // behaviors
        for (const b of (group.behaviors || [])) {
          if (b.name) interests.push(b.name);
        }
      }
      // Also check top-level interests (older format)
      for (const interest of (targeting.interests || [])) {
        if (interest.name && !interests.includes(interest.name)) interests.push(interest.name);
      }
      return interests;
    };

    // Build per-adset result with interests + performance
    const rows = [];
    const interestRollup = {}; // aggregate across adsets sharing an interest

    for (const adset of adsets) {
      const perf = insightMap[adset.id] || null;
      const interests = extractInterests(adset.targeting);
      const targeting = adset.targeting || {};
      const ageMin = targeting.age_min || null;
      const ageMax = targeting.age_max || null;
      const genders = (targeting.genders || []).map(g => g===1?'Male':g===2?'Female':'All').join(', ') || 'All';

      rows.push({
        adset_id:  adset.id,
        adset:     adset.name,
        status:    adset.status,
        interests,
        age:       ageMin && ageMax ? `${ageMin}–${ageMax}` : ageMin ? `${ageMin}+` : 'All',
        gender:    genders,
        ...(perf || { spend:0, impressions:0, clicks:0, reach:0, purchases:0, revenue:0, roas:0, cpp:0 }),
        has_data:  !!perf,
      });

      // Roll up by individual interest
      for (const name of interests) {
        if (!interestRollup[name]) interestRollup[name] = { interest:name, adsets:0, spend:0, revenue:0, purchases:0, impressions:0, clicks:0, reach:0, roas_sum:0, roas_count:0 };
        const r = interestRollup[name];
        r.adsets++;
        if (perf) {
          r.spend       += perf.spend;
          r.revenue     += perf.revenue;
          r.purchases   += perf.purchases;
          r.impressions += perf.impressions;
          r.clicks      += perf.clicks;
          r.reach       += perf.reach;
          if (perf.roas > 0) { r.roas_sum += perf.roas; r.roas_count++; }
        }
      }
    }

    // Compute aggregate ROAS per interest
    const byInterest = Object.values(interestRollup).map(r => ({
      interest:    r.interest,
      adsets:      r.adsets,
      spend:       parseFloat(r.spend.toFixed(2)),
      revenue:     parseFloat(r.revenue.toFixed(2)),
      roas:        r.roas_count > 0 ? parseFloat((r.roas_sum / r.roas_count).toFixed(2)) : (r.revenue && r.spend ? parseFloat((r.revenue/r.spend).toFixed(2)) : 0),
      purchases:   r.purchases,
      cpp:         r.purchases > 0 ? parseFloat((r.spend/r.purchases).toFixed(2)) : 0,
      impressions: r.impressions,
      clicks:      r.clicks,
      ctr:         r.impressions > 0 ? parseFloat(((r.clicks/r.impressions)*100).toFixed(2)) : 0,
    })).sort((a,b) => b.roas - a.roas);

    res.json({ ok:true, period, byInterest, byAdset: rows.sort((a,b) => b.roas - a.roas) });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

