const { ObjectId: SC_ObjectId } = require('mongodb');
const STOREFRONT_URL = process.env.STOREFRONT_URL || 'https://croscrow.com';
const SUPPORT_TRACK_URL = (orderName) => `${SERVER_URL}/o/${encodeURIComponent(String(orderName).replace(/^#/, ''))}`;

const SC = {
  async createChat({ shop_domain, customer_email, customer_phone }) {
    const doc = {
      shop_domain: shop_domain || null,
      customer_email: (customer_email||'').toLowerCase().trim() || null,
      customer_phone: (customer_phone||'').replace(/\D/g,'').slice(-10) || null,
      order_name: null, shopify_order_id: null, vendor_names: [],
      status: 'open', hidden_from_vendors: false, vendor_notified_at: null,
      tags: [], resolved: false, resolved_at: null, resolved_by: null,
      source: 'web',
      created_at: new Date().toISOString(), updated_at: new Date().toISOString(),
    };
    const r = await mdb.collection('support_chats').insertOne(doc);
    return { _id: r.insertedId, ...doc };
  },
  async get(chatId) {
    return mdb.collection('support_chats').findOne({ _id: new SC_ObjectId(String(chatId)) });
  },
  async update(chatId, fields) {
    await mdb.collection('support_chats').updateOne({ _id: new SC_ObjectId(String(chatId)) }, { $set: { ...fields, updated_at: new Date().toISOString() } });
  },
  async addMessage(chatId, { sender, sender_name = '', text = '', meta = null }) {
    const msg = { chat_id: String(chatId), sender, sender_name, text, meta, created_at: new Date().toISOString() };
    await mdb.collection('support_messages').insertOne(msg);
    return msg;
  },
  async messages(chatId, afterTs = null) {
    const q = { chat_id: String(chatId) };
    if (afterTs) q.created_at = { $gt: afterTs };
    return mdb.collection('support_messages').find(q, { projection: { _id: 0 } }).sort({ created_at: 1 }).toArray();
  },
};

function signSupportToken(chatId, vendorName) {
  const payload = `${chatId}.${Buffer.from(vendorName).toString('base64url')}.${Date.now() + 30*24*3600*1000}`;
  const sig = crypto.createHmac('sha256', process.env.VENDOR_APP_SECRET || 'fallback-secret').update(payload).digest('hex').slice(0, 24);
  return Buffer.from(`${payload}.${sig}`).toString('base64url');
}
function verifySupportToken(token) {
  try {
    const decoded = Buffer.from(token, 'base64url').toString('utf8');
    const [chatId, vendorB64, expiry, sig] = decoded.split('.');
    const payload = `${chatId}.${vendorB64}.${expiry}`;
    const expectedSig = crypto.createHmac('sha256', process.env.VENDOR_APP_SECRET || 'fallback-secret').update(payload).digest('hex').slice(0, 24);
    if (sig !== expectedSig) return null;
    if (Date.now() > parseInt(expiry)) return null;
    return { chatId, vendorName: Buffer.from(vendorB64, 'base64url').toString('utf8') };
  } catch { return null; }
}

// ── Support bot tools ───────────────────────────────────────────────────────
async function scSearchProducts(query) {
  try {
    // Check if any curated category matches the query — use those first
    if (mdb) {
      const normalised = query.toLowerCase();
      const CATEGORY_KEYWORDS = {
        tees: ['tee','tees','t-shirt','tshirt','t shirt'],
        hoodies: ['hoodie','hoodies','sweatshirt'],
        shirts: ['shirt','shirts','oxford','formal shirt'],
        jeans: ['jeans','denim','denims'],
        joggers: ['jogger','joggers','track pant'],
        coords: ['coord','co-ord','co ord','coords','set'],
        jackets: ['jacket','jackets','bomber'],
        shorts: ['short','shorts'],
      };
      let matchedCategory = null;
      for (const [cat, kws] of Object.entries(CATEGORY_KEYWORDS)) {
        if (kws.some(kw => normalised.includes(kw))) { matchedCategory = cat; break; }
      }
      if (matchedCategory) {
        const doc = await mdb.collection('wa_featured_products').findOne({ category: matchedCategory });
        if (doc?.mode === 'url' && doc?.collection_url) {
          // URL mode — return the collection link directly, no product cards
          const catLabels = { tees:'Tees', hoodies:'Hoodies', shirts:'Shirts', jeans:'Jeans / Denim', joggers:'Joggers', coords:'Co-ords & Sets', jackets:'Jackets', shorts:'Shorts' };
          return { found: 0, products: [], collections: [{ title: catLabels[matchedCategory] || matchedCategory, url: doc.collection_url }], curated_url: true };
        }
        if (doc?.products?.length) {
          return { found: doc.products.length, products: doc.products.slice(0, 8), collections: [], curated: true };
        }
      }
    }

    // Shopify's REST /products.json?title= is an EXACT match, not a substring
    // search — "boxy fit" finds nothing even when "MOCKING BIRD BOXY FIT
    // SHIRT" exists. GraphQL's query syntax supports real wildcard search,
    // but it's still a literal substring match — "shirts" (plural) does NOT
    // match "T-SHIRT" (singular) since "shirts" isn't a substring of "shirt".
    // Widen each word with its singular form (strip trailing 's') so plural
    // search terms still find singular product titles, which is the common
    // case (verified: "shirts" found 0 products until this was added).
    const words = query.trim().split(/\s+/).filter(Boolean);
    const mentionsTshirt = /t[\s-]?shirt/i.test(query);

    function clauseForWord(w) {
      const variants = new Set([w]);
      if (w.length > 3 && /s$/i.test(w)) variants.add(w.slice(0, -1));
      const singular = w.toLowerCase().replace(/s$/, '');
      // "shirt"/"shirts" alone means collared shirts in this catalog, distinct
      // from "T-Shirts" — without this, *shirt* also matches "T-SHIRT" titles
      // since "shirt" is a literal substring of "t-shirt" (verified bug:
      // searching "shirts" surfaced T-shirts instead of actual shirts).
      if (singular === 'shirt' && !mentionsTshirt) {
        return `(title:*shirt* AND NOT title:*t-shirt* AND NOT title:*tshirt* AND NOT title:*t shirt*)`;
      }
      return `(${[...variants].map(v => `title:*${v}*`).join(' OR ')})`;
    }

    const terms = words.map(clauseForWord).join(' OR ');
    const collTerms = clauseForWord(words[0] || '');

    // Also search by vendor tag and full query phrase for better name matching
    const fullPhrase = query.trim().replace(/"/g, '');
    const [productData, collectionData, nameData] = await Promise.all([
      shopifyGQL(`{ products(first: 12, query: "status:active AND (${terms})") {
        edges { node { title handle featuredImage { url }
          variants(first: 10) { edges { node { price availableForSale } } } } } } }`),
      shopifyGQL(`{ collections(first: 3, query: "${collTerms}") {
        edges { node { title handle image { url } } } } }`),
      // Exact phrase / product name search (catches "MOCKING BIRD BOXY FIT" style names)
      shopifyGQL(`{ products(first: 8, query: "status:active AND title:*${fullPhrase}*") {
        edges { node { title handle featuredImage { url }
          variants(first: 10) { edges { node { price availableForSale } } } } } } }`),
    ]);

    const seenHandles = new Set();
    const dedup = (node) => { if (seenHandles.has(node.handle)) return false; seenHandles.add(node.handle); return true; };

    const nameEdges = (nameData.data?.products?.edges || []).map(e => e.node).filter(p => p.variants.edges.some(v => v.node.availableForSale));
    const kwEdges = (productData.data?.products?.edges || []).map(e => e.node).filter(p => p.variants.edges.some(v => v.node.availableForSale));
    // Name-matches first (more precise), then keyword matches
    const products = [...nameEdges, ...kwEdges].filter(dedup);

    const collections = (collectionData.data?.collections?.edges || []).map(e => ({
      title: e.node.title,
      url: `${STOREFRONT_URL}/collections/${e.node.handle}`,
      image: e.node.image?.url || null,
    }));

    return {
      found: products.length,
      products: products.slice(0, 8).map(p => ({
        title: p.title,
        url: `${STOREFRONT_URL}/products/${p.handle}`,
        image: p.featuredImage?.url || null,
        price_from: Math.min(...p.variants.edges.map(v => parseFloat(v.node.price) || Infinity)),
      })),
      collections,
    };
  } catch (e) { return { found: 0, products: [], collections: [], error: e.message }; }
}

async function scGetOrderStatus(orderName, contact) {
  try {
    const normalized = String(orderName).replace(/^#/, '').trim();
    const name = `#${normalized}`;
    const data = await shopifyREST(`/orders.json?name=${encodeURIComponent(name)}&status=any&limit=10`);
    const orders = data.orders || [];
    const contactClean = (contact||'').toLowerCase().trim();
    const contactPhone = normalizePhone(contact||'');
    let order = orders.find(o => {
      const oEmail = (o.email || o.contact_email || o.billing_address?.email || '').toLowerCase().trim();
      const oPhone = normalizePhone(o.shipping_address?.phone || o.billing_address?.phone || o.phone || '');
      return oEmail === contactClean || (contactPhone.length >= 10 && oPhone === contactPhone);
    });
    if (!order) order = orders[0]; // fall back if contact doesn't match but order exists — bot will just not over-claim certainty
    if (!order) return { found: false, message: 'Order not found. Please double check the order number.' };
    const payload = await buildOrderPayload(order);
    // Orders stuck in new/hold, or cancelled before confirmation, need the
    // customer to actively confirm them — surface that link directly so the
    // bot can offer it instead of just explaining the order isn't moving.
    const DISPATCHED_STAGES = ['ready','pickup','transit','ofd','delivered','rto','cancelled'];
    const isPrepaidOrder = order.financial_status === 'paid';
    const metaDoc = await mdb.collection('order_meta').findOne({ shopify_id: String(order.id) }, { projection: { advance_paid:1, confirmation_paid:1, _id:0 } }) || {};
    const alreadyPaid = !!(metaDoc.confirmation_paid) || (parseFloat(metaDoc.advance_paid||0) >= 99) || isPrepaidOrder;
    const needsConfirm = !isPrepaidOrder && !alreadyPaid && !DISPATCHED_STAGES.includes(payload.stage);
    const orderPageUrl = `${SERVER_URL}/o/${encodeURIComponent(payload.order_name.replace(/^#/, ''))}`;
    const confirm_url = needsConfirm ? orderPageUrl : null;
    const track_url   = needsConfirm ? null : orderPageUrl;
    return { found: true, ...payload, track_url, confirm_url, needs_confirm: needsConfirm };
  } catch (e) { return { found: false, error: e.message }; }
}

async function scGetDelayReason(orderName, contact) {
  const status = await scGetOrderStatus(orderName, contact);
  if (!status.found) return status;
  const reasons = [];
  for (const v of status.vendor_names || []) {
    const r = await mdb.collection('delay_remarks').findOne(
      { shopify_id: String(status.shopify_order_id), vendor_name: v },
      { sort: { submitted_at: -1 }, projection: { _id: 0 } }
    );
    if (r) reasons.push({ vendor: v, reason: r.reason, eta_date: r.eta_date });
  }
  if (reasons.length) return { found: true, has_specific_reason: true, reasons, order_name: status.order_name };
  return {
    found: true, has_specific_reason: false, order_name: status.order_name,
    generic_message: "There's a slight delay — likely routine warehouse processing time on the vendor's side. It should move to dispatch shortly; we'll keep you posted.",
  };
}

async function scStartReturnExchange(orderName, contact) {
  const status = await scGetOrderStatus(orderName, contact);
  if (!status.found) return status;
  const num = String(status.order_name).replace(/^#/, '');
  const returns_url = `${SERVER_URL}/returns?o=${encodeURIComponent(num)}&contact=na`;
  return {
    found: true, order_name: status.order_name, track_url: returns_url,
    return_configs: status.return_configs,
    message: 'Returns and exchanges can be raised from the link below — photo upload, reason selection and pickup scheduling are all there.',
  };
}

async function scCheckOrderConfirmation(orderName) {
  try {
    const normalized = String(orderName).replace(/^#/, '').trim();
    const name = `#${normalized}`;
    const data = await shopifyREST(`/orders.json?name=${encodeURIComponent(name)}&status=any&limit=5`);
    const order = (data.orders || [])[0];
    if (!order) return { found: false, message: 'Order not found. Please check the order number.' };
    const tags = (order.tags || '').split(',').map(t => t.trim().toLowerCase());
    const confirmed = tags.includes('order confirmed');
    return {
      found: true,
      order_name: order.name,
      confirmed,
      financial_status: order.financial_status,
      confirm_url: confirmed ? null : `${SERVER_URL}/o/${encodeURIComponent(order.name.replace(/^#/, ''))}`,
    };
  } catch (e) { return { found: false, error: e.message }; }
}

const SUPPORT_TOOLS = [
  { type:'function', function:{ name:'search_products', description:'Search the CROSCROW catalog for products by name/keyword (e.g. "sweatpants", "waffle hoodie"). Use when the customer is browsing/shopping, not asking about an existing order. If the result has curated_url=true and no products but has a collections entry, reply with "Here\'s our [category] collection — browse and pick what you like:" and the link is appended automatically. Do NOT say the link is below your message in this case — just use a natural sentence.', parameters:{ type:'object', properties:{ query:{type:'string'} }, required:['query'] } } },
  { type:'function', function:{ name:'get_order_status', description:'Look up a specific order\'s live status, stage, AWB, and per-vendor shipment details. Requires the order number; ask for it if not given.', parameters:{ type:'object', properties:{ order_name:{type:'string', description:'Order number, with or without #'} }, required:['order_name'] } } },
  { type:'function', function:{ name:'get_delay_reason', description:'Explain why an order has not shipped yet — checks if the vendor submitted a specific delay reason, otherwise gives a generic explanation.', parameters:{ type:'object', properties:{ order_name:{type:'string'} }, required:['order_name'] } } },
  { type:'function', function:{ name:'start_return_exchange', description:'Customer wants to return or exchange an item from an order. Returns a link to the self-serve return/exchange flow.', parameters:{ type:'object', properties:{ order_name:{type:'string'} }, required:['order_name'] } } },
  { type:'function', function:{ name:'check_order_confirmation', description:'Check if a COD order has been confirmed (has Order Confirmed tag on Shopify). Use when customer asks about confirming their order, says they already paid ₹99, or says the confirmation link is not working.', parameters:{ type:'object', properties:{ order_name:{type:'string'} }, required:['order_name'] } } },
  { type:'function', function:{ name:'get_orders_by_phone', description:'Look up ALL orders placed by this customer using their WhatsApp phone number. Use this when customer doesn\'t know or doesn\'t mention their order number — do NOT ask for order number first, call this tool immediately. Returns their most recent orders so you can help without making them search.', parameters:{ type:'object', properties:{}, required:[] } } },
  { type:'function', function:{ name:'get_return_status', description:'Check the status of a return or exchange request for a given order number. Use when customer asks "where is my return?", "when will I get my refund?", "what happened to my exchange?" etc.', parameters:{ type:'object', properties:{ order_name:{type:'string'} }, required:['order_name'] } } },
];

async function scGetOrdersByPhone(phone) {
  if (!phone || phone === 'unknown') return { found: false, message: 'Phone number not available' };
  const digits = String(phone).replace(/\D/g, '').replace(/^91/, '').slice(-10);
  if (digits.length !== 10) return { found: false, message: 'Could not determine phone number' };
  const orders = await mdb.collection('order_meta').find(
    { customer_phone: { $regex: digits } },
    { projection: { shopify_id: 1, order_name: 1, stage: 1, created_at: 1, customer_name: 1, _id: 0 } }
  ).sort({ created_at: -1 }).limit(3).toArray();
  if (!orders.length) return { found: false, message: 'No orders found for this phone number' };
  // For most recent order, get full status
  const top = orders[0];
  const fullStatus = await scGetOrderStatus(top.order_name, 'na');
  return { found: true, orders: orders.map(o => ({ order_name: o.order_name, stage: o.stage, placed_at: o.created_at })), primary: fullStatus };
}

async function scGetReturnStatus(order_name) {
  if (!order_name) return { found: false, message: 'Order number required' };
  const name = String(order_name).replace(/^#/, '').trim();
  const rr = await mdb.collection('return_requests').findOne(
    { order_name: { $regex: name, $options: 'i' } },
    { sort: { created_at: -1 }, projection: { request_id:1, type:1, status:1, items:1, created_at:1, reverse_shipment:1, forward_shipment:1, _id:0 } }
  );
  if (!rr) return { found: false, message: `No return or exchange request found for order #${name}` };
  const STATUS_LABELS = { pending:'Request received', submitted:'Request received', approved:'Approved', pickup_scheduled:'Pickup scheduled', picked_up:'Item picked up', received:'Received at warehouse', received_at_warehouse:'Received at warehouse', qc:'Quality check', refund_initiated:'Refund initiated', exchange_dispatched:'Exchange shipped', completed:'Completed', rejected:'Rejected', cancelled:'Cancelled' };
  return {
    found: true,
    type: rr.type || 'return',
    status: rr.status,
    status_label: STATUS_LABELS[rr.status] || rr.status,
    items: (rr.items || []).map(i => i.title || i.product_title || 'item'),
    created_at: rr.created_at,
    awb: rr.reverse_shipment?.awb || rr.forward_shipment?.awb || null,
  };
}

async function scRunTool(name, args, contact) {
  switch (name) {
    case 'search_products':          return scSearchProducts(args.query);
    case 'get_order_status':         return scGetOrderStatus(args.order_name, contact);
    case 'get_delay_reason':         return scGetDelayReason(args.order_name, contact);
    case 'start_return_exchange':    return scStartReturnExchange(args.order_name, contact);
    case 'check_order_confirmation': return scCheckOrderConfirmation(args.order_name);
    case 'get_orders_by_phone':      return scGetOrdersByPhone(contact);
    case 'get_return_status':        return scGetReturnStatus(args.order_name);
    default: return { error: 'Unknown tool' };
  }
}

const SC_SYSTEM_PROMPT = `You are the CROSCROW support concierge — warm, sharp, concise, never robotic. You help customers:
1. Find products ("I'm looking for sweatpants") — use search_products, then describe 2-3 best matches naturally and mention they're shown as cards below your message. If a matching collection page is returned too, mention they can browse the full collection for more options.
2. Track orders — use get_order_status. Always ask for the order number if not given. Once you have it, briefly summarize the status in plain words (the actual tracking/confirm card is shown automatically below your message). If the result has needs_confirm=true, tell the customer they need to pay ₹99 to get the order moving — the link is shown below. Keep it to one short sentence.
3. Explain delays — use get_delay_reason. If there's a specific vendor reason, relay it warmly with the ETA. If not, use the generic explanation, but reassure them it's being handled.
4. Returns/exchanges — use start_return_exchange and point them to the link/card shown below your message.
Rules:
- CRITICAL: call the relevant tool again on EVERY turn that needs order/product/delay data — even if you already looked up the exact same order or search term earlier in this conversation, even if the customer is just confirming ("yes", "yes status", "ok check it") rather than asking something new. Never answer from memory of an earlier tool result in this conversation. If your reply mentions a "card below" or any specific status/price/stage, that information must come from a tool call you just made in THIS turn — if you didn't call a tool this turn, you have no card to refer to, so don't claim one is shown.
- Keep replies short (2-4 sentences max), human, no corporate phrasing.
- If a customer is venting/frustrated, acknowledge it briefly before helping.
- If something is outside what your tools can do, say you're flagging it for a human and that's fine.`;

const SC_WHATSAPP_SYSTEM_PROMPT = `You are the CROSCROW support concierge — warm, sharp, concise, never robotic. You're replying on WhatsApp so there are NO cards or buttons — only plain text.

TOOLS:
0. get_orders_by_phone — use IMMEDIATELY when customer doesn't mention their order number or doesn't know it. Do NOT ask them to find the number — call this tool first. It auto-looks up their orders by WhatsApp number. If you get results, present the most recent order status and ask if this is the one they're asking about.
1. search_products — use this for ANY product mention: category browsing ("show me hoodies"), specific product name ("do you have MOCKING BIRD shirt?"), or vague requests ("something in black"). Always call this before answering about products — you have no catalog knowledge without it. Two possible results:
   • If result has products: describe 2-3 matches naturally ("We have X, Y and Z — here are the links:"). Links follow automatically.
   • If result has curated_url=true (no products, just a collections entry): say something like "Here's our full [category] collection — browse and pick what you like 👇" and the link is appended automatically. Keep it short.
2. get_order_status — track any order. Returns rich data — USE ALL OF IT to give a complete answer:
   • stage + stage_label: current position in lifecycle (confirmed / dispatched / in transit / delivered etc.)
   • awb: courier tracking number — share this if customer asks
   • courier: which courier company (Delhivery, Shiprocket, etc.) — mention by name
   • delivery_status: live courier scan update (e.g. "In Transit at Delhi HUB", "Out for Delivery") — always share this if present
   • delivery_status_updated_at: when that scan happened
   • vendor_shipments[].confirmed_at: when vendor confirmed the order
   • vendor_shipments[].dispatched_at: when vendor actually dispatched (handed to courier)
   • vendor_shipments[].hours_waiting_dispatch: hours spent in confirmed state — if >48, the order is delayed
   • vendor_shipments[].delay_remark: if vendor submitted a delay reason, it has .reason, .eta_date, .submitted_at — relay this to customer
   • created_at: order placed date — use to estimate delivery if no AWB yet (placed + 5-7 days typical)
   Use these together: if stage=transit and delivery_status="In Transit at Delhi HUB", say "Your order is on the way — last scan shows it's at Delhi hub. Should reach you in 1-2 days 🚚"
   If stage=confirmed and hours_waiting_dispatch>48, say "Order's been ready but not yet dispatched (Xh delay) — I'm flagging this to our team right now" (flags admin).
   If delay_remark exists: "The vendor mentioned [reason] and expects to dispatch by [eta_date] (submitted [submitted_at]) — apologies for the wait 🙏"
3. get_delay_reason — additional context on why order hasn't shipped. Relay vendor reason warmly with ETA if available.
4. start_return_exchange — customer wants return/exchange. Link follows automatically.
5. check_order_confirmation — use whenever customer mentions confirming order, ₹99 payment, or confirmation link.
6. get_return_status — use when customer asks about their return, exchange status, or refund update by order number. Gives live RR request status (pickup_scheduled, picked_up, refund_initiated etc.).

ORDER CONFIRMATION PROCESS (very important — know this well):
- CROSCROW requires a ₹99 advance for all COD orders before dispatch. NOT an extra charge — adjusted at delivery (customer pays ₹99 less COD).
- Any COD order that isn't prepaid and hasn't paid ₹99 yet will have needs_confirm=true in get_order_status result. The confirmation+payment page link is sent automatically after your reply — do NOT repeat it in your message.
- When needs_confirm=true: send this exact message (no changes): "Your order needs a ₹99 confirmation to start dispatch — this small step lets us know you're ready to receive it, so we don't pack and ship an order that gets rejected at the door 😊 Tap below — it's adjusted at delivery, not extra." The link follows automatically — do NOT add the URL yourself.

HOW TO HANDLE EACH CONFIRMATION SCENARIO:
- Customer asks order status and needs_confirm=true → use the exact message above, nothing else.
- Customer asks "how do I confirm?" or link not received → use get_order_status, if needs_confirm say: "Here's your payment link 👇" (link follows automatically)
- "Link not working / payment page not opening" → say: "I've flagged this to our team right now, they'll send you an alternative shortly." (flags admin)
- "I already paid ₹99 / sent screenshot" → say: "Got it! Our team will verify and confirm your order within a few hours 🙏"
- "Why ₹99? Other sites don't do this" → say: "It's adjusted at delivery — you pay ₹99 less COD. Confirms the order is genuine so we dispatch faster 😊"
- "I'll pay full on delivery / don't want to pay ₹99" → say: "Noted, flagging to our team — they'll manually confirm it. Keep full amount ready at delivery." (flags admin)
- "I already confirmed but still getting messages" → use get_order_status; if needs_confirm=false say "You're confirmed — messages were sent before the update. All good!"; if still needs_confirm say "Flagging to our team to resolve right now." (flags admin)
- "I want to cancel my order" → say: "Flagged to our team — they'll process it within a few hours and confirm over WhatsApp." (flags admin)
- "How long will delivery take?" / "When will it arrive?" / "Can you deliver by [date]?" → follow this logic in order:
  1. If delivery_status has a live update (e.g. "Out for Delivery", "In Transit at Delhi") — share that exact status: "Your order is currently [delivery_status]. You should receive it very soon!"
  2. If AWB exists but no live delivery_status — use the dispatch date from the order (created_at or fulfillment date) to give a rough estimate: "Your order was dispatched on [date] — it typically takes 3–5 days to arrive, so you should receive it around [dispatch date + 4 days]. If you need a more precise update, I can connect you with our team 👇\n\n1️⃣ Connect with support team\n\nOr call: 📞 *6375668971* | 🕐 2–8 PM" and set session menu to offer_human.
  3. If no AWB yet (not dispatched) — say: "Your order is being prepared by the vendor and hasn't shipped yet. Once dispatched, it typically takes 3–5 days to reach you. I've flagged this to our team to prioritize dispatch." (flags admin)
  NEVER invent a specific confirmed date. Use rough estimates only when AWB exists.

REFUND RULES (very important):
- "How many days for refund?" or "When will I get my refund?" or "Refund status?" → say: "Once your returned product reaches us (which usually takes 5–10 days after pickup), we process the refund within 24 hours of quality check. I'm looping in our team to confirm the current status of your return 🙏" (flags admin). Do NOT try to compute a date yourself.
- "I returned the product, when will I get money back?" → same as above — give the SLA, flag admin.
- "I want a refund" → use get_order_status first to understand the stage, then say: "I've noted your refund request and flagged it to our team — they'll reach out to you shortly on WhatsApp 🙏" (flags admin).
- For RTO orders (returned to origin): refund is processed within 3-5 business days once item is received at our warehouse.

ORDER NUMBER HELP:
- If customer seems to not know their order number, IMMEDIATELY call get_orders_by_phone — it automatically looks them up by their WhatsApp number. Do NOT ask them to find their order number first. Just say "Let me check your orders right away!" and call the tool. Only if get_orders_by_phone returns no results should you ask them to check their confirmation message.
- get_return_status — use when customer asks about their return, exchange, or refund status by order number. Gives current status of RR request.
- get_orders_by_phone returns their most recent orders automatically — no phone number argument needed.

RULES:
- CRITICAL: call the relevant tool on EVERY turn that needs live data. Never answer from memory.
- No markdown. Plain text only. Short replies (2-4 sentences). Human, warm tone.
- If customer is frustrated, acknowledge briefly first.
- When you say you're "flagging to our team", that triggers an automatic admin alert — always say this exact phrase for the scenarios listed above.
- NEVER mention rate limits, API errors, or technical issues. If something fails just say "Give me a moment, trying again!" or similar.
- NEVER include any tracking URL in your message — not courier URLs (delhivery.com, shiprocket.com etc.) AND NOT the CROSCROW track link either. A tracking link is ALWAYS appended automatically after your reply. Including one yourself causes a duplicate link in the message.
- If the customer asks to call them, says "call me", or needs something only a human can handle, say: "I can't make calls, but I'm connecting you with our team right now — someone will reach out to you on WhatsApp shortly 🙏" (this flags admin).
- For multi-vendor orders where items haven't shipped yet: modifications or cancellations ARE possible before dispatch. Say "Since the order hasn't shipped yet, I've flagged this to our team and they can make the change for you." (flags admin). Don't say items can't be separated — that's the vendor's call, not yours.
- For cancelled orders: never show a confirm link. Just explain the order is cancelled and ask if they'd like to place a fresh one.`;

// Builds a plain-text links section to append to WhatsApp replies when meta has URLs
function waLinksFromMeta(meta) {
  if (!meta) return '';
  const lines = [];
  if (meta.type === 'tracking_card') {
    const d = meta.data;
    // Single /order page handles both confirm and track — no separate links needed
    const orderUrl = d.order_name
      ? `${SERVER_URL}/o/${encodeURIComponent(String(d.order_name).replace(/^#/,''))}`
      : d.track_url || d.confirm_url;
    if (d.needs_confirm && orderUrl) {
      lines.push(`💳 Pay ₹99 & confirm: ${orderUrl}`);
    } else if (orderUrl) {
      lines.push(`📦 Track your order: ${orderUrl}`);
    }
    if (d.return_requests?.length) {
      const open = d.return_requests.find(r => !['completed','rejected','cancelled'].includes(r.status));
      if (open) {
        const rrNum = String(d.order_name||'').replace(/^#/,'');
        lines.push(`🔄 Return/Exchange status: ${SERVER_URL}/returns?o=${encodeURIComponent(rrNum)}&contact=na`);
      }
    }
  } else if (meta.type === 'action_link') {
    lines.push(`🔗 ${meta.data.label}: ${meta.data.url}`);
  } else if (meta.type === 'product_cards') {
    const { products = [], collections = [] } = meta.data;
    products.slice(0, 3).forEach(p => lines.push(`• ${p.title}${p.price_from ? ` — ₹${p.price_from}` : ''}\n  ${p.url}`));
    collections.slice(0, 2).forEach(c => lines.push(`🛍️ Browse ${c.title}: ${c.url}`));
  }
  return lines.length ? '\n\n' + lines.join('\n') : '';
}

async function scCallLLM(messages) {
  const DEEPSEEK_KEY = process.env.DEEPSEEK_API_KEY;
  const GROQ_KEY = process.env.GROQ_API_KEY;
  const attempt = async (apiUrl, apiKey, model) => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 25000); // 25s timeout
    try {
      const r = await fetch(apiUrl, {
        method:'POST',
        headers:{ 'Content-Type':'application/json', 'Authorization':`Bearer ${apiKey}` },
        body: JSON.stringify({ model, max_tokens:800, messages, tools: SUPPORT_TOOLS, tool_choice:'auto' }),
        signal: controller.signal,
      });
      const d = await r.json();
      if (!r.ok) throw new Error(d.error?.message || `${model} ${r.status}`);
      return d;
    } finally { clearTimeout(timer); }
  };
  if (DEEPSEEK_KEY) {
    try { return await attempt('https://api.deepseek.com/chat/completions', DEEPSEEK_KEY, 'deepseek-chat'); }
    catch (e) { console.error('Support chat DeepSeek failed, falling back to Groq:', e.message); if (!GROQ_KEY) throw e; }
  }
  if (GROQ_KEY) return attempt('https://api.groq.com/openai/v1/chat/completions', GROQ_KEY, 'llama-3.3-70b-versatile');
  throw new Error('No AI key configured (DEEPSEEK_API_KEY or GROQ_API_KEY)');
}

async function scRunChatTurn(chat, history, customerText, { systemPrompt, forceContact } = {}) {
  const contact = forceContact || chat.customer_email || chat.customer_phone || '';
  // Trim to last 12 messages — prevents context pollution when customer queries multiple orders
  const recentHistory = history.slice(-12);
  // Inject known context (order memory, customer name) so bot doesn't re-ask
  let sysContent = systemPrompt || SC_SYSTEM_PROMPT;
  const knownOrder = chat.order_name || chat.last_order_name || null;
  const knownName = chat.customer_name || null;
  if (knownOrder || knownName) {
    const hints = [];
    if (knownName) hints.push(`Customer's name: ${knownName}`);
    if (knownOrder) hints.push(`Customer's most recent order: #${String(knownOrder).replace(/^#/, '')} — use this if they ask without specifying an order number`);
    sysContent = sysContent + `\n\n[Known context: ${hints.join(' | ')}]`;
  }
  const messages = [
    { role:'system', content: sysContent },
    ...recentHistory.map(m => ({ role: m.sender === 'customer' ? 'user' : (m.sender === 'assistant' ? 'assistant' : 'user'), content: m.sender==='vendor'||m.sender==='admin' ? `[${m.sender} note: ${m.text}]` : m.text })),
    { role:'user', content: customerText },
  ];

  let finalReply = '';
  let cardMeta = null;
  const newTags = new Set();
  for (let turn = 0; turn < 4; turn++) {
    const d = await scCallLLM(messages);
    const choice = d.choices?.[0];
    const msg = choice?.message;
    if (choice?.finish_reason === 'tool_calls' && msg?.tool_calls?.length) {
      messages.push(msg);
      for (const tc of msg.tool_calls) {
        let args = {}; try { args = JSON.parse(tc.function.arguments || '{}'); } catch {}
        const result = await scRunTool(tc.function.name, args, contact);
        if (tc.function.name === 'get_order_status' && result.found) {
          const existingChat = await scFindExistingChatForOrder(result.shopify_order_id, chat._id);
          cardMeta = { type:'tracking_card', data: { ...result, existing_chat: existingChat } };
          if (['new','confirmed','partial','hold'].includes(result.stage)) newTags.add('Not Dispatched');
          if (result.stage === 'rto') newTags.add('RTO');
          const openExchange = (result.return_requests||[]).find(r => r.type === 'exchange' && !['completed','rejected','cancelled'].includes(r.status));
          if (openExchange) newTags.add('Exchange Pending');
        }
        else if (tc.function.name === 'search_products' && (result.found || result.collections?.length)) { cardMeta = { type:'product_cards', data: { products: result.products, collections: result.collections || [] } }; newTags.add('Product Inquiry'); }
        else if (tc.function.name === 'start_return_exchange' && result.found) { cardMeta = { type:'action_link', data: { label:'Open Return/Exchange', url: result.track_url } }; newTags.add('Exchange Issue'); }
        else if (tc.function.name === 'get_orders_by_phone' && result.found && result.primary?.found) {
          const p = result.primary;
          const existingChat = await scFindExistingChatForOrder(p.shopify_order_id, chat._id);
          cardMeta = { type:'tracking_card', data: { ...p, existing_chat: existingChat } };
          if (['new','confirmed','partial','hold'].includes(p.stage)) newTags.add('Not Dispatched');
          if (p.stage === 'rto') newTags.add('RTO');
          if (p.shopify_order_id) await SC.update(chat._id, { order_name: p.order_name, shopify_order_id: String(p.shopify_order_id), vendor_names: p.vendor_names || [] });
        }
        else if (tc.function.name === 'get_return_status' && result.found) { newTags.add(result.type === 'exchange' ? 'Exchange Issue' : 'Return Issue'); }
        else if (tc.function.name === 'get_delay_reason') newTags.add('Delay Inquiry');
        else if (tc.function.name === 'check_order_confirmation') {
          newTags.add('Confirmation Query');
          // check_order_confirmation is legacy — get_order_status now handles confirm/track in one page
          if (result.found && !result.confirmed) {
            const orderUrl = result.confirm_url || result.track_url;
            if (orderUrl) cardMeta = { type:'action_link', data: { label:'Pay ₹99 & Confirm Order', url: orderUrl } };
          }
        }
        if (result.shopify_order_id) {
          await SC.update(chat._id, { order_name: result.order_name, shopify_order_id: String(result.shopify_order_id), vendor_names: result.vendor_names || [] });
        }
        messages.push({ role:'tool', tool_call_id: tc.id, content: JSON.stringify(result) });
      }
      continue;
    }
    finalReply = msg?.content || "I'm here to help — could you tell me a bit more?";
    break;
  }
  if (newTags.size) {
    await mdb.collection('support_chats').updateOne({ _id: chat._id }, { $addToSet: { tags: { $each: [...newTags] } } });
  }
  return { reply: finalReply, meta: cardMeta };
}

// Finds a prior chat already tied to this order (a different browser/device
// session asked about the same order before) so the widget can offer to
// resume that single thread instead of fragmenting the conversation across
// multiple chats — keeps the vendor's view of an order to one coherent
// thread instead of several scattered ones.
async function scFindExistingChatForOrder(shopifyOrderId, excludeChatId) {
  if (!shopifyOrderId) return null;
  const prior = await mdb.collection('support_chats').findOne(
    { shopify_order_id: String(shopifyOrderId), _id: { $ne: new SC_ObjectId(String(excludeChatId)) } },
    { sort: { updated_at: -1 } }
  );
  if (!prior) return null;
  const msgCount = await mdb.collection('support_messages').countDocuments({ chat_id: String(prior._id) });
  if (msgCount < 2) return null; // nothing beyond the welcome message — not worth resuming
  const lastMsg = await mdb.collection('support_messages').find({ chat_id: String(prior._id) }, { projection: { _id: 0 } }).sort({ created_at: -1 }).limit(1).next();
  return { chat_id: String(prior._id), message_count: msgCount, updated_at: prior.updated_at, last_message: lastMsg?.text?.slice(0, 80) || '' };
}

// Detect what the customer is asking about based on chat tags / context
function scDetectVendorQueryContext(chat) {
  const tags = (chat.tags || []).map(t => t.toLowerCase());
  if (tags.some(t => t.includes('exchange') || t.includes('return')))
    return { type: 'return_exchange', label: 'Return / Exchange issue', emoji: '🔄' };
  if (tags.some(t => t.includes('delay') || t.includes('dispatch')))
    return { type: 'delay', label: 'Order not dispatched — delay inquiry', emoji: '⏳' };
  if (tags.some(t => t.includes('refund')))
    return { type: 'refund', label: 'Refund inquiry', emoji: '💰' };
  return { type: 'status', label: 'Order status / dispatch update needed', emoji: '📦' };
}

async function scNotifyVendorsIfNeeded(chatId) {
  const chat = await SC.get(chatId);
  if (!chat || !chat.vendor_names?.length || chat.vendor_notified_at) return;
  if (!waSocket || !waConnected) return;

  const ctx = scDetectVendorQueryContext(chat);
  const orderName = chat.order_name || '';

  for (const vendorName of chat.vendor_names) {
    try {
      const vp = await mdb.collection('vendor_profiles').findOne({ vendor_name: vendorName }, { projection: { phone: 1, _id: 0 } });
      const rawPhone = (vp?.phone || '').replace(/\D/g, '').replace(/^91/, '').slice(-10);
      if (rawPhone.length !== 10) continue;

      const jidDoc = await mdb.collection('wa_vendor_jids').findOne({ phone: rawPhone }).catch(() => null);
      const jid = jidDoc?.jid || `91${rawPhone}@s.whatsapp.net`;

      // Create update token so vendor can submit via web form (fallback)
      const updateToken = await createVendorUpdateToken(
        chat.shopify_order_id || orderName, orderName, vendorName, '', ctx.type
      ).catch(() => null);
      const formLink = updateToken ? `${SERVER_URL}/vendor/update/${updateToken}` : null;

      const waMsg =
`💬 *Customer Query — Order ${orderName}*

Hi ${vendorName},

A customer is asking about: ${ctx.emoji} *${ctx.label}*

Please reply so we can update them:

1️⃣ Report delay (share reason + dispatch date)
2️⃣ Already shipped (share AWB / tracking)
3️⃣ Other / I've already handled this — inform CROSCROW team${formLink ? `\n\n🔗 Submit update via form: ${formLink}` : ''}

Reply with *1*, *2* or *3* 👇`;

      const sent = await waSocket.sendMessage(jid, { text: waMsg });
      const actualJid = sent?.key?.remoteJid || jid;

      // Store session so numbered reply gets routed correctly
      await waSessionSet(actualJid, {
        type: 'support_vendor_reply',
        chat_id: String(chat._id),
        order_name: orderName,
        shopify_id: String(chat.shopify_order_id || ''),
        vendor: vendorName,
        query_context: ctx,
        form_link: formLink,
      });
      await mdb.collection('wa_vendor_jids').updateOne(
        { phone: rawPhone },
        { $set: { phone: rawPhone, jid: actualJid, updated_at: new Date().toISOString() } },
        { upsert: true }
      ).catch(() => {});
      console.log(`📲 WA vendor support notify sent: ${orderName} / ${vendorName} (${ctx.type})`);
    } catch (e) { console.error('Support chat vendor notify WA failed:', vendorName, e.message); }
  }
  await SC.update(chatId, { vendor_notified_at: new Date().toISOString() });
}

