// Test endpoint — send a WhatsApp message to any number directly
// GET /admin/whatsapp-test?to=9876543210&msg=hello&image=https://...
app.get('/admin/whatsapp-test', adminAuth, async (req, res) => {
  try {
    if (!waSocket) return res.status(503).json({ error: 'WhatsApp bot not running (WHATSAPP_BOT_ENABLED=true required)' });
    const to = (req.query.to || '').replace(/\D/g, '');
    const msg = req.query.msg || 'Test message from CROSCROW bot ✅';
    const imageUrl = req.query.image || '';
    if (!to) return res.status(400).json({ error: 'to= phone number required' });
    const jid = `91${to.replace(/^91/, '')}@s.whatsapp.net`;
    if (imageUrl) {
      const https = require('https');
      const http = require('http');
      // Resolve imgbb share pages to direct image URL
      async function fetchUrl(url) {
        const fetcher = url.startsWith('https') ? https : http;
        return new Promise((resolve, reject) => {
          fetcher.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' } }, res2 => {
            if (res2.statusCode >= 300 && res2.statusCode < 400 && res2.headers.location) {
              return resolve(fetchUrl(res2.headers.location));
            }
            const ct = res2.headers['content-type'] || '';
            if (ct.includes('text/html')) {
              // Extract direct image from imgbb HTML
              let html = '';
              res2.on('data', c => html += c);
              res2.on('end', () => {
                const m = html.match(/https:\/\/i\.ibb\.co\/[^"'\s]+\.(jpg|jpeg|png|gif|webp)/i);
                if (m) return resolve(fetchUrl(m[0]));
                reject(new Error('Could not find direct image URL on page'));
              });
            } else {
              const chunks = [];
              res2.on('data', c => chunks.push(c));
              res2.on('end', () => resolve(Buffer.concat(chunks)));
            }
            res2.on('error', reject);
          }).on('error', reject);
        });
      }
      const imageBuffer = await fetchUrl(imageUrl);
      await waSocket.sendMessage(jid, { image: imageBuffer, caption: msg });
    } else {
      await waSocket.sendMessage(jid, { text: msg });
    }
    res.json({ success: true, sent_to: jid, message: msg, image: imageUrl || null });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// GET /admin/whatsapp-test-list?to=  — sends a "Select Option" list message
app.get('/admin/whatsapp-test-list', adminAuth, async (req, res) => {
  try {
    if (!waSocket) return res.status(503).json({ error: 'WhatsApp bot not running' });
    if (!waConnected) return res.status(503).json({ error: 'WhatsApp not connected yet' });
    const to = (req.query.to || '').replace(/\D/g, '');
    if (!to) return res.status(400).json({ error: 'to required' });
    const jid = `91${to.replace(/^91/, '')}@s.whatsapp.net`;
    const { proto, generateWAMessageFromContent } = require('@whiskeysockets/baileys');

    const content = proto.Message.fromObject({
      listMessage: {
        title: 'How can we help? 👋',
        description: 'Tap below to choose an option',
        buttonText: 'Select Option',
        listType: 'SINGLE_SELECT',
        footerText: 'CROSCROW',
        sections: [{
          title: 'Order Actions',
          rows: [
            { title: '✅ Confirm Order', description: 'I am ready to receive', rowId: 'confirm' },
            { title: '❌ Cancel Order', description: 'I want to cancel', rowId: 'cancel' },
            { title: '📦 Track Order', description: 'Where is my order?', rowId: 'track' },
            { title: '🔄 Return / Exchange', description: 'I want to return or exchange', rowId: 'return' },
            { title: '💬 Talk to Agent', description: 'Connect me with support', rowId: 'agent' },
          ]
        }]
      }
    });

    const waMsg = generateWAMessageFromContent(jid, content, { userJid: waSocket.user?.id });
    await waSocket.relayMessage(jid, waMsg.message, { messageId: waMsg.key.id });
    res.json({ success: true, sent_to: jid });
  } catch (e) { res.status(500).json({ error: e.message, stack: e.stack?.split('\n').slice(0,3) }); }
});

