// GET /admin/whatsapp-confirm-poll?to=8209544626&order=2304
// Sends a Yes/No poll to customer asking them to confirm their order
app.get('/admin/whatsapp-confirm-poll', adminAuth, async (req, res) => {
  try {
    if (!waSocket) return res.status(503).json({ error: 'WhatsApp bot not running' });
    const to = (req.query.to || '').replace(/\D/g, '');
    const orderNum = (req.query.order || '').replace(/^#/, '').trim();
    if (!to || !orderNum) return res.status(400).json({ error: 'to and order required' });
    const jid = `91${to.replace(/^91/, '')}@s.whatsapp.net`;
    const messageSecret = require('crypto').randomBytes(32);
    const sent = await waSocket.sendMessage(jid, {
      poll: {
        name: `Confirm your order #${orderNum}?`,
        values: ['✅ Yes, confirm', '❌ No, cancel'],
        selectableCount: 1,
        messageSecret,
      }
    });
    // Store poll metadata so we can act on the vote
    await mdb.collection('wa_confirm_polls').insertOne({
      msg_id: sent.key.id,
      jid,
      order_name: `#${orderNum}`,
      message_secret: messageSecret.toString('hex'),
      bot_jid: waSocket.user?.id,
      created_at: new Date(),
      expires_at: new Date(Date.now() + 24 * 60 * 60 * 1000),
    });
    res.json({ success: true, sent_to: jid, order: `#${orderNum}` });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// POST /admin/vendor-nudge-test/:orderId — send test penalty nudge to vendor
app.post('/admin/vendor-nudge-test/:orderId', adminAuth, async (req, res) => {
  try {
    // Wait up to 15s for WA to connect (handles post-deploy reconnect delay)
    if (!waSocket || !waConnected) {
      await new Promise(resolve => {
        const deadline = Date.now() + 15000;
        const check = setInterval(() => { if ((waSocket && waConnected) || Date.now() > deadline) { clearInterval(check); resolve(); } }, 500);
      });
    }
    if (!waSocket || !waConnected) return res.status(503).json({ error: 'WhatsApp bot not connected', connected: waConnected, socket: !!waSocket });
    const orderName = `#${req.params.orderId.replace(/^#/, '')}`;
    const shopifyId = req.params.orderId.replace(/^#/, '');

    // Try to find order by shopify_id (long ID) or by wa_vendor_nudges/order_vendor_stage
    // For test purposes, allow passing vendor_name + phone directly in body
    let vendorName = req.body?.vendor_name;
    let customerName = req.body?.customer_name || '';
    let customerPhone = (req.body?.customer_phone || '').replace(/\D/g, '').replace(/^91/, '').slice(-10);
    let productNames = req.body?.products || 'your item';

    // Auto-lookup vendor from order_vendor_stage if not provided
    if (!vendorName) {
      // Try order_vendor_stage with the raw orderId as shopify_id
      const vendorStage = await mdb.collection('order_vendor_stage').findOne({ shopify_id: String(shopifyId) });
      vendorName = vendorStage?.vendor_name;
    }
    if (!vendorName) return res.status(400).json({ error: 'No vendor found for this order. Pass vendor_name in body, or ensure order_vendor_stage has a record with this shopify_id.' });

    // Get vendor phone
    const vendorProfile = await mdb.collection('vendor_profiles').findOne({ vendor_name: vendorName });
    const rawPhone = (vendorProfile?.phone || '').replace(/\D/g, '').replace(/^91/, '').slice(-10);
    if (rawPhone.length !== 10) return res.status(400).json({ error: `No valid phone for vendor "${vendorName}"` });

    const jid = `91${rawPhone}@s.whatsapp.net`;
    const days = req.body?.days || 3;
    const orderRef = shopifyId;

    const testToken = mdb ? await createVendorUpdateToken(shopifyId, orderName, vendorName, productNames).catch(() => null) : null;
    const testLink = testToken ? `\n\n🔗 *Quick update (no login):*\n${SERVER_BASE}/vendor/update/${testToken}` : '';
    const _Fndg = '```';
    const nudgeMsg = `${_Fndg}\n▪ C R O S C R O W ▪\nACTION REQUIRED\n────────────────\nORDER  ${orderName}\nITEM   ${productNames}\nSTUCK  ${days} day${days > 1 ? 's' : ''} unshipped\n────────────────\nSUBMIT UPDATE HERE\n${testToken ? `dashboard.croscrow.com/vendor/update/${testToken}` : 'Log in to vendor portal'}\n${_Fndg}`;

    const sent = await waSocket.sendMessage(jid, { text: nudgeMsg });
    const actualJid = sent?.key?.remoteJid || jid;

    // Store session so vendor's 1/2 reply maps to this order
    await waVendorSessionSet(actualJid, jid, { type: 'vendor_menu', order_name: orderName, shopify_id: String(shopifyId), orderRef, vendor: vendorName });

    // Cache JID
    await mdb.collection('wa_vendor_jids').updateOne(
      { phone: rawPhone },
      { $set: { phone: rawPhone, jid: actualJid, updated_at: new Date().toISOString() } },
      { upsert: true }
    ).catch(() => {});

    res.json({ success: true, sent_to: jid, order: orderName, vendor: vendorName });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ══════════════════════════════════════════════════════════════════════════
// WHATSAPP SUPPORT BOT (Baileys — no browser, session stored in MongoDB)
// ══════════════════════════════════════════════════════════════════════════
// Set WHATSAPP_BOT_ENABLED=true in .env to activate.
// On first start a QR code prints in the terminal — scan it once with your
// business WhatsApp → Settings → Linked Devices → Link a device.
// Session is stored in MongoDB (whatsapp_auth collection) so it survives
// Render restarts and deploys without needing to re-scan.
// ─────────────────────────────────────────────────────────────────────────

let waSocket = null;
let waConnected = false;
let waLatestQR = null;
let waStarting = false;
let waSharedMessageHandler = null; // set by v1 bot; reused by v2
let waReconnectTimer = null;
const waPending = new Set();

// MongoDB-backed auth state for Baileys — survives server restarts/redeploys
async function useMongoAuthState() {
  const { initAuthCreds, BufferJSON, proto } = require('@whiskeysockets/baileys');
  const col = mdb.collection('whatsapp_auth');

  // Load ALL auth keys into memory at startup — one bulk read instead of
  // per-key round-trips during every handshake. Writes go to memory first
  // and flush to MongoDB in the background. This matches the speed of
  // file-based auth while keeping MongoDB as the durable backing store.
  const cache = new Map();
  const allDocs = await col.find({}).toArray().catch(() => []);
  for (const doc of allDocs) {
    try { cache.set(doc._id, JSON.parse(doc.v, BufferJSON.reviver)); } catch {}
  }

  const write = (id, data) => {
    cache.set(id, data);
    // Fire-and-forget persist — doesn't block the handshake
    col.updateOne({ _id: id }, { $set: { v: JSON.stringify(data, BufferJSON.replacer) } }, { upsert: true }).catch(() => {});
  };

  const del = (id) => {
    cache.delete(id);
    col.deleteOne({ _id: id }).catch(() => {});
  };

  const creds = cache.get('creds') || initAuthCreds();

  return {
    state: {
      creds,
      keys: {
        get: (type, ids) => {
          const data = {};
          for (const id of ids) {
            let val = cache.get(`${type}-${id}`) ?? null;
            if (type === 'app-state-sync-key' && val) val = proto.Message.AppStateSyncKeyData.fromObject(val);
            data[id] = val;
          }
          return data;
        },
        set: (data) => {
          for (const [type, ids] of Object.entries(data)) {
            for (const [id, val] of Object.entries(ids || {})) {
              if (val) write(`${type}-${id}`, val);
              else del(`${type}-${id}`);
            }
          }
        },
      },
    },
    saveCreds: () => write('creds', creds),
  };
}

// Nudges vendor on WhatsApp when customer asks about an order stuck unshipped for 2+ days.
// Deduped per order+vendor per 24h via wa_vendor_nudges collection.
// ── Handle replies from the vendor WhatsApp number ────────────────────────
// Supports two formats (case-insensitive):
//   TRACK <order> <AWB> <courier>       → saves tracking to order_vendor_stage
//   DELAY <order> <reason> | ETA <date> → saves delay_reason + resolution date
async function waHandleVendorReply(sock, sender, text) {
  if (!mdb) return;

  const trimmed = text.trim();

  // Helper to send + log bot reply
  const sendAndLog = async (msg, vendorNameHint) => {
    await sock.sendMessage(sender, { text: msg });
    await waLogVendorMessage(sender, vendorNameHint || sender, 'bot', msg).catch(() => {});
  };

  // Check session for pending menu interaction
  const session = await waSessionGet(sender);

  // ── Support chat vendor reply (3-option menu from scNotifyVendorsIfNeeded) ──
  if (session?.type === 'support_vendor_reply') {
    const { order_name, shopify_id, vendor, query_context, form_link, chat_id } = session;
    const orderRef = String(shopify_id).replace(/^#/, '');

    if (trimmed === '1') {
      await waSessionSet(sender, { type: 'vendor_delay', order_name, shopify_id, orderRef, vendor });
      await sendAndLog(
        `📝 *Order ${order_name} — Delay Reason*\n\nPlease share the reason and when you'll dispatch. Just type naturally, e.g.:\n\n_Stitching pending, will ship by 20 July_\n_Stock shortage, dispatching by 18 Jul_\n\nType your message 👇`,
        vendor
      );
      return;
    }

    if (trimmed === '2') {
      await waSessionSet(sender, { type: 'vendor_tracking', order_name, shopify_id, orderRef, vendor });
      await sendAndLog(
        `📦 *Order ${order_name} — Tracking Update*\n\nShare AWB + courier naturally, e.g.:\n\n_123456789 Delhivery_\n_Shipped via Shiprocket, AWB 9876543210_\n\nType your message 👇`,
        vendor
      );
      return;
    }

    if (trimmed === '3') {
      // Vendor says they've already handled it or it's an unrelated issue
      await waAdminAlert(
        `\`\`\`\n▪ C R O S C R O W ▪\nVENDOR SELF-RESOLVED\n────────────────\nORDER  ${order_name}\nVENDOR ${vendor}\nQUERY  ${query_context?.label || 'general'}\n────────────────\nVendor says handled /\nneeds CROSCROW help\n\`\`\``
      );
      if (chat_id) {
        await mdb.collection('support_chats').updateOne(
          { _id: new (require('mongodb').ObjectId)(chat_id) },
          { $set: { vendor_self_resolved: true, updated_at: new Date().toISOString() } }
        ).catch(() => {});
      }
      await sendAndLog(
        `✅ Got it, ${vendor}! Noted as handled — our team has been informed and will follow up with the customer directly. Thank you! 🙏`,
        vendor
      );
      await waSessionClear(sender);
      return;
    }

    // Unrecognised reply — re-prompt
    await sendAndLog(
      `Please reply with *1*, *2* or *3*:\n\n1️⃣ Report delay reason\n2️⃣ Already shipped (share AWB)\n3️⃣ Other / already handled${form_link ? `\n\n🔗 Or use form: ${form_link}` : ''}`,
      vendor
    );
    return;
  }

  if (session?.type === 'vendor_menu') {
    const { order_name, shopify_id, orderRef, vendor } = session;

    if (trimmed === '1') {
      await waSessionSet(sender, { type: 'vendor_delay', order_name, shopify_id, orderRef, vendor });
      await sendAndLog(`📝 *Order ${order_name} — Delay Update*\n\nPlease share the reason and when you'll ship it. Just reply naturally, for example:\n\n_Slightly delayed due to stitching, will ship by 16 July_\n_Stock issue, dispatching by 18 Jul_\n_Courier pickup delayed, shipping tomorrow_\n\nJust type your message 👇`, vendor);
      return;
    }

    if (trimmed === '2') {
      await waSessionSet(sender, { type: 'vendor_tracking', order_name, shopify_id, orderRef, vendor });
      await sendAndLog(`📦 *Order ${order_name} — Tracking Update*\n\nPlease share the AWB number and courier. Just reply naturally, for example:\n\n_123456789 Delhivery_\n_Shipped via Shiprocket, AWB 9876543210_\n_Bluedart 445566778_\n\nJust type your message 👇`, vendor);
      return;
    }
  }

  if (session?.type === 'vendor_delay') {
    const { order_name, shopify_id, vendor } = session;
    // Parse via LLM to extract reason + ETA
    let reason = trimmed, etaDisplay = 'Not specified', etaIso = null;
    try {
      const DEEPSEEK_KEY = process.env.DEEPSEEK_API_KEY;
      const GROQ_KEY = process.env.GROQ_API_KEY;
      const today = new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
      const prompt = [
        { role: 'system', content: `Extract delay reason and ETA from vendor message. Today is ${today}. Reply ONLY with JSON: {"reason":"one sentence","eta_display":"DD-MMM-YYYY or null","eta_iso":"YYYY-MM-DD or null"}` },
        { role: 'user', content: trimmed }
      ];
      const apiUrl = DEEPSEEK_KEY ? 'https://api.deepseek.com/chat/completions' : 'https://api.groq.com/openai/v1/chat/completions';
      const r = await fetch(apiUrl, { method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${DEEPSEEK_KEY || GROQ_KEY}` }, body: JSON.stringify({ model: DEEPSEEK_KEY ? 'deepseek-chat' : 'llama-3.3-70b-versatile', max_tokens: 150, messages: prompt }) });
      const d = await r.json();
      const parsed = JSON.parse((d.choices?.[0]?.message?.content?.trim() || '{}').replace(/^```json\s*/i,'').replace(/```$/,''));
      if (parsed.reason) reason = parsed.reason;
      if (parsed.eta_display && parsed.eta_display !== 'null') etaDisplay = parsed.eta_display;
      if (parsed.eta_iso && parsed.eta_iso !== 'null') etaIso = parsed.eta_iso;
    } catch (_) {}
    // Save to delay_remarks (shown in admin order page, used by penalty cron for ETA breach)
    await DR.insert(shopify_id, vendor, reason, etaIso);
    // Also update order_vendor_stage for quick display
    await OVS.upsert(shopify_id, vendor, { delay_reason: reason, delay_resolution_date: etaDisplay, updated_at: new Date().toISOString() });
    await mdb.collection('wa_vendor_nudges').updateOne({ shopify_id: String(shopify_id), resolved: { $ne: true } }, { $set: { resolved: true } });
    await waSessionClear(sender);
    await sendAndLog(`✅ Delay recorded for *${order_name}*\n\nReason: ${reason}\nExpected by: *${etaDisplay}*\n\nWe'll update the customer. Thank you! 🙏`, vendor);
    notifyDelayToCustomer(shopify_id, vendor, reason, etaIso).catch(() => {});
    await waAdminAlert(`\`\`\`\n▪ C R O S C R O W ▪\nVENDOR DELAY\n────────────────\nORDER  ${order_name}\nVENDOR ${vendor}\nREASON ${reason}\nETA    ${etaDisplay}\n────────────────\nSOURCE Vendor WA\n\`\`\``, 'dispatch_alert');
    return;
  }

  if (session?.type === 'vendor_tracking') {
    const { order_name, shopify_id, vendor: vendorT } = session;
    // Parse AWB + courier from free text via LLM
    let awb = null, courier = 'Not specified';
    try {
      const DEEPSEEK_KEY = process.env.DEEPSEEK_API_KEY;
      const GROQ_KEY = process.env.GROQ_API_KEY;
      const prompt = [
        { role: 'system', content: 'Extract AWB tracking number and courier name. Reply ONLY with JSON: {"awb":"...","courier":"..."}' },
        { role: 'user', content: trimmed }
      ];
      const apiUrl = DEEPSEEK_KEY ? 'https://api.deepseek.com/chat/completions' : 'https://api.groq.com/openai/v1/chat/completions';
      const r = await fetch(apiUrl, { method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${DEEPSEEK_KEY || GROQ_KEY}` }, body: JSON.stringify({ model: DEEPSEEK_KEY ? 'deepseek-chat' : 'llama-3.3-70b-versatile', max_tokens: 100, messages: prompt }) });
      const d = await r.json();
      const parsed = JSON.parse(d.choices?.[0]?.message?.content?.trim() || '{}');
      if (parsed.awb) awb = parsed.awb;
      if (parsed.courier) courier = parsed.courier;
    } catch (_) {}
    if (!awb) {
      await sendAndLog(`⚠️ Couldn't read the AWB. Please send it in this format:\n_123456789 Delhivery_`, vendorT);
      return;
    }
    await mdb.collection('order_vendor_stage').updateOne(
      { shopify_id: String(shopify_id) },
      { $set: { awb, courier, stage: 'transit', updated_at: new Date().toISOString() } }
    );
    await mdb.collection('wa_vendor_nudges').updateOne({ shopify_id: String(shopify_id), resolved: { $ne: true } }, { $set: { resolved: true } });
    await waSessionClear(sender);
    await sendAndLog(`✅ Tracking updated for *${order_name}*!\n\nAWB: *${awb}*\nCourier: *${courier}*\n\nThank you! 🙏`, vendorT);
    await waAdminAlert(`\`\`\`\n▪ C R O S C R O W ▪\nVENDOR TRACKING\n────────────────\nORDER  ${order_name}\nAWB    ${awb}\nVIA    ${courier}\n────────────────\nSOURCE Vendor WA\n\`\`\``);
    return;
  }

  // ── vendor_confirm: short confirmation step for natural language WA updates ──
  if (session?.type === 'vendor_confirm') {
    const { action, shopify_id, order_name, vendor_name, data } = session;
    if (trimmed === '1') {
      await waSessionClear(sender);
      if (action === 'delay') {
        await DR.insert(shopify_id, vendor_name, data.reason, data.eta_iso);
        await OVS.upsert(shopify_id, vendor_name, { delay_reason: data.reason, delay_resolution_date: data.eta_display, updated_at: new Date().toISOString() });
        await mdb.collection('wa_vendor_nudges').updateOne({ shopify_id: String(shopify_id), vendor: vendor_name, resolved: { $ne: true } }, { $set: { resolved: true } }).catch(() => {});
        await notifyDelayToCustomer(shopify_id, vendor_name, data.reason, data.eta_iso);
        await waAdminAlert(`\`\`\`\n▪ C R O S C R O W ▪\nVENDOR DELAY\n────────────────\nORDER  ${order_name}\nVENDOR ${vendor_name}\nREASON ${data.reason}\nETA    ${data.eta_display || 'not specified'}\n────────────────\nSOURCE Vendor WA (NL)\n\`\`\``);
        await sendAndLog(`✅ *Delay recorded for ${order_name}*\n\nReason: ${data.reason}\nShipping by: *${data.eta_display || 'not specified'}*\n\nCustomer has been notified. Thank you! 🙏`, vendor_name);
      } else if (action === 'tracking') {
        await mdb.collection('order_vendor_stage').updateOne(
          { shopify_id: String(shopify_id) },
          { $set: { awb: data.awb, courier: data.courier, stage: 'transit', updated_at: new Date().toISOString() } }
        );
        await mdb.collection('wa_vendor_nudges').updateOne({ shopify_id: String(shopify_id), vendor: vendor_name, resolved: { $ne: true } }, { $set: { resolved: true } }).catch(() => {});
        await waAdminAlert(`\`\`\`\n▪ C R O S C R O W ▪\nVENDOR TRACKING\n────────────────\nORDER  ${order_name}\nVENDOR ${vendor_name}\nAWB    ${data.awb}\nVIA    ${data.courier}\n────────────────\nSOURCE Vendor WA (NL)\n\`\`\``);
        await sendAndLog(`✅ *Tracking updated for ${order_name}*\n\nAWB: *${data.awb}*\nCourier: *${data.courier}*\n\nThank you! 🙏`, vendor_name);
      }
      return;
    }
    // "2" or anything else = cancel
    await waSessionClear(sender);
    await sendAndLog(`↩ Cancelled. No changes saved.\n\nTo report a delay or shipping update, just describe it naturally:\n_"Order 2344 delayed, fabric issue, ships by 25 Jul"_\n_"Order 2344 AWB 123456789 Delhivery"_`, vendor_name);
    return;
  }

  if (session?.type === 'vendor_order_select') {
    const { vendor, orders } = session;
    const num = parseInt(trimmed, 10);
    if (!isNaN(num) && num >= 1 && num <= orders.length) {
      const selected = orders[num - 1];
      await waSessionSet(sender, { type: 'vendor_menu', order_name: selected.order_name, shopify_id: selected.shopify_id, vendor });
      await sendAndLog(
        `*Order ${selected.order_name}* selected ✅\n\nWhat do you want to update?\n\n1️⃣ — Report delay (reason + expected date)\n2️⃣ — Already shipped (AWB + courier name)`,
        vendor
      );
      return;
    }
    await sendAndLog(`Please reply with a number between *1* and *${orders.length}*.\n\nFor example, reply *1* to select the first order in the list.`, vendor);
    return;
  }

  // Resolve vendor name from wa_vendor_jids for use in messages below
  const vendorJidDoc = await mdb.collection('wa_vendor_jids').findOne(
    { $or: [{ jid: sender }, ...(phone ? [{ phone: { $regex: phone } }] : [])] }
  ).catch(() => null);
  const resolvedVendorName = vendorJidDoc?.vendor_name || null;

  // Find most recent unresolved nudge for THIS specific vendor (last 7 days)
  const recentNudge = resolvedVendorName
    ? await mdb.collection('wa_vendor_nudges').findOne(
        { vendor: resolvedVendorName, sent_at: { $gt: Date.now() - 7 * 86400000 }, resolved: { $ne: true } },
        { sort: { sent_at: -1 } }
      ).catch(() => null)
    : null;

  // If vendor sends "1" or "2" with a recent nudge in context → go straight to that order
  const isBareMenuReply = /^[12]$/.test(trimmed);
  if (isBareMenuReply && recentNudge && resolvedVendorName) {
    const orderName = recentNudge.order_name || `#${recentNudge.shopify_id}`;
    const shopifyId = String(recentNudge.shopify_id);
    if (trimmed === '1') {
      await waSessionSet(sender, { type: 'vendor_delay', order_name: orderName, shopify_id: shopifyId, vendor: resolvedVendorName });
      await sendAndLog(
        `📝 *Order ${orderName} — Delay Update*\n\nPlease share the reason and when you'll ship it. Just reply naturally, for example:\n\n_Slightly delayed due to stitching, will ship by 16 July_\n_Stock issue, dispatching by 18 Jul_\n_Courier pickup delayed, shipping tomorrow_\n\nJust type your message 👇`,
        resolvedVendorName
      );
    } else {
      await waSessionSet(sender, { type: 'vendor_tracking', order_name: orderName, shopify_id: shopifyId, vendor: resolvedVendorName });
      await sendAndLog(
        `📦 *Order ${orderName} — Tracking Update*\n\nPlease share the AWB number and courier. Just reply naturally, for example:\n\n_123456789 Delhivery_\n_Shipped via Shiprocket, AWB 9876543210_\n_Bluedart 445566778_\n\nJust type your message 👇`,
        resolvedVendorName
      );
    }
    return;
  }

  // If vendor sends "1"/"2" or delay keywords with NO nudge context → show order picker
  const isPenaltyOrMenuReply = isBareMenuReply ||
    /\b(delay|delayed|dispute|penalty|wrong|extend|can'?t ship|not yet|few days|stock issue|stitching|fabric|courier|pickup|tomorrow|this week)\b/i.test(trimmed);

  if (isPenaltyOrMenuReply && resolvedVendorName) {
    const pendingOrders = await mdb.collection('order_vendor_stage').find({
      vendor_name: resolvedVendorName,
      stage: { $in: ['confirmed', 'partial', 'hold', 'new', 'pending'] }
    }).sort({ updated_at: -1 }).limit(10).toArray();

    if (!pendingOrders.length) {
      await sendAndLog(
        `Hi ${resolvedVendorName}! 👋\n\nNo pending fulfillments found for your account right now.\n\nIf you need help with a specific order, share the order number (e.g. *#2531*) and we'll sort it out!`,
        resolvedVendorName
      );
      return;
    }

    const lines = pendingOrders.map((o, i) =>
      `*${i + 1}.* ${o.order_name || '#' + o.shopify_id} — ${(o.stage || 'pending').toUpperCase()}`
    );
    await waSessionSet(sender, {
      type: 'vendor_order_select',
      vendor: resolvedVendorName,
      orders: pendingOrders.map(o => ({
        shopify_id: String(o.shopify_id),
        order_name: o.order_name || `#${o.shopify_id}`,
        stage: o.stage
      }))
    });
    await sendAndLog(
      `Hi ${resolvedVendorName}! 👋\n\nWhich order are you updating?\n\n${lines.join('\n')}\n\nReply with the number (e.g. *1*, *3*)`,
      resolvedVendorName
    );
    return;
  }

  // ── Stateless natural language detection ─────────────────────────────────
  // Detect messages like "order 2344 delayed fabric issue ships 25 july"
  // Accepts from any sender — order number in the message is the identifier
  const orderNumMatch = trimmed.match(/(?:order[#\s]*|#)(\d{3,6})/i);
  const hasDelayKeywords = /delay|not.*ship|can'?t.*ship|issue|stitching|fabric|stock|pending|by \d|shipping.*\d|dispatch.*\d|tomorrow|next week|this week/i.test(trimmed);
  const hasTrackingKeywords = /\bawb\b|\btrack(ing)?\b|delhivery|bluedart|ecomexpress|shiprocket|ekart|dtdc|xpressbees|\b[A-Z0-9]{8,}\s+(delhivery|bluedart|shiprocket|ecomexpress)\b/i.test(trimmed);

  if (orderNumMatch && (hasDelayKeywords || hasTrackingKeywords)) {
    const orderNum = orderNumMatch[1];
    // Look up order in order_vendor_stage
    const ovs = await mdb.collection('order_vendor_stage').findOne({
      $or: [{ shopify_id: { $regex: orderNum } }, { order_name: { $regex: orderNum } }]
    }).catch(() => null);
    if (ovs) {
      const vName = ovs.vendor_name;
      const shopifyId = String(ovs.shopify_id);
      const oName = ovs.order_name || `#${orderNum}`;
      const today = new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
      try {
        const DEEPSEEK_KEY = process.env.DEEPSEEK_API_KEY;
        const GROQ_KEY = process.env.GROQ_API_KEY;
        const llmPrompt = [
          { role: 'system', content: `Extract delay/tracking info. Today is ${today}. Order is ${oName}. Reply ONLY with JSON:\n{"type":"delay"|"tracking","reason":"one sentence or null","eta_display":"DD-MMM-YYYY or null","eta_iso":"YYYY-MM-DD or null","awb":"AWB number or null","courier":"courier name or null"}` },
          { role: 'user', content: trimmed }
        ];
        const apiUrl = DEEPSEEK_KEY ? 'https://api.deepseek.com/chat/completions' : 'https://api.groq.com/openai/v1/chat/completions';
        const r = await fetch(apiUrl, { method:'POST', headers:{'Content-Type':'application/json','Authorization':`Bearer ${DEEPSEEK_KEY||GROQ_KEY}`}, body: JSON.stringify({ model: DEEPSEEK_KEY?'deepseek-chat':'llama-3.3-70b-versatile', max_tokens:150, messages: llmPrompt }) });
        const lr = await r.json();
        const nlParsed = JSON.parse((lr.choices?.[0]?.message?.content?.trim()||'{}').replace(/^```json\s*/i,'').replace(/```$/,'').trim());
        if (nlParsed.type === 'delay' && nlParsed.reason) {
          const _Fcd = '```';
          const confirmMsg = `${_Fcd}\n▪ C R O S C R O W ▪\nDELAY LOGGED ✓\n────────────────\nORDER  ${oName}\nREASON ${nlParsed.reason}\nETA    ${nlParsed.eta_display || 'not mentioned'}\n────────────────\nReply 1 to confirm ✓\nReply 2 to cancel ✗\n${_Fcd}`;
          await waSessionSet(sender, { type: 'vendor_confirm', action: 'delay', shopify_id: shopifyId, order_name: oName, vendor_name: vName, data: { reason: nlParsed.reason, eta_display: nlParsed.eta_display, eta_iso: nlParsed.eta_iso } });
          await sendAndLog(confirmMsg, vName);
          return;
        }
        if (nlParsed.type === 'tracking' && nlParsed.awb) {
          const _Fct = '```';
          const confirmMsg = `${_Fct}\n▪ C R O S C R O W ▪\nTRACKING LOGGED ✓\n────────────────\nORDER   ${oName}\nAWB     ${nlParsed.awb}\nCOURIER ${nlParsed.courier || 'not mentioned'}\n────────────────\nReply 1 to confirm ✓\nReply 2 to cancel ✗\n${_Fct}`;
          await waSessionSet(sender, { type: 'vendor_confirm', action: 'tracking', shopify_id: shopifyId, order_name: oName, vendor_name: vName, data: { awb: nlParsed.awb, courier: nlParsed.courier || 'Not specified' } });
          await sendAndLog(confirmMsg, vName);
          return;
        }
      } catch (_) {}
    }
  }

  // Use LLM to parse natural language from vendor into structured data
  const orderContext = recentNudge ? `The vendor is likely replying about order ${recentNudge.order_name}.` : 'No recent order context found.';
  const today = new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });

  let parsed = null;
  try {
    const DEEPSEEK_KEY = process.env.DEEPSEEK_API_KEY;
    const GROQ_KEY = process.env.GROQ_API_KEY;
    const prompt = [
      { role: 'system', content: `You are a parser for vendor WhatsApp replies to CROSCROW support nudges. Today is ${today}. ${orderContext}\n\nExtract structured info from the vendor message and reply ONLY with valid JSON, no other text.\n\nJSON schema:\n{\n  "type": "tracking" | "delay" | "unknown",\n  "awb": "<AWB/tracking number if found, else null>",\n  "courier": "<courier name if found, else null>",\n  "reason": "<delay reason in one sentence if type is delay, else null>",\n  "eta": "<expected ship/delivery date as DD-MMM-YYYY if mentioned, else null>",\n  "order_num": "<order number digits only if explicitly mentioned, else null>"\n}\n\nExamples:\n- "it will be shipped on 12th july" → {"type":"delay","awb":null,"courier":null,"reason":"Order will be shipped by 12th July","eta":"12-Jul-2026","order_num":null}\n- "4959596 bluedart" → {"type":"tracking","awb":"4959596","courier":"BlueDart","reason":null,"eta":null,"order_num":null}\n- "TRACK 2531 123456 delhivery" → {"type":"tracking","awb":"123456","courier":"Delhivery","reason":null,"eta":null,"order_num":"2531"}\n- "fabric shortage, ship by 15 july" → {"type":"delay","awb":null,"courier":null,"reason":"Fabric shortage causing delay","eta":"15-Jul-2026","order_num":null}` },
      { role: 'user', content: text }
    ];
    const apiUrl = DEEPSEEK_KEY ? 'https://api.deepseek.com/chat/completions' : 'https://api.groq.com/openai/v1/chat/completions';
    const apiKey = DEEPSEEK_KEY || GROQ_KEY;
    const model = DEEPSEEK_KEY ? 'deepseek-chat' : 'llama-3.3-70b-versatile';
    const r = await fetch(apiUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
      body: JSON.stringify({ model, max_tokens: 200, messages: prompt }),
    });
    const d = await r.json();
    const raw = d.choices?.[0]?.message?.content?.trim() || '';
    parsed = JSON.parse(raw.replace(/^```json\s*/i, '').replace(/```$/, '').trim());
  } catch (e) {
    console.error('❌ Vendor reply parse failed:', e.message);
  }

  // Determine which order to update
  const orderNum = parsed?.order_num || (recentNudge ? recentNudge.shopify_id : null);
  const orderName = parsed?.order_num ? `#${parsed.order_num}` : (recentNudge?.order_name || null);

  if (!parsed || parsed.type === 'unknown' || !orderNum) {
    await sock.sendMessage(sender, {
      text: `Got your message! 👍 Could you confirm which order you're updating?\n\nFor order status updates, just reply:\n📦 *Shipped:* <AWB number> <courier name>\n⏳ *Delay:* <reason> by <expected date>\n\n_We'll handle the rest!_`
    });
    return;
  }

  if (parsed.type === 'tracking' && parsed.awb) {
    const courier = parsed.courier || 'Not specified';
    const result = await mdb.collection('order_vendor_stage').updateOne(
      { shopify_id: String(orderNum) },
      { $set: { awb: parsed.awb, courier, stage: 'transit', updated_at: new Date().toISOString() } }
    );
    if (result.matchedCount > 0) {
      if (recentNudge) await mdb.collection('wa_vendor_nudges').updateOne({ _id: recentNudge._id }, { $set: { resolved: true } });
      await sock.sendMessage(sender, { text: `✅ Tracking updated for order *${orderName}*!\n\nAWB: *${parsed.awb}*\nCourier: *${courier}*\n\nCustomer will be able to track their order. Thank you! 🙏` });
      await waAdminAlert(`\`\`\`\n▪ C R O S C R O W ▪\nVENDOR TRACKING\n────────────────\nORDER  ${orderName}\nAWB    ${parsed.awb}\nVIA    ${courier}\n────────────────\nSOURCE Vendor WA\n\`\`\``);
    } else {
      await sock.sendMessage(sender, { text: `⚠️ Couldn't find order *${orderName}* in our system. Please check the order number.` });
    }
    return;
  }

  if (parsed.type === 'delay') {
    const reason = parsed.reason || text;
    const eta = parsed.eta || 'Not specified';
    const result = await mdb.collection('order_vendor_stage').updateOne(
      { shopify_id: String(orderNum) },
      { $set: { delay_reason: reason, delay_resolution_date: eta, updated_at: new Date().toISOString() } }
    );
    if (result.matchedCount > 0) {
      if (recentNudge) await mdb.collection('wa_vendor_nudges').updateOne({ _id: recentNudge._id }, { $set: { resolved: true } });
      await sock.sendMessage(sender, { text: `✅ Update saved for order *${orderName}*!\n\nExpected by: *${eta}*\n\nWe'll let the customer know. Thank you for the update! 🙏` });
      await waAdminAlert(`\`\`\`\n▪ C R O S C R O W ▪\nVENDOR DELAY\n────────────────\nORDER  ${orderName}\nREASON ${reason}\nETA    ${eta}\n────────────────\nSOURCE Vendor WA\n\`\`\``);
    } else {
      await sock.sendMessage(sender, { text: `⚠️ Couldn't find order *${orderName}* in our system. Please check the order number.` });
    }
    return;
  }

  await sock.sendMessage(sender, {
    text: `Got your message! 👍 Could you confirm which order you're updating?\n\nFor order status updates, just reply:\n📦 *Shipped:* <AWB number> <courier name>\n⏳ *Delay:* <reason> by <expected date>\n\n_We'll handle the rest!_`
  });
}

async function waVendorNudge(meta, customerPhone) {
  if (!waSocket || !mdb) return;
  if (meta?.type !== 'tracking_card') return;
  const d = meta.data;
  if (!d.order_name) return;

  const STUCK_STAGES = ['confirmed', 'hold', 'partial', 'new'];
  const now = Date.now();
  const vendorStages = await mdb.collection('order_vendor_stage').find(
    { shopify_id: String(d.shopify_order_id), stage: { $in: STUCK_STAGES } }
  ).toArray();

  for (const vs of vendorStages) {
    const hoursStuck = vs.stage_started_at ? (now - vs.stage_started_at) / 3600000 : 0;
    if (hoursStuck < 24) continue;
    const dedupKey = `${vs.shopify_id}:${vs.vendor_name}`;
    const recent = await mdb.collection('wa_vendor_nudges').findOne({ key: dedupKey, sent_at: { $gt: now - 86400000 } });
    if (recent) continue;

    // Fetch vendor's phone from their profile (set in Settings → Vendor Profiles)
    const vendorProfile = await mdb.collection('vendor_profiles').findOne(
      { vendor_name: vs.vendor_name },
      { projection: { phone: 1, _id: 0 } }
    );
    const rawVendorPhone = (vendorProfile?.phone || '').replace(/\D/g, '').replace(/^91/, '').slice(-10);
    const VENDOR_WA = rawVendorPhone.length === 10 ? rawVendorPhone
                    : (process.env.WHATSAPP_VENDOR_NUDGE_NUMBER || '');
    if (!VENDOR_WA) {
      console.log(`⚠️  No WhatsApp number for vendor "${vs.vendor_name}" — skipping nudge`);
      continue;
    }

    const days = Math.floor(hoursStuck / 24);
    const orderRef = d.order_name.replace(/^#/, '');
    const customerName = d.customer_name || '';
    const customerMobile = customerPhone ? `+91${customerPhone}` : '';
    const productNames = (d.items || []).filter(i => !i.vendor || i.vendor === vs.vendor_name).map(i => i.title || i.name).filter(Boolean).join(', ') || 'your item';
    // Generate magic link token for no-login form update
    const updateToken = mdb ? await createVendorUpdateToken(d.shopify_order_id, d.order_name, vs.vendor_name, productNames).catch(() => null) : null;
    const updateLink = updateToken ? `\n\n🔗 *Quick update (no login):*\n${SERVER_BASE}/vendor/update/${updateToken}` : '';
    const _Fndg2 = '```';
    const nudgeMsg = `${_Fndg2}\n▪ C R O S C R O W ▪\nACTION REQUIRED\n────────────────\nORDER  ${d.order_name}\nITEM   ${productNames}\nSTUCK  ${days} day${days > 1 ? 's' : ''} unshipped\n────────────────\nSUBMIT UPDATE HERE\n${updateToken ? `dashboard.croscrow.com/vendor/update/${updateToken}` : 'Log in to vendor portal'}\n${_Fndg2}`;

    try {
      const jid = `91${VENDOR_WA}@s.whatsapp.net`;
      const sent = await waSocket.sendMessage(jid, { text: nudgeMsg });
      // Capture the actual JID Baileys used — may differ from the phone JID (LID routing)
      const actualJid = sent?.key?.remoteJid || jid;
      if (actualJid !== jid || true) {
        await mdb.collection('wa_vendor_jids').updateOne(
          { phone: VENDOR_WA },
          { $set: { phone: VENDOR_WA, jid: actualJid, updated_at: new Date().toISOString() } },
          { upsert: true }
        ).catch(() => {});
      }
      // Store session so vendor's "1" or "2" reply maps to this order
      await waVendorSessionSet(actualJid, jid, { type: 'vendor_menu', order_name: d.order_name, shopify_id: String(d.shopify_order_id), orderRef, vendor: vs.vendor_name });
      await mdb.collection('wa_vendor_nudges').insertOne({ key: dedupKey, order_name: d.order_name, shopify_id: String(d.shopify_order_id), vendor: vs.vendor_name, customer_phone: customerPhone, sent_at: now });
      console.log(`📲 Vendor nudge sent for ${d.order_name} (${vs.vendor_name}) — ${Math.round(hoursStuck)}h stuck`);
    } catch (e) {
      waLogVendorSendFailure(vs.vendor_name, VENDOR_WA, 'stuck_order_nudge', d.order_name, e).catch(()=>{});
    }
  }
}

// ── Vendor WA chat logger ──────────────────────────────────────────────────
async function waLogVendorMessage(senderJid, vendorName, role, text) {
  if (!mdb) return;
  const now = new Date().toISOString();
  // Upsert a chat thread per vendor
  const existing = await mdb.collection('vendor_wa_chats').findOne({ vendor_name: vendorName });
  let chatId;
  if (existing) {
    chatId = existing._id;
    await mdb.collection('vendor_wa_chats').updateOne(
      { _id: chatId },
      { $set: { updated_at: now, last_message: text, last_message_from: role },
        $inc: { [role === 'vendor' ? 'vendor_msg_count' : 'bot_msg_count']: 1 } }
    );
  } else {
    const r = await mdb.collection('vendor_wa_chats').insertOne({
      vendor_name: vendorName, jid: senderJid,
      created_at: now, updated_at: now,
      last_message: text, last_message_from: role,
      vendor_msg_count: role === 'vendor' ? 1 : 0,
      bot_msg_count: role === 'bot' ? 1 : 0,
    });
    chatId = r.insertedId;
  }
  await mdb.collection('vendor_wa_messages').insertOne({
    chat_id: String(chatId), vendor_name: vendorName, role, text, created_at: now
  });
}

// ── Session state per sender (4 hour TTL) ─────────────────────────────────
async function waSessionGet(sender) {
  const doc = await mdb.collection('whatsapp_sessions').findOne({ _id: sender });
  if (!doc || Date.now() > doc.expiresAt) return {};
  return doc.data || {};
}
async function waSessionSet(sender, data) {
  await mdb.collection('whatsapp_sessions').updateOne(
    { _id: sender },
    { $set: { data, expiresAt: Date.now() + 4 * 60 * 60 * 1000 } }, // 4 hour TTL
    { upsert: true }
  );
}
// Store vendor session under both the actual JID and the plain phone JID so LID replies match
async function waVendorSessionSet(actualJid, phoneJid, data) {
  await waSessionSet(actualJid, data);
  if (phoneJid && phoneJid !== actualJid) await waSessionSet(phoneJid, data);
  // Also store under any cached LID for this vendor phone
  const phone = phoneJid.replace('91','').replace('@s.whatsapp.net','');
  const cached = await mdb.collection('wa_vendor_jids').findOne({ phone }).catch(()=>null);
  if (cached?.jid && cached.jid !== actualJid && cached.jid !== phoneJid) await waSessionSet(cached.jid, data);
}
async function waSessionClear(sender) {
  await mdb.collection('whatsapp_sessions').deleteOne({ _id: sender });
}

// ── Alert admin on WhatsApp ────────────────────────────────────────────────
const WA_ADMIN_NO = process.env.WHATSAPP_ADMIN_NUMBER || '8209544626';
const WA_ADMIN_CODE = process.env.WHATSAPP_ADMIN_CODE || '4626';

// ── Staff WA notification broadcast ──────────────────────────────────────────
// Topics: 'order_ticket' | 'stuck_orders' | 'dispatch_alert' | 'support_escalation' | 'digest'
async function notifyStaff(topic, message) {
  if (!mdb || !waSocket) return;
  try {
    const staffList = await mdb.collection('staff_accounts').find(
      { wa_phone: { $exists: true, $ne: '' } },
      { projection: { wa_phone: 1, wa_topics: 1, name: 1 } }
    ).toArray();
    for (const s of staffList) {
      const topics = s.wa_topics || ['order_ticket','stuck_orders','dispatch_alert','support_escalation','digest'];
      if (!topics.includes(topic)) continue;
      const raw = (s.wa_phone || '').replace(/\D/g,'').replace(/^91/,'').slice(-10);
      if (raw.length !== 10) continue;
      const jid = `91${raw}@s.whatsapp.net`;
      waSocket.sendMessage(jid, { text: message }).catch(e => console.error(`Staff WA notify failed (${s.name}):`, e.message));
    }
  } catch (e) {
    console.error('notifyStaff error:', e.message);
  }
}

async function waAdminSessionSet(sender) {
  // Admin mode stored separately with no expiry — persists until explicitly cleared
  await mdb.collection('wa_admin_sessions').updateOne(
    { _id: sender },
    { $set: { active: true, set_at: new Date().toISOString() } },
    { upsert: true }
  );
}
async function waAdminSessionCheck(sender) {
  const doc = await mdb.collection('wa_admin_sessions').findOne({ _id: sender });
  return !!doc?.active;
}

async function waLogVendorSendFailure(vendor, phone, type, orderName, error) {
  if (!mdb) return;
  try {
    await mdb.collection('wa_vendor_send_failures').insertOne({
      vendor, phone: phone || null, type, order_name: orderName || null,
      error: (error?.message || String(error)).slice(0, 300),
      failed_at: new Date().toISOString(),
    });
    console.error(`❌ WA vendor send failure logged: ${vendor} / ${type} / ${orderName || ''} — ${error?.message || error}`);
  } catch (_) {}
}

async function waAdminAlert(message, staffTopic = null) {
  if (!waSocket) return;
  try {
    // Prefer the resolved JID from DB (handles LID-based accounts on newer WA)
    let adminJidDoc = await mdb.collection('wa_admin_jids').findOne({ phone: WA_ADMIN_NO }).catch(() => null);
    if (!adminJidDoc?.jid) {
      // Live-resolve the JID and cache it for next time
      const [aRes] = await waSocket.onWhatsApp(`91${WA_ADMIN_NO}`).catch(() => []) || [];
      if (aRes?.jid) {
        await mdb.collection('wa_admin_jids').updateOne(
          { phone: WA_ADMIN_NO },
          { $set: { phone: WA_ADMIN_NO, jid: aRes.jid, updated_at: new Date().toISOString() } },
          { upsert: true }
        ).catch(() => {});
        adminJidDoc = { jid: aRes.jid };
      }
    }
    const jid = adminJidDoc?.jid || `91${WA_ADMIN_NO}@s.whatsapp.net`;
    await waSocket.sendMessage(jid, { text: message });
    if (staffTopic) notifyStaff(staffTopic, message).catch(()=>{});
  } catch (e) { console.error('❌ Admin alert failed:', e.message); }
}

// Look up customer name + most recent order name from order_meta by phone
async function waLookupCustomer(phone) {
  if (!mdb || !phone) return { name: '', order_name: '' };
  const digits = String(phone).replace(/\D/g, '').replace(/^91/, '').slice(-10);
  if (digits.length !== 10) return { name: '', order_name: '' };
  const meta = await mdb.collection('order_meta').findOne(
    { customer_phone: { $regex: digits } },
    { projection: { customer_name: 1, order_name: 1, _id: 0 }, sort: { created_at: -1 } }
  );
  return { name: meta?.customer_name || '', order_name: meta?.order_name || '' };
}

// Send a WhatsApp message to a customer by their phone number (Indian, 10-digit)
async function waSendToCustomer(phone, message) {
  if (!waSocket || !waConnected) return;
  if (!phone) return;
  const digits = String(phone).replace(/\D/g, '').replace(/^91/, '').slice(-10);
  if (digits.length !== 10) return;
  try { await waSocket.sendMessage(`91${digits}@s.whatsapp.net`, { text: message }); }
  catch (e) { console.error('❌ waSendToCustomer failed:', e.message); }
}

// ── Admin WhatsApp AI — routes admin messages to Jarvis with waMode formatting ─

// ── Admin Order Ticket helpers ────────────────────────────────────────────────

function parseAdminOrderIssue(text) {
  const orderMatch = text.match(/(?:order\s*#?|#)?(\d{3,6})/i);
  if (!orderMatch) return null;
  const order_num = orderMatch[1];

  const t = text.toLowerCase();

  // "ticket" keyword = explicit intent — always create, no signal check needed
  const explicitTicket = /\bticket\b/.test(t);

  // Otherwise must have at least one issue signal word so normal order queries
  // like "status of 2612" don't accidentally create tickets
  const hasIssueSignal = explicitTicket || /not\s+dispatch|unship|not\s+ship|pending\s+dispatch|dispatch|delay|late|slow|lost|missing|not\s+received|not\s+delivered|return|refund|rto|wrong|incorrect|pending|stuck|no\s+update|no\s+movement|days|week|issue|problem|kyun|kyu|nahi|nhi|kab|abhi|still|hold|cancel/.test(t);
  if (!hasIssueSignal) return null;

  // Vendor name: word(s) before "in/for <order_num>"
  let vendor_name = null;
  const vendorInMatch = text.match(/^([\w\s]+?)\s+(?:in|for)\s+(?:order\s*#?)?\d+/i);
  if (vendorInMatch) {
    const candidate = vendorInMatch[1].trim().toLowerCase();
    if (candidate.split(' ').length <= 3 && !/not|is|are|has|was|still|been/.test(candidate)) {
      vendor_name = vendorInMatch[1].trim();
    }
  }

  // Issue type + priority — Hindi keywords included
  let issue_type = 'stuck';
  let priority = 'medium';
  if (/not\s+dispatch|unship|not\s+ship|pending\s+dispatch|nahi\s+bheja|nhi\s+bheja/.test(t)) { issue_type = 'not_dispatched'; priority = 'high'; }
  else if (/delay|late|taking\s+long|slow|der|bahut\s+time/.test(t)) { issue_type = 'delayed'; priority = 'medium'; }
  else if (/lost|missing|not\s+received|not\s+delivered|mila\s+nahi/.test(t)) { issue_type = 'lost_in_transit'; priority = 'high'; }
  else if (/exchange|return|refund|rto|wapas/.test(t)) { issue_type = 'return_issue'; priority = 'medium'; }
  else if (/wrong|incorrect|different|galat/.test(t)) { issue_type = 'wrong_item'; priority = 'high'; }
  else if (/pending|stuck|no\s+update|no\s+movement|days|week|abhi\s+tak|still/.test(t)) { issue_type = 'stuck'; priority = 'medium'; }
  // explicit ticket with no specific type = keep 'stuck' as default

  return { order_num, vendor_name, issue_type, priority, description: text.trim() };
}

async function handleAdminOrderTicket(sock, jid, parsed) {
  if (!mdb) return 'Database unavailable.';
  const { order_num, vendor_name, issue_type, priority, description } = parsed;

  // Exact-match lookup — avoid #2612 matching #26120
  const meta = await mdb.collection('order_meta').findOne(
    { order_name: `#${order_num}` },
    { projection: { order_name: 1, shopify_id: 1, customer_name: 1, customer_phone: 1,
                    delivery_status: 1, vendors: 1, items: 1, stage: 1, shopify_created_at: 1, _id: 0 } }
  );

  const orderName = meta?.order_name || `#${order_num}`;
  const now = new Date().toISOString();

  // Check for duplicate open ticket
  const existingTicket = await mdb.collection('admin_order_tickets').findOne({
    order_name: orderName, issue_type, status: { $ne: 'resolved' }
  });

  let ticketId;
  if (existingTicket) {
    ticketId = existingTicket._id;
    await mdb.collection('admin_order_tickets').updateOne(
      { _id: ticketId },
      { $set: { description, updated_at: now, priority }, $inc: { follow_up_count: 1 } }
    );
  } else {
    const r = await mdb.collection('admin_order_tickets').insertOne({
      order_name: orderName,
      shopify_order_id: meta?.shopify_id || null,
      vendor_name: vendor_name || null,
      issue_type,
      priority,
      description,
      status: 'open',
      follow_up_count: 0,
      vendor_pinged: false,
      created_at: now,
      updated_at: now,
    });
    ticketId = r.insertedId;
  }

  // Notify staff — clean up raw description (strip trailing "create ticket" command words)
  const cleanDesc = description.replace(/\bcreate\s+ticket\b/gi, '').replace(/\s{2,}/g, ' ').trim();
  const staffMsg = `🎫 *Admin Order Ticket ${existingTicket ? 'Updated' : 'Created'}*\n\n📦 Order: *${orderName}*${vendor_name ? `\n🏪 Vendor: ${vendor_name}` : ''}\n📋 Issue: ${issue_type.replace(/_/g,' ')}\n🚨 Priority: ${priority.toUpperCase()}\n\n📝 Context: ${cleanDesc}`;
  notifyStaff('order_ticket', staffMsg).catch(()=>{});

  const ISSUE_LABELS = {
    not_dispatched:'Not dispatched', delayed:'Delayed', lost_in_transit:'Lost in transit',
    return_issue:'Return issue', wrong_item:'Wrong item', stuck:'Stuck', other:'Other',
  };
  const lines = [`🎫 *Ticket ${existingTicket ? 'Updated' : 'Created'}* — *${orderName}*`];
  if (meta?.customer_name) lines.push(`👤 Customer: ${meta.customer_name}${meta.customer_phone ? ` (+91${meta.customer_phone})` : ''}`);
  if (vendor_name) lines.push(`🏪 Vendor: ${vendor_name}`);
  lines.push(`📋 Issue: ${ISSUE_LABELS[issue_type] || issue_type} · Priority: ${priority.toUpperCase()}`);
  if (meta?.stage) lines.push(`📦 Stage in DB: ${meta.stage}`);
  if (meta?.delivery_status) lines.push(`🚚 Courier status: ${meta.delivery_status}`);
  if (!meta) lines.push(`⚠️ Order not found in DB — ticket created but check order number`);

  // Ping relevant vendor on WA
  // Sanity-check vendor_name — AI sometimes fills junk like "Create ticket"
  const isValidVendorName = vendor_name &&
    !/^(create|ticket|order|issue|problem|check|help|update|ping|escalate)/i.test(vendor_name.trim());
  const vendorsToAlert = [];
  if (isValidVendorName) {
    vendorsToAlert.push(vendor_name);
  } else if (meta?.vendors?.length) {
    vendorsToAlert.push(...meta.vendors);
  } else if (meta?.items?.length) {
    const unique = [...new Set(meta.items.map(i => i.vendor).filter(Boolean))];
    vendorsToAlert.push(...unique);
  } else {
    // Fallback: look up vendors via OVS by shopify_id (always use meta's id)
    if (meta?.shopify_id) {
      const ovsList = await mdb.collection('order_vendor_stage').find(
        { shopify_id: String(meta.shopify_id) },
        { projection: { vendor_name: 1, _id: 0 } }
      ).toArray();
      vendorsToAlert.push(...[...new Set(ovsList.map(v => v.vendor_name).filter(Boolean))]);
    }
    // Also try order_meta.vendors as last resort
    if (!vendorsToAlert.length && meta?.vendors?.length) {
      vendorsToAlert.push(...meta.vendors);
    }
  }

  let vendorPinged = false;
  for (const vn of vendorsToAlert) {
    const vp = await mdb.collection('vendor_profiles').findOne({ vendor_name: vn }, { projection: { phone: 1 } });
    const rawPhone = (vp?.phone || '').replace(/\D/g, '').replace(/^91/, '').slice(-10);
    if (rawPhone.length !== 10) continue;
    const vjid = `91${rawPhone}@s.whatsapp.net`;

    // Enrich vendor message with real order context from snapshot
    const vendorItems = (meta?.items || []).filter(i => !i.vendor || i.vendor === vn);
    const itemNames = vendorItems.length ? vendorItems.map(i => `• ${i.title}${i.variant_title && i.variant_title !== 'Default Title' ? ` (${i.variant_title})` : ''} × ${i.qty}`).join('\n') : '';

    // Days stuck from OVS if available
    const ovs = await mdb.collection('order_vendor_stage').findOne(
      { shopify_id: String(meta?.shopify_id || ''), vendor_name: vn },
      { projection: { stage: 1, stage_started_at: 1 } }
    ).catch(() => null);
    const daysStuck = ovs?.stage_started_at ? Math.floor((Date.now() - ovs.stage_started_at) / 86400000) : null;

    const urgencyLine = priority === 'high' ? '🚨 *URGENT — Immediate Action Required*' : '⚠️ *Action Required*';

    // Generate a no-login vendor update token for the form link
    const updateToken = await createVendorUpdateToken(
      meta?.shopify_id || orderName, orderName, vn, '', issue_type
    ).catch(() => null);
    const formLink = updateToken ? `${SERVER_URL}/vendor/update/${updateToken}` : null;

    const issueLabel = {
      not_dispatched: 'Order has not been dispatched yet',
      delayed: 'Order dispatch is delayed',
      return_issue: 'Return/Exchange pickup pending',
      lost_in_transit: 'Item appears lost in transit',
      wrong_item: 'Wrong item may have been packed',
      damaged: 'Item reported as damaged',
      missing_item: 'Item is missing from the order',
      stuck: 'Order requires attention',
      other: 'Issue flagged on this order',
    }[issue_type] || issue_type.replace(/_/g, ' ');

    // AI-rephrase the raw admin note into clean professional vendor context
    let contextNote = '';
    try {
      const rawNote = description.replace(/\bcreate\s+ticket\b/gi, '').replace(/\b\d{3,5}\b/g, '').replace(/\s{2,}/g, ' ').trim();
      if (rawNote.length > 8) {
        let rephrased = null;
        if (DEEPSEEK_KEY) {
          const resp = await fetch('https://api.deepseek.com/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${DEEPSEEK_KEY}` },
            body: JSON.stringify({
              model: 'deepseek-chat',
              max_tokens: 80,
              messages: [
                { role: 'system', content: 'You are a professional operations assistant. Rephrase the admin note into one clear, polite sentence suitable for a vendor. Remove any command-like words (like "create ticket"). Return only the rephrased sentence, no quotes.' },
                { role: 'user', content: rawNote },
              ],
            }),
          });
          const rd = await resp.json();
          rephrased = rd?.choices?.[0]?.message?.content?.trim() || null;
        }
        contextNote = `\n📝 *Context:* ${rephrased || rawNote}`;
      }
    } catch (_) {}

    const actionLine = issue_type === 'return_issue'
      ? 'Please ensure the return/exchange pickup is arranged at the earliest and update us with the status.'
      : 'Kindly update the order status at the earliest. If already shipped, share the AWB and courier details.';

    const replyOptions = issue_type === 'return_issue'
      ? `*1️⃣* — Pickup scheduled (share date/courier)\n*2️⃣* — Already picked up (share details)\n*3️⃣* — Need assistance from CROSCROW`
      : `*1️⃣* — Delayed (share reason + expected dispatch date)\n*2️⃣* — Already shipped (share AWB + courier)\n*3️⃣* — Need assistance from CROSCROW`;

    const _Fvp = '```';
    const _vpDaysLine = daysStuck !== null ? `PENDING  ${daysStuck} day${daysStuck !== 1 ? 's' : ''}\n` : '';
    const _vpCustLine = meta?.customer_name ? `CUSTOMER ${meta.customer_name}\n` : '';
    const _vpItemsLine = itemNames ? `ITEMS    ${itemNames.replace(/\n/g, ', ')}\n` : '';
    const _vpReplyOpts = issue_type === 'return_issue'
      ? `1 — Pickup scheduled (date + courier)\n2 — Already picked up\n3 — Need CROSCROW help`
      : `1 — Delayed (reason + ETA)\n2 — Shipped (AWB + courier)\n3 — Need CROSCROW help`;
    const vendorMsg = `${_Fvp}\n▪ C R O S C R O W ▪\n${urgencyLine.toUpperCase()}\n────────────────\nORDER    ${orderName}\nISSUE    ${issueLabel}\n${_vpDaysLine}${_vpCustLine}${_vpItemsLine}────────────────\n${_vpReplyOpts}\n${formLink ? `────────────────\nUPDATE HERE (no login)\n${formLink}` : ''}\n${_Fvp}`;
    try {
      const sent = await waSocket.sendMessage(vjid, { text: vendorMsg });
      const actualJid = sent?.key?.remoteJid || vjid;
      await waLogVendorMessage(actualJid, vn, 'bot', vendorMsg);
      // Set session so vendor 1/2/3 reply routes correctly
      await waSessionSet(actualJid, {
        type: 'support_vendor_reply',
        order_name: orderName,
        shopify_id: String(meta?.shopify_id || ''),
        vendor: vn,
        query_context: { type: issue_type, label: issueLabel, emoji: '📋' },
        form_link: formLink,
        chat_id: null,
      });
      await mdb.collection('wa_vendor_jids').updateOne(
        { phone: rawPhone },
        { $set: { phone: rawPhone, jid: actualJid, updated_at: new Date().toISOString() } },
        { upsert: true }
      ).catch(() => {});
      await mdb.collection('admin_order_tickets').updateOne({ _id: ticketId }, { $set: { vendor_pinged: true, vendor_pinged_at: new Date().toISOString() } });
      vendorPinged = true;
      lines.push(`\n📲 Vendor *${vn}* pinged on WhatsApp`);
    } catch (e) {
      lines.push(`\n⚠️ Could not ping vendor ${vn}: ${e.message}`);
    }
  }

  if (!vendorPinged && vendorsToAlert.length === 0) {
    lines.push('\n⚠️ No vendor found — check order number or assign manually');
  }

  lines.push(`\n────────────────`);
  lines.push(`*!resolve ${order_num}* → close this ticket once issue is fixed`);
  lines.push(`*!tickets* → see all open tickets`);
  return lines.join('\n');
}

async function adminStuckOrdersReport() {
  if (!mdb) return 'Database unavailable.';
  const STUCK_STAGES = ['confirmed', 'processing', 'packed'];
  const cutoff = Date.now() - 24 * 3600000;
  const stuckRows = await mdb.collection('order_vendor_stage').find({
    stage: { $in: STUCK_STAGES },
    stage_started_at: { $lt: cutoff },
  }).sort({ stage_started_at: 1 }).limit(20).toArray();

  if (!stuckRows.length) return '✅ No stuck orders right now — all good!';

  // Resolve order_name from order_meta for rows that only have shopify_id
  const missingNames = stuckRows.filter(r => !r.order_name).map(r => String(r.shopify_id));
  const metaMap = {};
  if (missingNames.length) {
    const metas = await mdb.collection('order_meta').find({ shopify_id: { $in: missingNames } }, { projection: { shopify_id: 1, order_name: 1, _id: 0 } }).toArray();
    for (const m of metas) metaMap[m.shopify_id] = m.order_name;
  }

  const lines = [`🚨 *Stuck Orders (${stuckRows.length})*\n`];
  for (const r of stuckRows) {
    const hrs = Math.round((Date.now() - r.stage_started_at) / 3600000);
    const label = r.order_name || metaMap[String(r.shopify_id)] || r.shopify_id;
    lines.push(`• *${label}* — ${r.vendor_name} | ${r.stage} | ${hrs}h`);
  }
  lines.push(`\nSend *"<vendor> in <order#> not dispatched"* to create a ticket and ping vendor.`);
  return lines.join('\n');
}

async function adminMorningDigest(sock, adminJid) {
  if (!mdb || !sock) return;
  try {
    const STUCK_STAGES = ['confirmed', 'processing', 'packed'];
    const cutoff24h = Date.now() - 24 * 3600000;
    const cutoff48h = Date.now() - 48 * 3600000;

    const [stuck24, stuck48, openTickets, openChats] = await Promise.all([
      mdb.collection('order_vendor_stage').countDocuments({ stage: { $in: STUCK_STAGES }, stage_started_at: { $lt: cutoff24h } }),
      mdb.collection('order_vendor_stage').countDocuments({ stage: { $in: STUCK_STAGES }, stage_started_at: { $lt: cutoff48h } }),
      mdb.collection('admin_order_tickets').countDocuments({ status: { $ne: 'resolved' } }),
      mdb.collection('support_chats').countDocuments({ needs_human: true, resolved: { $ne: true } }),
    ]);

    const topStuck = await mdb.collection('order_vendor_stage').find(
      { stage: { $in: STUCK_STAGES }, stage_started_at: { $lt: cutoff48h } }
    ).sort({ stage_started_at: 1 }).limit(5).toArray();

    // Resolve order_name from order_meta for any urgent rows missing it
    const urgentMissingNames = topStuck.filter(r => !r.order_name).map(r => String(r.shopify_id));
    const urgentMetaMap = {};
    if (urgentMissingNames.length) {
      const ums = await mdb.collection('order_meta').find({ shopify_id: { $in: urgentMissingNames } }, { projection: { shopify_id: 1, order_name: 1, _id: 0 } }).toArray();
      for (const m of ums) urgentMetaMap[m.shopify_id] = m.order_name;
    }
    const urgentLines = topStuck.map(r => {
      const hrs = Math.round((Date.now() - r.stage_started_at) / 3600000);
      const label = r.order_name || urgentMetaMap[String(r.shopify_id)] || r.shopify_id;
      return `  • *${label}* (${r.vendor_name}) — ${hrs}h in ${r.stage}`;
    });

    const now = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', hour: '2-digit', minute: '2-digit' });
    const msg =
`🌅 *CROSCROW Morning Digest* — ${now} IST

📦 Orders stuck >24h: *${stuck24}*
🚨 Orders stuck >48h: *${stuck48}*
🎫 Open admin tickets: *${openTickets}*
💬 Escalated support chats: *${openChats}*
${urgentLines.length ? `\n*Most Urgent (48h+):*\n${urgentLines.join('\n')}` : ''}

Use *!stuck* for full list · *!tickets* for tickets · *!digest* to refresh`;

    await sock.sendMessage(adminJid, { text: msg });
    notifyStaff('digest', msg).catch(()=>{});
  } catch (e) {
    console.error('adminMorningDigest error:', e.message);
  }
}

async function waHandleAdminQuery(sock, sender, text) {
  if (!mdb) return;
  try {
    // ── Admin resolve shortcut — "👍 / sorted / done / resolved / handled / ✅" ──
    const ADMIN_RESOLVE = /^(👍|✅|sorted|done|resolved|handled|close|closed|complete|finished|ok done|ho gaya|theek hai|kr do close|resolve kr do)[\s!.]*$/i;
    if (ADMIN_RESOLVE.test(text.trim())) {
      const pending = await mdb.collection('support_chats').find(
        { needs_human: true, resolved: { $ne: true }, source: { $ne: 'wa_admin' } },
        { projection: { _id: 1, order_name: 1, customer_phone: 1, updated_at: 1 } }
      ).sort({ updated_at: -1 }).limit(5).toArray();

      if (!pending.length) {
        await sock.sendMessage(sender, { text: '✅ No open escalated chats right now — all clear!' });
        return;
      }

      if (pending.length === 1) {
        const c = pending[0];
        await mdb.collection('support_chats').updateOne(
          { _id: c._id },
          { $set: { resolved: true, status: 'resolved', resolved_at: new Date().toISOString(), updated_at: new Date().toISOString() } }
        );
        const label = c.order_name || c.customer_phone || String(c._id);
        await sock.sendMessage(sender, { text: `✅ Chat resolved — *${label}*` });
        return;
      }

      // Multiple pending — list them, admin replies with number
      const lines = pending.map((c, i) => {
        const label = c.order_name || c.customer_phone || String(c._id);
        const ago = Math.round((Date.now() - new Date(c.updated_at).getTime()) / 60000);
        return `${i + 1}️⃣ ${label} (${ago}m ago)`;
      });
      await sock.sendMessage(sender, {
        text: `You have *${pending.length}* open escalated chats:\n\n${lines.join('\n')}\n\nReply with a number to resolve that one, or *"sorted all"* to close all.`
      });
      await waSessionSet(sender, { type: 'admin_resolve_pick', chats: pending.map(c => ({ id: String(c._id), label: c.order_name || c.customer_phone || String(c._id) })) });
      return;
    }

    // ── Admin Order Tracker Commands ─────────────────────────────────────────
    const trimmed = text.trim();

    // !stuck — list all stuck orders right now
    if (/^!stuck$/i.test(trimmed)) {
      await sock.sendMessage(sender, { text: '🔍 Fetching stuck orders...' });
      const report = await adminStuckOrdersReport();
      await sock.sendMessage(sender, { text: report });
      return;
    }

    // !tickets — list open admin order tickets
    if (/^!tickets$/i.test(trimmed)) {
      const tix = await mdb.collection('admin_order_tickets').find({ status: { $ne: 'resolved' } }).sort({ created_at: -1 }).limit(10).toArray();
      if (!tix.length) { await sock.sendMessage(sender, { text: '✅ No open order tickets — all clear!' }); return; }
      const lines = tix.map((t, i) => {
        const age = Math.round((Date.now() - new Date(t.created_at).getTime()) / 3600000);
        const icon = t.priority === 'high' ? '🔴' : t.priority === 'medium' ? '🟡' : '🟢';
        return `${icon} *${t.order_name}*${t.vendor_name ? ` (${t.vendor_name})` : ''}\n   ${t.issue_type} · ${age}h ago\n   ${t.description}`;
      });
      await sock.sendMessage(sender, { text: `📋 *Open Order Tickets (${tix.length})*\n\n${lines.join('\n\n')}` });
      return;
    }

    // !resolve #XXXX or !resolve 2588 — resolve ticket by order number
    const resolveMatch = trimmed.match(/^!resolve\s+#?(\d+)/i);
    if (resolveMatch) {
      const orderNum = resolveMatch[1];
      const res = await mdb.collection('admin_order_tickets').updateMany(
        { order_name: { $regex: orderNum }, status: { $ne: 'resolved' } },
        { $set: { status: 'resolved', resolved_at: new Date().toISOString() } }
      );
      await sock.sendMessage(sender, { text: res.modifiedCount > 0 ? `✅ Resolved ${res.modifiedCount} ticket(s) for order *#${orderNum}*` : `⚠️ No open tickets found for order #${orderNum}` });
      return;
    }

    // !watch #XXXX [notes] — watch an order, get auto-updates
    const watchMatch = trimmed.match(/^!watch\s+#?(\d+)(.*)$/i);
    if (watchMatch) {
      const orderNum = watchMatch[1];
      const notes = watchMatch[2].trim();
      await mdb.collection('admin_order_tickets').updateOne(
        { order_name: { $regex: orderNum }, status: { $ne: 'resolved' } },
        { $set: { watched: true, watch_notes: notes, updated_at: new Date().toISOString() } }
      );
      await sock.sendMessage(sender, { text: `👁️ Watching order *#${orderNum}* — you'll get updates when status changes.${notes ? `\n📝 Notes: ${notes}` : ''}` });
      return;
    }

    // !digest — trigger manual morning digest
    if (/^!digest$/i.test(trimmed)) {
      await sock.sendMessage(sender, { text: '📊 Generating digest...' });
      await adminMorningDigest(sock, sender);
      return;
    }

    // Natural language order issue detection
    // Matches: "2588 is not dispatched", "fitcheck pants in 2578 pending", "#2588 stuck"
    const orderIssueMatch = trimmed.match(/(?:order\s*#?|#)?(\d{3,6})/i);
    if (orderIssueMatch && trimmed.length > 4) {
      const parsed = parseAdminOrderIssue(trimmed);
      if (parsed) {
        await sock.sendMessage(sender, { text: `🎫 On it! Creating ticket for order *#${parsed.order_num}*...` });
        const result = await handleAdminOrderTicket(sock, sender, parsed);
        await sock.sendMessage(sender, { text: result });
        return;
      }
    }

    // Admin picks which chat to resolve from the list above
    const adminSession = await waSessionGet(sender);
    if (adminSession?.type === 'admin_resolve_pick') {
      const { chats } = adminSession;
      const ALL = /^sorted all$/i.test(text.trim());
      const num = parseInt(text.trim());
      const targets = ALL ? chats : (num >= 1 && num <= chats.length ? [chats[num - 1]] : []);
      if (targets.length) {
        const { ObjectId } = require('mongodb');
        for (const t of targets) {
          await mdb.collection('support_chats').updateOne(
            { _id: new ObjectId(t.id) },
            { $set: { resolved: true, status: 'resolved', resolved_at: new Date().toISOString(), updated_at: new Date().toISOString() } }
          );
        }
        const labels = targets.map(t => `*${t.label}*`).join(', ');
        await sock.sendMessage(sender, { text: `✅ Resolved: ${labels}` });
        await waSessionClear(sender);
        return;
      }
      // Not a valid pick — fall through to Jarvis
      await waSessionClear(sender);
    }

    // Maintain a rolling history per admin session (last 10 exchanges)
    let chat = await mdb.collection('support_chats').findOne({ whatsapp_sender: sender, source: 'wa_admin' });
    if (!chat) {
      const r = await mdb.collection('support_chats').insertOne({
        whatsapp_sender: sender, source: 'wa_admin', customer_phone: WA_ADMIN_NO,
        created_at: new Date().toISOString(), updated_at: new Date().toISOString(),
      });
      chat = { _id: r.insertedId, whatsapp_sender: sender };
    }
    await SC.addMessage(chat._id, { sender: 'customer', text });

    // Build history in Jarvis format
    const msgs = (await SC.messages(chat._id)).slice(-20);
    const history = msgs.slice(0, -1).map(m => ({
      role: m.sender === 'customer' ? 'user' : 'bot',
      text: m.text,
    }));

    const result = await runJarvisQuery(text, history, { waMode: true });
    let reply = (result?.reply || '').trim();
    // Strip any leftover markdown bold/headers for WhatsApp
    reply = reply.replace(/\*\*(.+?)\*\*/g, '$1').replace(/#{1,3} /g, '');
    if (!reply) reply = "I didn't get a response — try asking again or check the dashboard.";

    await SC.addMessage(chat._id, { sender: 'assistant', text: reply });
    await mdb.collection('support_chats').updateOne({ _id: chat._id }, { $set: { updated_at: new Date().toISOString() } });
    await sock.sendMessage(sender, { text: reply });
  } catch (e) {
    console.error('❌ Admin WA query failed:', e.message);
    await sock.sendMessage(sender, { text: 'Error fetching data. Try again in a moment.' });
  }
}

// ── Send product images one by one ────────────────────────────────────────
async function waSendProductImages(sock, sender, products) {
  const list = products.slice(0, 3);
  for (let i = 0; i < list.length; i++) {
    const p = list[i];
    const priceStr = p.price_from ? `₹${Math.round(p.price_from)}` : '';
    const caption = [
      `*${p.title}*`,
      priceStr ? `💰 ${priceStr}` : '',
      p.url ? `🛍️ Shop now: ${p.url}` : '',
    ].filter(Boolean).join('\n');
    try {
      if (p.image) {
        await sock.sendMessage(sender, { image: { url: p.image }, caption });
      } else {
        await sock.sendMessage(sender, { text: caption });
      }
      await new Promise(r => setTimeout(r, 800));
    } catch (e) {
      // Image fetch failed — fall back to text card
      try { await sock.sendMessage(sender, { text: caption }); } catch {}
    }
  }
}

// ── Hours since order was confirmed ───────────────────────────────────────
async function waHoursConfirmed(shopifyOrderId) {
  if (!shopifyOrderId || !mdb) return 0;
  const vs = await mdb.collection('order_vendor_stage').findOne(
    { shopify_id: String(shopifyOrderId), stage: { $in: ['confirmed', 'partial'] } },
    { sort: { stage_started_at: 1 } }
  );
  return vs?.stage_started_at ? (Date.now() - vs.stage_started_at) / 3600000 : 0;
}

// ── Vendor delay reason + ETA from DB ─────────────────────────────────────
async function waDelayReason(shopifyOrderId) {
  if (!shopifyOrderId || !mdb) return null;
  const vs = await mdb.collection('order_vendor_stage').findOne({
    shopify_id: String(shopifyOrderId),
    delay_reason: { $exists: true, $ne: '' },
  });
  if (!vs?.delay_reason) return null;
  return { reason: vs.delay_reason, eta: vs.delay_resolution_date || null };
}

// ── Escalate to human + pause bot ────────────────────────────────────────
// sendCustomerMsg: true = send the handoff line to customer (only on first escalation or explicit request)
// ── Detect issue category from chat tags for ticket classification ────────
function scTicketCategory(chat) {
  const tags = (chat.tags || []).map(t => t.toLowerCase());
  if (tags.some(t => t.includes('exchange') || t.includes('return'))) return 'return_exchange';
  if (tags.some(t => t.includes('refund'))) return 'refund';
  if (tags.some(t => t.includes('delay') || t.includes('dispatch'))) return 'dispatch_delay';
  return 'general';
}

const TICKET_CATEGORY_LABELS = {
  dispatch_delay:  '⏳ Dispatch delay',
  return_exchange: '🔄 Return / Exchange',
  refund:          '💰 Refund',
  general:         '💬 General query',
};

// ── Create support ticket when chat escalates to human ────────────────────
async function createSupportTicket(chat, contextNote) {
  if (!mdb) return null;
  // Only one open ticket per chat
  const existing = await mdb.collection('support_tickets').findOne({ chat_id: String(chat._id), status: { $in: ['open','in_progress','overdue'] } });
  if (existing) return existing;
  const category = scTicketCategory(chat);
  const allMsgs = await SC.messages(chat._id).catch(() => []);
  const custMsgs = allMsgs.filter(m => m.sender === 'customer').slice(-5);
  const lastCust = custMsgs.map(m => (m.text || '').slice(0, 200)).join(' | ');
  const now = new Date().toISOString();
  const slaDeadline = new Date(Date.now() + 8 * 3600000).toISOString(); // 8h SLA
  const r = await mdb.collection('support_tickets').insertOne({
    chat_id: String(chat._id),
    order_name: chat.order_name || null,
    customer_phone: chat.customer_phone || null,
    issue_category: category,
    context_tags: chat.tags || [],
    context_note: contextNote || '',
    last_customer_msg: lastCust.slice(0, 800),
    status: 'open',
    assigned_to: null,
    sla_deadline: slaDeadline,
    reminder_sent_at: null,
    vendor_pinged_at: null,
    created_at: now,
    updated_at: now,
    closed_at: null,
    closed_by: null,
  });
  return { _id: r.insertedId, chat_id: String(chat._id), order_name: chat.order_name, category, sla_deadline: slaDeadline };
}

// ── Close ticket when admin replies or chat resolves ──────────────────────
async function closeSupportTicket(chatId, closedBy = 'admin') {
  if (!mdb) return;
  await mdb.collection('support_tickets').updateOne(
    { chat_id: String(chatId), status: { $in: ['open','in_progress','overdue'] } },
    { $set: { status: 'closed', closed_at: new Date().toISOString(), closed_by: closedBy, updated_at: new Date().toISOString() } }
  );
}

// ── Ticket SLA cron — runs every 30 min ──────────────────────────────────
async function ticketSLACron() {
  if (!mdb) return;
  try {
    const now = Date.now();
    const openTickets = await mdb.collection('support_tickets').find(
      { status: { $in: ['open','in_progress'] } }
    ).toArray();

    for (const t of openTickets) {
      const createdAt = new Date(t.created_at).getTime();
      const slaDeadline = new Date(t.sla_deadline).getTime();
      const label = t.order_name || t.customer_phone || String(t._id);
      const categoryLabel = TICKET_CATEGORY_LABELS[t.issue_category] || '💬 Query';
      const panelLink = `https://dashboard.croscrow.com/admin#supporttickets`;

      // Mark reminder_sent_at silently (no WA message — handled by scheduled digest)
      if (!t.reminder_sent_at && now >= createdAt + 6 * 3600000) {
        await mdb.collection('support_tickets').updateOne(
          { _id: t._id },
          { $set: { reminder_sent_at: new Date().toISOString(), updated_at: new Date().toISOString() } }
        );
      }

      // T+8h — mark overdue (status update only, no individual WA message)
      if (now >= slaDeadline && t.status !== 'overdue') {
        await mdb.collection('support_tickets').updateOne(
          { _id: t._id },
          { $set: { status: 'overdue', updated_at: new Date().toISOString() } }
        );
      }

      // T+12h — ping vendor if dispatch/return issue and not already pinged
      const isVendorIssue = ['dispatch_delay','return_exchange'].includes(t.issue_category);
      if (isVendorIssue && !t.vendor_pinged_at && now >= createdAt + 12 * 3600000) {
        // Find vendor from chat and ping via WA
        const chatDoc = await mdb.collection('support_chats').findOne({ _id: new (require('mongodb').ObjectId)(t.chat_id) }).catch(() => null);
        if (chatDoc?.vendor_names?.length && waSocket && waConnected) {
          for (const vendorName of chatDoc.vendor_names) {
            try {
              const vp = await mdb.collection('vendor_profiles').findOne({ vendor_name: vendorName }, { projection: { phone: 1 } });
              const rawPhone = (vp?.phone || '').replace(/\D/g, '').replace(/^91/, '').slice(-10);
              if (rawPhone.length === 10) {
                const jidDoc = await mdb.collection('wa_vendor_jids').findOne({ phone: rawPhone }).catch(() => null);
                const jid = jidDoc?.jid || `91${rawPhone}@s.whatsapp.net`;
                await waSocket.sendMessage(jid, {
                  text: `🔔 *Follow-up — Order ${t.order_name || ''}*\n\nHi ${vendorName},\n\nA customer query about this order has been open for 12+ hours. Please share an update so we can close this — ${categoryLabel}\n\n_CROSCROW Support_`
                });
              }
            } catch (_) {}
          }
        }
        await mdb.collection('support_tickets').updateOne(
          { _id: t._id },
          { $set: { vendor_pinged_at: new Date().toISOString(), updated_at: new Date().toISOString() } }
        );
      }
    }
  } catch (e) { console.error('ticketSLACron error:', e.message); }
}
setInterval(ticketSLACron, 30 * 60 * 1000); // every 30 min

// ── Pending tickets digest (sent at 9 AM and 12 PM IST) ──────────────────
async function sendTicketDigest(sock, adminJid, label) {
  if (!mdb || !sock || !adminJid) return;
  try {
    const tickets = await mdb.collection('support_tickets').find(
      { status: { $in: ['open', 'in_progress', 'overdue'] } }
    ).sort({ created_at: 1 }).toArray();

    if (!tickets.length) {
      await sock.sendMessage(adminJid, { text: `✅ *${label} — No Pending Tickets*\nAll support tickets are closed. 🎉` });
      return;
    }

    const now = Date.now();
    const overdue = tickets.filter(t => t.status === 'overdue');
    const urgent  = tickets.filter(t => t.status !== 'overdue' && now - new Date(t.created_at).getTime() >= 6 * 3600000);
    const normal  = tickets.filter(t => t.status !== 'overdue' && now - new Date(t.created_at).getTime() < 6 * 3600000);

    const fmtTicket = t => {
      const hrs  = Math.round((now - new Date(t.created_at).getTime()) / 3600000);
      const ref  = t.order_name || t.customer_phone || String(t._id).slice(-6);
      const cat  = TICKET_CATEGORY_LABELS[t.issue_category] || '💬 Query';
      const tags = (t.context_tags || []).filter(Boolean).slice(0, 2).join(', ');
      return `  • *${ref}* — ${cat} · ${hrs}h open${tags ? ` · ${tags}` : ''}`;
    };

    const parts = [];
    if (overdue.length) parts.push(`🚨 *Overdue (${overdue.length}):*\n${overdue.map(fmtTicket).join('\n')}`);
    if (urgent.length)  parts.push(`⏰ *Aging 6h+ (${urgent.length}):*\n${urgent.map(fmtTicket).join('\n')}`);
    if (normal.length)  parts.push(`🟡 *Open (${normal.length}):*\n${normal.map(fmtTicket).join('\n')}`);

    const msg = `🎫 *${label} — Ticket Summary*\nTotal pending: *${tickets.length}*\n\n${parts.join('\n\n')}\n\n🔗 https://dashboard.croscrow.com/admin#supporttickets`;
    await sock.sendMessage(adminJid, { text: msg });
    notifyStaff('ticket_digest', msg).catch(() => {});
  } catch (e) { console.error('sendTicketDigest error:', e.message); }
}

// ── Daily 9 AM IST morning digest + 12 PM ticket digest ──────────────────
let _digestLastSent = 0;
let _noonDigestLastSent = 0;
setInterval(async () => {
  const now = new Date();
  const istH = Math.floor((now.getUTCHours() * 60 + now.getUTCMinutes() + 330) / 60) % 24;
  const istM = (now.getUTCMinutes() + 30) % 60;
  const adminJid = WA_ADMIN_NO ? `91${WA_ADMIN_NO.replace(/\D/g, '').replace(/^91/, '').slice(-10)}@s.whatsapp.net` : null;

  // 9 AM — morning digest + tickets
  if (istH === 9 && istM < 30 && Date.now() - _digestLastSent > 3600000) {
    _digestLastSent = Date.now();
    if (adminJid && waSocket) {
      adminMorningDigest(waSocket, adminJid).catch(e => console.error('Morning digest error:', e.message));
      setTimeout(() => sendTicketDigest(waSocket, adminJid, 'Morning Check-in').catch(() => {}), 5000);
    }
  }

  // 12 PM — noon ticket digest
  if (istH === 12 && istM < 30 && Date.now() - _noonDigestLastSent > 3600000) {
    _noonDigestLastSent = Date.now();
    if (adminJid && waSocket) {
      sendTicketDigest(waSocket, adminJid, 'Afternoon Check-in').catch(e => console.error('Noon digest error:', e.message));
    }
  }
}, 10 * 60 * 1000); // check every 10 min

// ── Dispatch alert cron — every 2h, fires alerts for orders stuck >4 days ──
let _dispatchAlertLastRun = 0;
async function dispatchAlertCron() {
  if (!mdb || !waSocket) return;
  const now = Date.now();
  if (now - _dispatchAlertLastRun < 90 * 60 * 1000) return; // min 90min between runs
  _dispatchAlertLastRun = now;
  try {
    const cutoff4d = now - 4 * 24 * 3600000;
    const STUCK_STAGES = ['confirmed', 'processing', 'packed'];

    // Get all vendor stages stuck >4 days
    const stuckRows = await mdb.collection('order_vendor_stage').find(
      { stage: { $in: STUCK_STAGES }, stage_started_at: { $lt: cutoff4d } }
    ).sort({ stage_started_at: 1 }).limit(30).toArray();

    if (!stuckRows.length) return;

    // Dedup — only fire once per order per day
    const deduped = [];
    for (const r of stuckRows) {
      const key = `dispatch_alert:${r.shopify_id}:${r.vendor_name}`;
      const recent = await mdb.collection('staff_alert_log').findOne({ key, sent_at: { $gt: now - 20 * 3600000 } });
      if (!recent) deduped.push(r);
    }
    if (!deduped.length) return;

    // Enrich with order meta
    const shopifyIds = [...new Set(deduped.map(r => r.shopify_id))];
    const metas = await mdb.collection('order_meta').find(
      { shopify_order_id: { $in: shopifyIds } },
      { projection: { shopify_order_id: 1, order_name: 1, payment_status: 1, partial_payment: 1, customer_name: 1, _id: 0 } }
    ).toArray();
    const metaMap = {};
    for (const m of metas) metaMap[String(m.shopify_order_id)] = m;

    const lines = [];
    for (const r of deduped) {
      const meta = metaMap[String(r.shopify_id)] || {};
      const daysStuck = Math.floor((now - r.stage_started_at) / 86400000);
      const orderRef = meta.order_name || `#${r.shopify_id}`;
      const isPrepaid = meta.payment_status === 'paid' || (!meta.partial_payment);
      const payTag = isPrepaid ? '💳 Prepaid' : '🔶 Partial/COD';
      lines.push(`• *${orderRef}* (${r.vendor_name}) — ${r.stage} ${daysStuck}d | ${payTag}`);
      await mdb.collection('staff_alert_log').updateOne(
        { key: `dispatch_alert:${r.shopify_id}:${r.vendor_name}` },
        { $set: { key: `dispatch_alert:${r.shopify_id}:${r.vendor_name}`, sent_at: now } },
        { upsert: true }
      );
    }

    const msg = `\`\`\`\n▪ C R O S C R O W ▪\nDISPATCH ALERT 🚨\nSTUCK 4+ DAYS (${deduped.length})\n────────────────\n${lines.map(l=>l.replace(/\*/g,'')).join('\n')}\n────────────────\nFollow up or reply !stuck\n\`\`\``;

    await waAdminAlert(msg, 'dispatch_alert');
  } catch (e) {
    console.error('dispatchAlertCron error:', e.message);
  }
}
setInterval(dispatchAlertCron, 2 * 60 * 60 * 1000); // every 2h

function isAngryMessage(text) {
  if (!text) return false;
  // Detect all-caps frustration (5+ consecutive uppercase words)
  if (/([A-Z]{3,}\s+){2,}[A-Z]{3,}/.test(text)) return true;
  return /\b(fraud|scam|scammer|cheater|cheat|cheat|worst|pathetic|useless|ridiculous|disgusting|terrible|horrible|unacceptable|legal action|consumer court|police complaint|sue|lawsuit|immediately|money back|furious|outraged|harassment|blasting|viral|1 star|zero star|0 star|one star|social media|twitter|instagram|very angry|so angry|fed up|had enough|refund.*now|now.*refund|cancel.*immediately|this is a scam|such a scam|will.*complain|going to complain|gonna complain|review.*bad|bad.*review)\b/i.test(text);
}

async function waTalkToHuman(sock, sender, chat, phone, context, { sendCustomerMsg = true, forceMsg = false, humanRequested = true } = {}) {
  const _hci = await waLookupCustomer(phone === 'unknown' ? '' : phone);
  const _hPhone = phone !== 'unknown' ? `+91${phone}` : (_hci.order_name ? `LID — Order ${_hci.order_name}` : null);

  // Pull last 3 customer messages for context
  const _allMsgs = await SC.messages(chat._id).catch(() => []);
  const _lastMsgs = _allMsgs.filter(m => m.sender === 'customer').slice(-3);
  const _chatSnippet = _lastMsgs.length
    ? '\n\n💬 *Last messages:*\n' + _lastMsgs.map(m => `"${(m.text || '').slice(0, 120)}"`).join('\n')
    : '';

  // Detect anger in last customer message even for bot-triggered escalations
  const _lastCustomerText = _lastMsgs.length ? (_lastMsgs[_lastMsgs.length - 1]?.text || '') : '';
  const _isAngry = isAngryMessage(_lastCustomerText);
  const _shouldTicket = humanRequested || _isAngry;

  const _panelLink = `https://dashboard.croscrow.com/admin#supporttickets`;
  const _nameStr = _hci.name ? `Name: *${_hci.name}*\n` : '';
  const _phoneStr = _hPhone ? `Phone: ${_hPhone}\n` : '';
  const _orderStr = _hci.order_name ? `Order: *${_hci.order_name}*\n` : '';
  const _category = TICKET_CATEGORY_LABELS[scTicketCategory(chat)] || '💬 Query';

  if (_shouldTicket) {
    // Human explicitly requested or angry customer — create ticket + transfer
    // Build enriched context note from last customer messages so ticket has real query reason
    const _querySummary = _lastMsgs.length
      ? '\nQuery: ' + _lastMsgs.map(m => `"${(m.text || '').slice(0, 150)}"`).join(' → ')
      : '';
    await createSupportTicket(chat, context + _querySummary).catch(() => null);
    const _angryTag = _isAngry && !humanRequested ? '\n⚠️ ANGRY CUSTOMER' : '';
    await waAdminAlert(`\`\`\`\n▪ C R O S C R O W ▪\nNEW SUPPORT TICKET 🎫\n────────────────\n${_nameStr}${_phoneStr}${_orderStr}TYPE   ${_category}\nSLA    8 hours${_angryTag}\n────────────────\n${context.slice(0, 100)}${_chatSnippet}\n────────────────\nAdmin → Support Tickets\n\`\`\``, 'support_escalation');

    const lastEscalated = chat.last_escalated_at ? new Date(chat.last_escalated_at).getTime() : 0;
    const escalatedRecently = (Date.now() - lastEscalated) < 6 * 3600000;
    if (sendCustomerMsg && (!escalatedRecently || forceMsg)) {
      const nowHour = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Kolkata' })).getHours();
      const offHours = nowHour < 14 || nowHour >= 20;
      const msg = WA_MENUS.support_queue(offHours);
      await sock.sendMessage(sender, { text: msg });
      await SC.addMessage(chat._id, { sender: 'assistant', text: msg });
    }

    const pauseUntil = Date.now() + 4 * 60 * 60 * 1000;
    await mdb.collection('support_chats').updateOne(
      { _id: chat._id },
      { $set: { needs_human: true, status: 'transferred', bot_paused_until: pauseUntil, last_escalated_at: new Date().toISOString(), confused_count: 0, updated_at: new Date().toISOString() } }
    );
  } else {
    // Bot-triggered escalation, customer not angry — alert admin silently, auto-resolve chat
    await waAdminAlert(`\`\`\`\n▪ C R O S C R O W ▪\nBOT ESCALATION\nAUTO-RESOLVED\n────────────────\n${_nameStr}${_phoneStr}${_orderStr}${context.slice(0, 80)}\n\`\`\``, 'support_escalation');
    await mdb.collection('support_chats').updateOne(
      { _id: chat._id },
      { $set: { status: 'resolved', confused_count: 0, updated_at: new Date().toISOString() } }
    );
  }

  await waSessionClear(sender);
}

// ── Log bot confusion insight for analysis ────────────────────────────────
async function waLogConfusionInsight(chat, phone, customerText, botReply, triggerRule, stats) {
  if (!mdb) return;
  try {
    await mdb.collection('wa_confusion_log').insertOne({
      chat_id: String(chat._id),
      customer_phone: phone,
      trigger_rule: triggerRule,          // 'message_count' | 'repeated_keyword' | 'time_limit'
      repeated_keyword: stats.repeatedKeyword || null,
      customer_text: customerText.slice(0, 300),
      bot_reply_preview: botReply.slice(0, 300),
      bot_message_count: stats.botMessages,
      customer_message_count: stats.customerMessages,
      chat_age_minutes: stats.chatAgeMinutes,
      logged_at: new Date().toISOString(),
    });
    // Also tag the support chat so it shows in insights panel
    await mdb.collection('support_chats').updateOne(
      { _id: chat._id },
      { $addToSet: { tags: 'bot_confused' }, $set: { updated_at: new Date().toISOString() } }
    );
  } catch (e) { console.error('waLogConfusionInsight error:', e.message); }
}

